document.querySelectorAll("[data-field]").forEach((field) => {
  const fields = fieldMap.get(field.dataset.field) || [];
  fields.push(field);
  fieldMap.set(field.dataset.field, fields);
});

function setField(name, value) {
  (fieldMap.get(name) || []).forEach((field) => {
    field.textContent = value;
  });
}

function escapeHtml(value = "") {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function createTextElement(tagName, text = "", className = "") {
  const element = document.createElement(tagName);
  if (className) element.className = className;
  element.textContent = text ?? "";
  return element;
}

function createSvgElement(tagName, attributes = {}) {
  const element = document.createElementNS("http://www.w3.org/2000/svg", tagName);
  Object.entries(attributes).forEach(([name, value]) => element.setAttribute(name, String(value)));
  return element;
}

function appendDetailPair(container, label, value, { valueTag = "strong" } = {}) {
  const row = document.createElement("div");
  const labelElement = createTextElement("span", label);
  const valueElement = createTextElement(valueTag, value);
  row.append(labelElement, valueElement);
  container.append(row);
  return row;
}

function createEmptyState(message, className = "security-empty-state") {
  return createTextElement("div", message, className);
}

function freezeAgentStatusSnapshot(snapshot) {
  const metadata = Object.freeze({ ...(snapshot.metadata || {}) });
  return Object.freeze({ ...snapshot, metadata });
}

function normalizeRendererAgentStatus(source = {}, fallback = AGENT_STATUS_FALLBACK) {
  const state = AGENT_STATUS_STATES.includes(source.state) ? source.state : fallback.state;
  return freezeAgentStatusSnapshot({
    ...AGENT_STATUS_FALLBACK,
    ...fallback,
    ...source,
    state,
    primary: source.primary || source.label || state,
    label: source.label || source.primary || state,
    secondary: source.secondary || source.message || fallback.secondary || AGENT_STATUS_FALLBACK.secondary,
    tone: source.tone || fallback.tone || AGENT_STATUS_FALLBACK.tone,
  });
}

function getAgentStatusSnapshot(target = getSelectedNode()) {
  const targetId = target?.id || target?.nodeId || getSelectedNodeId() || "application-host";
  const fallback = target?.kind === "application-host"
    ? normalizeRendererAgentStatus({
      state: "Connected",
      primary: "Connected",
      label: "Connected",
      tone: "online",
      secondary: "This device is available locally.",
      targetId,
      targetType: "application-host",
      name: target?.displayName || target?.name || "Application Host",
      metadata: { platform: target?.applicationHost?.platform || target?.platform || null, type: target?.modeLabel || "Application Host", registered: false },
    })
    : normalizeRendererAgentStatus({
      ...AGENT_STATUS_FALLBACK,
      targetId,
      targetType: target?.localAgent ? "local-agent" : "registered-node",
      name: target?.displayName || target?.name || null,
      metadata: { platform: target?.platform || target?.agentIdentity?.platform || null, type: target?.modeLabel || target?.nodeTypeLabel || null, registered: target?.kind === "agent" },
    });
  const snapshot = normalizeRendererAgentStatus(target?.agentStatus, fallback);
  const cacheKey = `${targetId}:${snapshot.state}:${snapshot.checkedAt || ""}:${snapshot.lastSeen || ""}:${snapshot.secondary || ""}`;
  const cached = agentStatusSnapshots.get(targetId);
  if (cached?.cacheKey === cacheKey) return cached.snapshot;
  agentStatusSnapshots.set(targetId, { cacheKey, snapshot });
  return snapshot;
}

function getActiveAgentStatusSnapshot() {
  return getAgentStatusSnapshot(getSelectedNode());
}

function isAgentStatusConnected(status = getActiveAgentStatusSnapshot()) {
  return status.state === "Connected";
}

function isAgentStatusAuthenticated(status = getActiveAgentStatusSnapshot()) {
  return status.state === "Connected" || status.state === "Degraded";
}

function getAgentStatusPillTone(status = getActiveAgentStatusSnapshot()) {
  if (status.state === "Connected") return "ok";
  if (status.state === "Authentication Required") return "critical";
  if (status.state === "Offline") return "planned";
  return "warning";
}

function updateFieldAttributes(name, updater) {
  (fieldMap.get(name) || []).forEach((field) => {
    updater(field);
  });
}

function setDashboardFriendlyField(name, value) {
  dashboardFriendlyFields.forEach((field) => {
    if (field.dataset.dashboardFriendly === name) field.textContent = value;
  });
}

function getFriendlyDashboardState() {
  const nodeId = getSelectedNodeId();
  const selectedNode = getSelectedNode();
  const activeTarget = resolveActiveManagementTarget();
  const remoteNodes = (nodesState.nodes || []).filter((node) => node?.kind === "agent");
  const connectedRemoteNodes = remoteNodes.filter((node) => getNodeVisualState(node) === "online");
  const instances = getInstances();
  const instancesLoaded = isInstancesSnapshotCurrentForSelectedNode();
  const runningInstances = instances.filter(isInstanceRunning);
  const runningContainers = Number(latestDockerSnapshot?.summary?.runningContainers || 0);
  const hasSystemSnapshot = Boolean(latestSystemSnapshot && latestSystemSnapshotNodeId === nodeId);
  const nodeHealth = getSharedNodeHealthModel(selectedNode);
  const agentSummary = getOnboardingAgentSummary();
  const onboardingComplete = getCurrentSettings()["onboarding.completed"] === true;
  const dockerReady = dockerWorkspaceState?.ready === true;
  const metrics = {
    selectedSystem: `${activeTarget.name} · ${activeTarget.targetType === "application-host" ? "Local Application Host" : activeTarget.targetType === "local-agent" ? "Local Agent" : "Remote Agent"}`,
    selectedSystemStatus: activeTarget.connectionState.label,
    updated: hasSystemSnapshot ? formatHealthCheckedAt(latestSystemSnapshotAt) : "Waiting for metrics",
    health: `${nodeHealth.state} · ${nodeHealth.issueCount} issue${nodeHealth.issueCount === 1 ? "" : "s"}`,
  };

  const computer = activeTarget.targetType === "application-host" && (hasSystemSnapshot || runtimeInfoState)
    ? {
      status: "Ready",
      detail: `${runtimeInfoState?.hostname || latestSystemSnapshot?.host?.hostname || "This computer"} is available to AnxOS.`,
    }
    : activeTarget.targetType !== "application-host"
      ? {
        status: activeTarget.connectionState.label,
        detail: `${activeTarget.name} is the selected target. Local Windows metrics are hidden to avoid mixing sources.`,
      }
    : {
      status: "Unable to confirm",
      detail: "System details have not loaded yet.",
    };

  const systems = remoteNodes.length
    ? {
      status: connectedRemoteNodes.length ? "Connected" : "Attention needed",
      detail: `${connectedRemoteNodes.length}/${remoteNodes.length} remote systems connected.`,
    }
    : {
      status: "Ready",
      detail: "Only this computer is connected. Add another system whenever you are ready.",
    };

  const services = !instancesLoaded
    ? {
      status: "Loading",
      detail: "Checking installed servers for the selected system.",
    }
    : instances.length || runningContainers
    ? {
      status: runningInstances.length || runningContainers ? "Running" : "Ready",
      detail: `${runningInstances.length} servers and ${runningContainers} containers running.`,
    }
    : {
      status: "Setup needed",
      detail: "No servers yet. Install a server from the Marketplace to get started.",
    };

  const setupAttention = agentSummary.status === "Connected" || agentSummary.status === "Unable to check" ? false : true;
  const setup = onboardingComplete && !setupAttention
    ? { status: "Ready", detail: "Core setup is complete." }
    : setupAttention
      ? { status: "Attention needed", detail: `Agent status: ${agentSummary.status}.` }
      : { status: "Setup needed", detail: "Finish the setup guide to review local tools and optional features." };

  let next = { title: "Everything looks ready", detail: "Open a workspace or continue managing your systems.", action: "dashboard" };
  if (agentSummary.status !== "Connected" && agentSummary.status !== "Unable to check") {
    next = { title: "Connect your local Agent", detail: "Open Agent Control to check service state and recovery actions.", action: "agent-control" };
  } else if (!dockerReady) {
    next = { title: "Install Docker", detail: "Docker is optional, but useful for container workloads.", action: "docker" };
  } else if (instancesLoaded && !instances.length) {
    next = { title: "Create your first server", detail: "Browse the Marketplace and install a supported server.", action: "marketplace" };
  } else if (!remoteNodes.length) {
    next = { title: "Add a remote system", detail: "Connect another Windows or Linux system when you are ready.", action: "nodes" };
  } else if (!getCurrentSettings()["playit.address"]) {
    next = { title: "Configure public access", detail: "Public Access can make supported services reachable.", action: "playit" };
  }

  return { computer, systems, services, setup, next, metrics, instances, instancesLoaded, remoteNodes };
}

function setSetupHealthField(name, value) {
  setupHealthFields.forEach((field) => {
    if (field.dataset.setupHealth === name) field.textContent = value;
  });
}

function getSetupHealthStatus(ready, label = "Ready") {
  return ready
    ? { label, tone: "ok" }
    : { label: "Needs attention", tone: "warning" };
}

function getManagedBackupCount() {
  const summaryTotal = Number(backupsState.summary?.totalBackups);
  return Number.isFinite(summaryTotal) ? summaryTotal : backupsState.backups.length;
}

function getPublicAccessSetupReadiness(snapshot = latestPublicAccessSnapshot) {
  const services = Array.isArray(snapshot?.services) ? snapshot.services : [];
  const persistedServices = Array.isArray(snapshot?.persistedServices) ? snapshot.persistedServices : [];
  const configuredCount = services.length || persistedServices.length;
  if (configuredCount > 0) {
    const checked = Boolean(snapshot?.checkedAt || services.some((service) => service.lastCheckedAt));
    return {
      configured: true,
      status: checked ? "Ready" : "Configured, not checked",
      tone: "ok",
      detail: `${configuredCount} public or private access service${configuredCount === 1 ? "" : "s"} configured${checked ? "." : ", but live validation has not completed yet."}`,
    };
  }
  if (getCurrentSettings()["playit.address"]) {
    return {
      configured: true,
      status: "Configured, not checked",
      tone: "ok",
      detail: "A legacy Playit address is saved, but live Public Access validation has not completed yet.",
    };
  }
  return {
    configured: false,
    status: "Optional",
    tone: "planned",
    detail: "Configure Public Access only for services you want reachable outside the local system.",
  };
}

function createSetupHealthItem(item) {
  const article = document.createElement("article");
  article.className = "setup-health-item";
  article.append(
    createTextElement("span", item.status, `status-pill status-pill--${item.tone || "planned"}`),
    createTextElement("strong", item.title),
    createTextElement("p", item.detail),
  );
  return article;
}

function createSetupHealthGroup(title, items) {
  const group = document.createElement("section");
  group.className = "setup-health-group";
  const completed = items.filter((item) => item.complete).length;
  group.append(
    createTextElement("h3", title),
    createTextElement("p", `${completed}/${items.length} complete`),
  );
  const list = document.createElement("div");
  list.className = "setup-health-list";
  items.forEach((item) => list.append(createSetupHealthItem(item)));
  group.append(list);
  return group;
}

function getSetupHealthState() {
  const friendly = getFriendlyDashboardState();
  const agentSummary = getOnboardingAgentSummary();
  const dependencySummary = summarizeDependencyStatus(latestDependencyResult);
  const hasDependencyScan = Boolean(latestDependencyResult);
  const backupCount = getManagedBackupCount();
  const publicAccessReadiness = getPublicAccessSetupReadiness();
  const agentConnected = agentSummary.status === "Connected";
  const serviceConfigured = Boolean(agentControlState?.local?.service?.installed || agentControlState?.local?.service?.enabled);
  const core = [
    {
      title: "App installed",
      detail: runtimeInfoState?.appVersion ? `AnxOS ${runtimeInfoState.appVersion} is running.` : "The desktop app is running.",
      complete: true,
      ...getSetupHealthStatus(true),
    },
    {
      title: "Local system detected",
      detail: friendly.computer.detail,
      complete: friendly.computer.status === "Ready",
      ...getSetupHealthStatus(friendly.computer.status === "Ready", friendly.computer.status),
    },
    {
      title: "Agent connected",
      detail: agentConnected ? "Agent features can use the selected connection." : `Agent status: ${agentSummary.status}.`,
      complete: agentConnected,
      ...getSetupHealthStatus(agentConnected, "Connected"),
      action: "agent-control",
    },
  ];
  const recommended = [
    {
      title: "Agent service configured",
      detail: serviceConfigured ? "The local Agent service is configured." : "Configure service startup when you want local Agent management to start automatically.",
      complete: serviceConfigured,
      status: serviceConfigured ? "Ready" : "Recommended",
      tone: serviceConfigured ? "ok" : "planned",
      action: "agent-control",
    },
    {
      title: "Dependencies checked",
      detail: hasDependencyScan ? dependencySummary.message : "Run a dependency check before installing servers that need Java, SteamCMD, Docker, or other tools.",
      complete: hasDependencyScan && dependencySummary.state !== "unknown",
      status: hasDependencyScan ? dependencySummary.label : "Not checked",
      tone: hasDependencyScan ? dependencySummary.tone.replace("status-pill--", "") : "planned",
      action: "agent-control",
    },
    {
      title: "First server created",
      detail: friendly.instances.length ? `${friendly.instances.length} managed server${friendly.instances.length === 1 ? "" : "s"} found.` : "Install a server from the Marketplace when you are ready.",
      complete: friendly.instances.length > 0,
      status: friendly.instances.length ? "Ready" : "Recommended",
      tone: friendly.instances.length ? "ok" : "planned",
      action: "create-server",
    },
    {
      title: "Backup created",
      detail: backupCount ? `${backupCount} backup${backupCount === 1 ? "" : "s"} available.` : "Create a backup before making major server changes.",
      complete: backupCount > 0,
      status: backupCount ? "Ready" : "Recommended",
      tone: backupCount ? "ok" : "planned",
      action: "backups",
    },
  ];
  const optional = [
    {
      title: "Docker ready",
      detail: dockerWorkspaceState?.ready ? "Docker is ready for container workloads." : "Docker is optional unless you plan to use containers.",
      complete: dockerWorkspaceState?.ready === true,
      status: dockerWorkspaceState?.ready ? "Ready" : "Optional",
      tone: dockerWorkspaceState?.ready ? "ok" : "planned",
      action: "docker",
    },
    {
      title: "Public access configured",
      detail: publicAccessReadiness.detail,
      complete: publicAccessReadiness.configured,
      status: publicAccessReadiness.status,
      tone: publicAccessReadiness.tone,
      action: "playit",
    },
    {
      title: "Remote system connected",
      detail: friendly.remoteNodes.length ? `${friendly.remoteNodes.length} remote system${friendly.remoteNodes.length === 1 ? "" : "s"} registered.` : "Remote systems are optional.",
      complete: friendly.remoteNodes.length > 0,
      status: friendly.remoteNodes.length ? "Ready" : "Optional",
      tone: friendly.remoteNodes.length ? "ok" : "planned",
      action: "nodes",
    },
  ];
  const continueItem = [...core, ...recommended, ...optional].find((item) => !item.complete && item.action)
    || { action: "dashboard" };
  return { core, recommended, optional, continueAction: continueItem.action };
}

function renderSetupHealthCenter() {
  if (!setupHealthCenter || !setupHealthGroups) return;
  const state = getSetupHealthState();
  const coreComplete = state.core.filter((item) => item.complete).length;
  const optionalComplete = state.optional.filter((item) => item.complete).length;
  setSetupHealthField("coreProgress", `${coreComplete}/${state.core.length} complete`);
  setSetupHealthField("optionalProgress", `${optionalComplete}/${state.optional.length} complete`);
  setupHealthActionState = { action: state.continueAction };
  if (setupHealthContinueButton) {
    setupHealthContinueButton.textContent = state.continueAction === "dashboard" ? "Open Dashboard" : "Continue Setup";
  }
  setupHealthGroups.replaceChildren(
    createSetupHealthGroup("Essential", state.core),
    createSetupHealthGroup("Recommended", state.recommended),
    createSetupHealthGroup("Optional", state.optional),
  );
}

function renderFriendlyDashboard() {
  const state = getFriendlyDashboardState();
  setDashboardFriendlyField("selectedSystem", state.metrics.selectedSystem);
  setDashboardFriendlyField("selectedSystemStatus", state.metrics.selectedSystemStatus);
  setDashboardFriendlyField("metricsUpdated", state.metrics.updated);
  setDashboardFriendlyField("nodeHealth", state.metrics.health);
  setDashboardFriendlyField("computerStatus", state.computer.status);
  setDashboardFriendlyField("computerDetail", state.computer.detail);
  setDashboardFriendlyField("systemsStatus", state.systems.status);
  setDashboardFriendlyField("systemsDetail", state.systems.detail);
  setDashboardFriendlyField("servicesStatus", state.services.status);
  setDashboardFriendlyField("servicesDetail", state.services.detail);
  setDashboardFriendlyField("setupStatus", state.setup.status);
  setDashboardFriendlyField("setupDetail", state.setup.detail);
  setDashboardFriendlyField("nextStepTitle", state.next.title);
  setDashboardFriendlyField("nextStepDetail", state.next.detail);
  dashboardNextActionState = { page: state.next.action };
  if (dashboardNextAction) dashboardNextAction.textContent = state.next.title;
  if (dashboardFriendlyEmpty) {
    dashboardFriendlyEmpty.replaceChildren();
    if (state.instancesLoaded && !state.instances.length) {
      const server = document.createElement("article");
      server.append(createTextElement("strong", "No servers yet"), createTextElement("p", "Install a server from the Marketplace to get started."));
      const button = createTextElement("button", "Browse Marketplace", "inline-action");
      button.type = "button";
      button.addEventListener("click", () => showPage("marketplace"));
      server.append(button);
      dashboardFriendlyEmpty.append(server);
    }
    if (!state.remoteNodes.length) {
      const nodes = document.createElement("article");
      nodes.append(createTextElement("strong", "Only this computer is connected"), createTextElement("p", "Add another Windows or Linux system whenever you are ready."));
      const button = createTextElement("button", "Add Remote System", "inline-action");
      button.type = "button";
      button.addEventListener("click", () => { showPage("nodes"); setNodeModalVisible(true); });
      nodes.append(button);
      dashboardFriendlyEmpty.append(nodes);
    }
    dashboardFriendlyEmpty.hidden = dashboardFriendlyEmpty.childElementCount === 0;
  }
  renderSetupHealthCenter();
  refreshBackupSummaryForSetup().catch((error) => {
    console.warn("[Backups] Setup backup summary refresh failed.", { message: error?.message || String(error) });
  });
}

function ensurePageIntroductions() {
  Object.entries(PAGE_INTRODUCTIONS).forEach(([pageName, [title, copy]]) => {
    const page = document.querySelector(`[data-page="${pageName}"]`);
    const header = page?.querySelector(".page-header");
    if (!page || !header || page.querySelector("[data-page-introduction]")) return;
    const intro = document.createElement("section");
    intro.className = "page-introduction";
    intro.dataset.pageIntroduction = pageName;
    intro.append(createTextElement("strong", title), createTextElement("p", copy));
    const dismiss = createTextElement("button", "Do not show page introductions", "inline-action");
    dismiss.type = "button";
    dismiss.addEventListener("click", () => {
      saveSettingsPatch({ "guidance.pageIntroductions": false }, { statusMessage: "Page introductions hidden." }).catch((error) => {
        showToast(normalizeIpcErrorMessage(error, "Page introduction preference could not be saved."), "error");
      });
    });
    intro.append(dismiss);
    header.insertAdjacentElement("afterend", intro);
  });
}

function applyPageIntroductionPreference(settings = getCurrentSettings()) {
  const visible = settings["guidance.pageIntroductions"] !== false;
  document.querySelectorAll("[data-page-introduction]").forEach((intro) => {
    intro.hidden = !visible;
  });
}

function getDismissedHelpTips(settings = getCurrentSettings()) {
  return new Set(String(settings["guidance.dismissedTips"] || "").split(",").map((entry) => entry.trim()).filter(Boolean));
}

function setContextualHelpVisible(visible) {
  if (!contextualHelpModal) return;
  if (visible) {
    contextualHelpModal.hidden = false;
    contextualHelpCleanup = activateModal(contextualHelpModal, {
      initialFocus: () => contextualHelpModal.querySelector("[data-contextual-help-action=\"close\"]"),
    });
  } else {
    contextualHelpCleanup?.();
    contextualHelpCleanup = null;
    contextualHelpModal.hidden = true;
  }
}

function openContextualHelp(topicId) {
  const topic = CONTEXTUAL_HELP_TOPICS[topicId];
  if (!topic || !contextualHelpBody) return;
  activeContextualHelpTopic = topicId;
  if (contextualHelpTitle) contextualHelpTitle.textContent = topic.title;
  contextualHelpBody.replaceChildren(
    createTextElement("p", topic.explanation),
    createTextElement("p", topic.details || ""),
  );
  const dismissed = getDismissedHelpTips().has(topicId);
  contextualHelpButtons.forEach((button) => {
    const action = button.dataset.contextualHelpAction;
    if (action === "dismiss") button.textContent = dismissed ? "Tip dismissed" : "Dismiss tip";
    if (action === "related") {
      button.textContent = topic.action?.label || "Open related page";
      button.hidden = !topic.action?.page;
    }
  });
  setContextualHelpVisible(true);
}

async function dismissContextualHelpTip(topicId = activeContextualHelpTopic) {
  if (!topicId) return;
  const dismissed = getDismissedHelpTips();
  dismissed.add(topicId);
  await saveSettingsPatch({ "guidance.dismissedTips": [...dismissed].join(",") }, { statusMessage: "Tip dismissed." });
  openContextualHelp(topicId);
}

async function resetDismissedContextualTips() {
  await saveSettingsPatch({ "guidance.dismissedTips": "" }, { statusMessage: "Dismissed tips reset." });
  showToast("Dismissed tips reset.");
}

function configurePrimaryNavigation() {
  const navMenu = document.querySelector(".nav-menu");

  if (!navMenu) {
    return;
  }

  const orderedItems = PRIMARY_NAVIGATION_ORDER
    .map((pageName) => navMenu.querySelector(`[data-page-target="${pageName}"]`))
    .filter(Boolean);

  navMenu.querySelectorAll("[data-nav-description]").forEach((item) => {
    const label = item.querySelector("[data-nav-label]");
    if (label) label.dataset.navDescription = item.dataset.navDescription || "";
  });

  orderedItems.forEach((item) => {
    item.hidden = false;
    navMenu.appendChild(item);
  });

  navMenu.querySelectorAll("[data-page-target]").forEach((item) => {
    const pageTarget = item.dataset.pageTarget;
    if (LEGACY_PRIMARY_PAGES.has(pageTarget) || !PRIMARY_NAVIGATION_ORDER.includes(pageTarget)) {
      item.hidden = true;
      item.removeAttribute("aria-current");
    }
  });
}

function setStartupStep(name, status) {
  const step = startupSteps[name];

  if (!step) {
    return;
  }

  step.classList.toggle("is-active", status === "active");
  step.classList.toggle("is-complete", status === "complete");
}

function updateStartupMessage(message, detail) {
  if (startupMessage) {
    startupMessage.textContent = message;
  }

  if (startupDetail) {
    startupDetail.textContent = detail;
  }
}

function normalizeIpcErrorMessage(error, fallback = "Request failed.") {
  let message = String(error?.message || error || fallback);
  const ipcPrefixPattern = /^Error invoking remote method '[^']+':\s*(?:Error:\s*)?/;
  while (ipcPrefixPattern.test(message)) {
    message = message.replace(ipcPrefixPattern, "").trim();
  }
  if (/SECURE_SESSION_(?:DECRYPT_FAILED|CORRUPT|SCHEMA_INVALID|SCHEMA_UNSUPPORTED)/i.test(message)) {
    return "Your saved session could not be restored. Please unlock AnxOS again.";
  }
  if (/NODE_CREDENTIAL_DECRYPT_FAILED/i.test(message)) {
    return "Saved node credentials could not be restored. Unlock AnxOS to continue.";
  }
  if (/AUTH_UNLOCK_REQUIRED|OWNER_REQUIRED|LOGIN_REQUIRED/i.test(message)) {
    return "Unlock AnxOS to continue.";
  }
  return message || fallback;
}

function isAuthRecoveryLocked() {
  return securityState?.authState === "locked_recoverable" ||
    securityState?.recoveryRequired === true ||
    accountState?.state === "locked_recoverable" ||
    accountState?.authState === "locked_recoverable" ||
    accountState?.recoveryRequired === true;
}

function blockProtectedAction(message = "Unlock AnxOS to continue.") {
  if (!isAuthRecoveryLocked()) return false;
  if (securityMessage) securityMessage.textContent = securityState?.recoveryMessage || "Unlock AnxOS to continue.";
  showToast(message, "warning");
  return true;
}

