function getNodeVisualState(node) {
  const status = getAgentStatusSnapshot(node);
  if (status.state === "Connected") return "online";
  if (status.state === "Connecting") return "installing";
  if (status.state === "Degraded") return "warning";
  if (status.state === "Authentication Required") return "error";
  if (status.state === "Offline") return "offline";
  return status.tone || "error";
}

function getNodeConnectionState(node) {
  return getAgentStatusSnapshot(node);
}

function getNodeStatusLabel(node) {
  const state = getNodeConnectionState(node);
  if (node?.kind === "application-host") return "Healthy";
  return state.label;
}

function getNodeConnectionSummary(node) {
  const state = getNodeConnectionState(node);
  return state.secondary;
}

const NODE_HEALTH_STALE_MS = 60 * 1000;
const NODE_HEALTH_ACTIONABLE_DIAGNOSTIC_MS = 15 * 60 * 1000;
const NODE_HEALTH_RESOURCE_THRESHOLDS = {
  cpuWarningPercent: 90,
  memoryWarningPercent: 90,
  diskWarningPercent: 85,
  diskCriticalPercent: 95,
  diskCriticalFreeBytes: 2 * 1024 * 1024 * 1024,
  latencyWarningMs: 1000,
};
const NODE_HEALTH_SEVERITY_RANK = {
  Healthy: 0,
  Warning: 1,
  Degraded: 2,
  Unknown: 1,
  "Not Tested": 0,
  Unavailable: 0,
};
const NODE_HEALTH_CATEGORY_STATES = new Set(["Healthy", "Warning", "Degraded", "Unknown", "Unavailable", "Not Tested"]);

function normalizeNodeHealthState(value = "Unknown") {
  const text = String(value || "Unknown").toLowerCase();
  if (text === "healthy" || text === "ok" || text === "ready" || text === "connected") return "Healthy";
  if (text === "warning" || text === "needs attention") return "Warning";
  if (text === "degraded" || text === "failed" || text === "error" || text === "blocked" || text === "critical" || text === "offline" || text === "disconnected") return "Degraded";
  if (text === "not tested" || text === "not-tested") return "Not Tested";
  if (text === "unavailable" || text === "unsupported" || text === "not applicable" || text === "not-applicable" || text === "not configured" || text === "not-configured") return "Unavailable";
  return "Unknown";
}

function nodeHealthTone(state = "Unknown") {
  const normalized = normalizeNodeHealthState(state);
  if (normalized === "Healthy") return "ok";
  if (normalized === "Warning" || normalized === "Unknown" || normalized === "Not Tested" || normalized === "Unavailable") return "warning";
  if (normalized === "Degraded") return "critical";
  return "planned";
}

function isNodeHealthStale(timestamp, maxAgeMs = NODE_HEALTH_STALE_MS) {
  const value = typeof timestamp === "number" ? timestamp : Date.parse(timestamp || "");
  return !Number.isFinite(value) || Date.now() - value > maxAgeMs;
}

function formatHealthCheckedAt(timestamp) {
  if (!timestamp) return "Not checked";
  const value = typeof timestamp === "number" ? timestamp : Date.parse(timestamp || "");
  return Number.isFinite(value) ? formatDateTime(new Date(value).toISOString()) : "Not checked";
}

function getCurrentAgentHealthTarget() {
  return getAgentControlOverviewTarget(agentControlState) || null;
}

function getHealthRuntime() {
  const target = getCurrentAgentHealthTarget();
  return target?.runtime || null;
}

function getNodeHealthCacheKey(node = getSelectedNode()) {
  const id = node?.id || getSelectedNodeId() || "application-host";
  const kind = node?.kind || "unknown";
  return `${kind}:${id}`;
}

function getDependencyHealthState(result = latestDependencyResult) {
  if (!result) return { state: "Unknown", unhealthy: [], total: 0, evidence: "No dependency check has run in this session." };
  const dependencies = Array.isArray(result.dependencies) ? result.dependencies : [];
  const summary = summarizeDependencyStatus(result, { operationState: "idle" });
  const unhealthy = summary.attention || [];
  return {
    state: summary.state === "ready" ? "Healthy" : summary.state === "needs-attention" ? "Warning" : summary.state === "failed" ? "Degraded" : "Unknown",
    unhealthy,
    total: dependencies.length,
    evidence: dependencies.length
      ? `${dependencies.length - unhealthy.length}/${dependencies.length} dependencies installed or verified.`
      : summary.message || "Dependency result did not include dependency rows.",
  };
}

function getMarketplaceInstanceHealthState() {
  const instances = getInstances();
  if (!latestInstancesSnapshot) {
    return { state: getDesktopApiState().hasInstances ? "Unknown" : "Unavailable", failed: [], running: 0, total: 0, evidence: "Instance state has not loaded for this node." };
  }
  const failed = instances.filter((instance) => /fail|error|crash/i.test(String(instance.state || instance.status || "")));
  const running = instances.filter(isInstanceRunning).length;
  const recovery = instances.filter((instance) => instance.recoveryAvailable || instance.requiresRecovery || instance.installRecovery);
  return {
    state: failed.length || recovery.length ? "Degraded" : "Healthy",
    failed,
    recovery,
    running,
    total: instances.length,
    evidence: `${running}/${instances.length} instances running; ${failed.length} failed; ${recovery.length} recovery-required.`,
  };
}

function buildNodeHealthCategory({ id, label, state, evidence, checkedAt = Date.now(), issueCount = 0, workspace = "nodes", remediation = "Review", action = null, actions = null, stale = false, required = false, applicable = true, current = true, historicalIssueCount = 0 }) {
  const applicableState = applicable !== false;
  const currentState = current !== false;
  const normalizedState = normalizeNodeHealthState(state);
  const staleState = stale || (checkedAt ? isNodeHealthStale(checkedAt) : false);
  const countableState = currentState && applicableState && !staleState && !["Not Tested", "Unavailable"].includes(normalizedState);
  const currentIssueCount = countableState ? Math.max(0, Number(issueCount) || 0) : 0;
  const finalState = currentIssueCount <= 0 && ["Warning", "Degraded"].includes(normalizedState)
    ? "Unknown"
    : normalizedState;
  return {
    id,
    label,
    state: NODE_HEALTH_CATEGORY_STATES.has(finalState) ? finalState : "Unknown",
    evidence: evidence || "No evidence reported.",
    checkedAt,
    stale: staleState,
    issueCount: currentIssueCount,
    historicalIssueCount: Math.max(0, Number(historicalIssueCount) || 0),
    required: Boolean(required),
    applicable: applicableState,
    current: currentState,
    workspace,
    remediation,
    action,
    actions: Array.isArray(actions) ? actions.filter((entry) => entry?.action && entry?.label) : action ? [{ label: remediation || "Review", action }] : [],
  };
}

function getNodeHealthApplicability(node = {}) {
  const isApplicationHost = node?.kind === "application-host";
  const isAgentNode = node?.kind === "agent";
  return {
    applicationHost: isApplicationHost,
    agentNode: isAgentNode,
    localHostOnly: isApplicationHost,
    remoteAgentOnly: isAgentNode,
  };
}

function aggregateNodeHealthCategories(categories = []) {
  const applicable = categories.filter((category) => category.applicable !== false && category.state !== "Unavailable");
  const current = applicable.filter((category) => category.current !== false && !category.stale);
  const requiredCurrent = current.filter((category) => category.required);
  const hasHealthyRequiredEvidence = requiredCurrent.some((category) => category.state === "Healthy");
  const degraded = current.find((category) => category.state === "Degraded");
  if (degraded) {
    return { state: "Degraded", reason: `${degraded.label} has a current degraded condition.` };
  }
  const warning = current.find((category) => category.state === "Warning");
  if (warning) {
    return { state: "Warning", reason: `${warning.label} has a current warning.` };
  }
  const requiredUnknown = requiredCurrent.find((category) => category.state === "Unknown");
  if (requiredUnknown && !hasHealthyRequiredEvidence) {
    return { state: "Unknown", reason: `${requiredUnknown.label} does not have enough current evidence.` };
  }
  if (!requiredCurrent.length && !current.some((category) => category.state === "Healthy")) {
    return { state: "Unknown", reason: "No current applicable health evidence is available." };
  }
  return { state: "Healthy", reason: "All current applicable required checks are healthy." };
}

function getNodeHealthIssueCategories(categories = []) {
  const roots = new Set();
  return categories.filter((category) => {
    const hasIssue = category.issueCount > 0;
    if (category.applicable === false || category.current === false || category.stale || !hasIssue) {
      return false;
    }
    const evidence = `${category.label || ""} ${category.evidence || ""}`.toLowerCase();
    const root = /unauthorized|authentication|credential|token/.test(evidence)
      ? "saved-credential-rejected"
      : category.id || category.label || "node-health-issue";
    if (roots.has(root)) {
      return false;
    }
    roots.add(root);
    return true;
  });
}

function hasSystemSnapshotForNode(node = getSelectedNode()) {
  return Boolean(latestSystemSnapshot && latestSystemSnapshotNodeId === (node?.id || getSelectedNodeId() || "application-host"));
}

function getSystemSnapshotForNode(node = getSelectedNode()) {
  return hasSystemSnapshotForNode(node) ? latestSystemSnapshot : null;
}

function buildConnectivityHealth(node) {
  const visual = getNodeVisualState(node);
  const connectionState = getNodeConnectionState(node);
  const target = getCurrentAgentHealthTarget();
  const runtime = getHealthRuntime();
  const latency = runtime?.latencyMs ?? target?.latencyMs;
  const lastHeartbeat = node?.connection?.lastSeen || node?.updatedAt || target?.lastHeartbeat || null;
  let state = visual === "online" ? "Healthy" : visual === "warning" ? "Warning" : ["offline", "error"].includes(visual) ? "Degraded" : "Unknown";
  if (connectionState.state === "Authentication Required") state = "Degraded";
  else if (Number.isFinite(latency) && latency > NODE_HEALTH_RESOURCE_THRESHOLDS.latencyWarningMs) state = "Warning";
  else if (node?.kind === "agent" && isNodeHealthStale(lastHeartbeat, 2 * NODE_HEALTH_STALE_MS) && visual === "online") state = "Warning";
  return buildNodeHealthCategory({
    id: "connectivity",
    label: "Connectivity",
    state,
    evidence: [
      `${connectionState.primary}: ${connectionState.secondary}`,
      Number.isFinite(latency) ? `Latency ${latency} ms` : "Latency unavailable",
      lastHeartbeat ? `Last heartbeat ${formatHealthCheckedAt(lastHeartbeat)}` : "Heartbeat unavailable",
      node?.kind === "application-host" ? "Local application host" : node?.agentUrl || "Agent URL unavailable",
    ].join(" · "),
    checkedAt: lastHeartbeat ? Date.parse(lastHeartbeat) || Date.now() : Date.now(),
    issueCount: state === "Healthy" ? 0 : 1,
    required: true,
    workspace: "nodes",
    remediation: "Test connection",
    action: "test-node",
    actions: [
      { label: "Test connection", action: "test-node" },
      { label: "Ping Agent", action: "ping-agent" },
      { label: "Open Agent Control", action: "open-agent-control" },
    ],
  });
}

function buildAgentHealth(node) {
  if (node?.kind === "application-host" && !agentControlState) {
    return buildNodeHealthCategory({
      id: "agent",
      label: "Agent",
      state: "Unavailable",
      evidence: "Application host mode can run without a local Agent.",
      workspace: "agent-control",
      remediation: "Open Agent Control",
      action: "open-agent-control",
      actions: [{ label: "Open Agent Control", action: "open-agent-control" }],
      required: false,
      applicable: false,
    });
  }
  const rawTarget = getCurrentAgentHealthTarget();
  const target = node?.kind === "agent" ? (rawTarget?.nodeId === node.id ? rawTarget : null) : rawTarget;
  const runtime = target ? getAgentRuntime(target) : null;
  const connectionState = getNodeConnectionState(node);
  const stateText = target?.state || node?.connection?.status || "Unknown";
  const running = node?.kind === "agent"
    ? connectionState.state === "Connected"
    : runtime?.serviceState === "running" || isAgentTargetRunning(target || {});
  const authFailed = connectionState.state === "Authentication Required";
  const unavailable = connectionState.state === "Offline";
  const portConflict = target ? /AGENT_PORT_IN_USE|port .*in use/i.test(String(target?.mostRecentError?.code || target?.mostRecentError?.message || agentControlMessage?.textContent || "")) : false;
  const state = authFailed || portConflict ? "Degraded" : running ? "Healthy" : unavailable ? "Unavailable" : target ? "Degraded" : "Unknown";
  const checkedAt = node?.connection?.lastSeen || target?.lastHeartbeat || agentControlLastRuntimeSnapshot?.timestamp || null;
  return buildNodeHealthCategory({
    id: "agent",
    label: "Agent",
    state,
    evidence: [
      node?.kind === "agent" ? `${connectionState.primary}: ${connectionState.secondary}` : `Process ${formatAgentProcess(runtime, stateText)}`,
      runtime?.version || target?.agentVersion || node?.connection?.agentVersion || node?.agentIdentity?.agentVersion ? `Version ${runtime?.version || target?.agentVersion || node?.connection?.agentVersion || node?.agentIdentity?.agentVersion}` : "Version unavailable",
      Number.isFinite(runtime?.latencyMs ?? node?.connection?.latencyMs) ? `Last request ${runtime?.latencyMs ?? node?.connection?.latencyMs} ms` : "Last request unavailable",
      portConflict ? "Port conflict detected" : authFailed ? "Saved credential rejected" : target?.mostRecentError?.message || connectionState.secondary || "No recent Agent error reported",
    ].join(" · "),
    checkedAt,
    issueCount: state === "Healthy" ? 0 : 1,
    required: node?.kind === "agent",
    applicable: node?.kind === "agent" || Boolean(target),
    current: Boolean(checkedAt || state === "Healthy" || authFailed || unavailable),
    workspace: "agent-control",
    remediation: running ? "Open Agent Control" : "Reconnect Agent",
    action: running ? "open-agent-control" : "reconnect-agent",
    actions: [
      { label: "Open Agent Control", action: "open-agent-control" },
      { label: "Reconnect Agent", action: "reconnect-agent" },
      { label: "Run diagnostics", action: "agent-diagnostics" },
    ],
  });
}

function buildDesktopRuntimeHealth(node = getSelectedNode()) {
  if (node?.kind !== "application-host") {
    return buildNodeHealthCategory({
      id: "desktop-runtime",
      label: "Desktop runtime",
      state: "Unavailable",
      evidence: "Desktop runtime health applies only to the local application host.",
      workspace: "nodes",
      remediation: "Open Node Details",
      action: "open-node-details",
      actions: [{ label: "Open Node Details", action: "open-node-details" }],
      required: false,
      applicable: false,
      current: false,
    });
  }
  const identity = getNodeIdentity(node);
  const hasRuntime = Boolean(runtimeInfoState || identity.appVersion || identity.electronVersion);
  const running = identity.runningState === "running";
  const state = running && hasRuntime ? "Healthy" : running ? "Unknown" : "Degraded";
  return buildNodeHealthCategory({
    id: "desktop-runtime",
    label: "Desktop runtime",
    state,
    evidence: [
      `Running state ${identity.runningState || "unknown"}`,
      `Desktop uptime ${formatDuration(identity.desktopUptimeSeconds || 0)}`,
      `Electron ${identity.electronVersion || runtimeInfoState?.electron || "unavailable"}`,
      `App ${identity.appVersion || runtimeInfoState?.releaseLabel || runtimeInfoState?.appVersion || "unavailable"}`,
      `Developer Mode ${identity.developerMode || runtimeInfoState?.developmentMode ? "enabled" : "disabled"}`,
    ].join(" · "),
    checkedAt: Date.now(),
    issueCount: state === "Healthy" ? 0 : 1,
    required: true,
    workspace: "nodes",
    remediation: "Open Node Details",
    action: "open-node-details",
    actions: [
      { label: "Open Node Details", action: "open-node-details" },
      { label: "Open Dashboard", action: "open-dashboard" },
    ],
  });
}

function buildResourceHealth(node = getSelectedNode()) {
  const snapshot = getSystemSnapshotForNode(node);
  const cpu = Number(snapshot?.cpu?.usagePercent);
  const memory = Number(snapshot?.memory?.percent);
  const stateIssues = [];
  let state = snapshot ? "Healthy" : "Unknown";
  if (snapshot && !Number.isFinite(cpu) && !Number.isFinite(memory)) {
    state = "Unknown";
    stateIssues.push("CPU and memory unavailable");
  }
  if (Number.isFinite(cpu) && cpu >= NODE_HEALTH_RESOURCE_THRESHOLDS.cpuWarningPercent) stateIssues.push(`CPU ${cpu.toFixed(1)}%`);
  if (Number.isFinite(memory) && memory >= NODE_HEALTH_RESOURCE_THRESHOLDS.memoryWarningPercent) stateIssues.push(`Memory ${memory.toFixed(1)}%`);
  if (stateIssues.length && state !== "Unknown") state = "Warning";
  return buildNodeHealthCategory({
    id: "resources",
    label: "Resources",
    state,
    evidence: snapshot
      ? `CPU ${formatPercent(cpu)} · Memory ${formatPercent(memory)} (${formatBytes(snapshot.memory?.used)} / ${formatBytes(snapshot.memory?.total)})`
      : `${node?.displayName || "Node"} resource metrics have not loaded for this node.`,
    checkedAt: snapshot ? latestSystemSnapshotAt : null,
    issueCount: stateIssues.length,
    required: true,
    current: Boolean(snapshot),
    workspace: "dashboard",
    remediation: "Open Dashboard",
    action: "open-dashboard",
    actions: [
      { label: "Open Dashboard", action: "open-dashboard" },
      { label: "Live Metrics", action: "live-metrics" },
    ],
  });
}

function buildStorageHealth(node = getSelectedNode()) {
  const snapshot = getSystemSnapshotForNode(node);
  const disk = snapshot?.disk || null;
  let state = disk ? "Healthy" : "Unknown";
  const percent = Number(disk?.percent);
  const free = Number(disk?.free);
  const issues = [];
  if (disk && !Number.isFinite(percent) && !Number.isFinite(free)) {
    state = "Unknown";
    issues.push("Disk metrics unavailable");
  }
  if (Number.isFinite(percent) && percent >= NODE_HEALTH_RESOURCE_THRESHOLDS.diskWarningPercent) {
    state = "Warning";
    issues.push(`Disk ${percent.toFixed(1)}% used`);
  }
  if ((Number.isFinite(percent) && percent >= NODE_HEALTH_RESOURCE_THRESHOLDS.diskCriticalPercent) || (Number.isFinite(free) && free <= NODE_HEALTH_RESOURCE_THRESHOLDS.diskCriticalFreeBytes)) {
    state = "Degraded";
    issues.push(`Disk free ${formatBytes(free)}`);
  }
  return buildNodeHealthCategory({
    id: "storage",
    label: "Storage",
    state,
    evidence: disk ? `Disk ${formatPercent(percent)} used · ${formatBytes(free)} free · Mount ${disk.mount || "unavailable"}` : `${node?.displayName || "Node"} storage metrics have not loaded for this node.`,
    checkedAt: disk ? latestSystemSnapshotAt : null,
    issueCount: issues.length,
    required: true,
    current: Boolean(disk),
    workspace: "files",
    remediation: "Open Files",
    action: "open-files",
    actions: [
      { label: "Open Files", action: "open-files" },
      { label: "Storage usage", action: "storage-usage" },
    ],
  });
}

function buildDependencyHealth() {
  const health = getDependencyHealthState();
  return buildNodeHealthCategory({
    id: "dependencies",
    label: "Dependencies",
    state: health.state,
    evidence: health.evidence,
    checkedAt: latestDependencyResultAt || null,
    issueCount: health.unhealthy.length,
    required: false,
    current: Boolean(latestDependencyResult),
    workspace: "agent-control",
    remediation: health.unhealthy.length ? "Recheck dependencies" : "Open Agent Control",
    action: health.unhealthy.length ? "recheck-dependencies" : "open-agent-control",
    actions: [
      { label: "Check dependencies", action: "check-dependencies" },
      { label: "Prepare node", action: "prepare-node" },
    ],
  });
}

function buildMarketplaceHealth() {
  const health = getMarketplaceInstanceHealthState();
  return buildNodeHealthCategory({
    id: "marketplace-instances",
    label: "Marketplace instances",
    state: health.state,
    evidence: health.evidence,
    checkedAt: latestInstancesSnapshotAt || null,
    issueCount: (health.failed?.length || 0) + (health.recovery?.length || 0),
    required: false,
    current: Boolean(latestInstancesSnapshot),
    workspace: "instances",
    remediation: health.failed?.length ? "Open Instances" : "Open Marketplace",
    action: health.failed?.length ? "open-instances" : "open-marketplace",
    actions: [
      { label: "Open Marketplace", action: "open-marketplace" },
      { label: "View running instances", action: "view-running-instances" },
    ],
  });
}

function buildFilesHealth() {
  const unavailable = !getDesktopApiState().hasFiles;
  const connected = filesConnectionState.connected === true;
  return buildNodeHealthCategory({
    id: "files",
    label: "Files/storage provider",
    state: unavailable ? "Unavailable" : connected ? "Healthy" : "Warning",
    evidence: connected
      ? `${latestFilesListing?.entries?.length || 0} entries visible at ${filesConnectionState.currentPath || filesConnectionState.homePath || "current path"}.`
      : unavailable ? "Files IPC bridge is unavailable." : filesConnectionState.message || "No storage provider is connected.",
    checkedAt: latestFilesListingAt || Date.now(),
    issueCount: connected ? 0 : 1,
    required: false,
    current: !unavailable,
    workspace: "files",
    remediation: "Open Files",
    action: "open-files",
    actions: [{ label: "Open Files", action: "open-files" }],
  });
}

function buildOperationsHealth() {
  const operations = [...operationsState.items.values()];
  const failed = operations.filter((operation) => operation.status === "failed");
  const active = operations.filter((operation) => ["running", "queued"].includes(operation.status));
  const activeFailed = operations.filter((operation) => ["running", "queued"].includes(operation.status) && /fail|error/i.test(String(operation.step || operation.message || operation.error || "")));
  return buildNodeHealthCategory({
    id: "operations",
    label: "Operations",
    state: activeFailed.length ? "Warning" : "Healthy",
    evidence: `${active.length} active; ${failed.length} historical failed operation${failed.length === 1 ? "" : "s"}.`,
    checkedAt: Date.now(),
    issueCount: activeFailed.length,
    historicalIssueCount: failed.length,
    required: false,
    workspace: "operations",
    remediation: activeFailed.length ? "Open failed operations" : "Open Operations",
    action: "open-operations",
    actions: [
      { label: "Open Operations", action: "open-operations" },
      { label: "Failed operations", action: "failed-operations" },
    ],
  });
}

function buildDiagnosticsHealth() {
  const groups = diagnosticsIssueGroups.length ? diagnosticsIssueGroups : groupDiagnosticIssues(agentLogEntries);
  const actionable = groups.filter((group) => {
    const lastSeen = Date.parse(group.lastSeen || group.latest?.timestamp || "");
    return Number.isFinite(lastSeen) && Date.now() - lastSeen <= NODE_HEALTH_ACTIONABLE_DIAGNOSTIC_MS;
  });
  const critical = actionable.filter((group) => getDiagnosticSeverityRank(group.severity) >= 3);
  return buildNodeHealthCategory({
    id: "diagnostics",
    label: "Diagnostics",
    state: critical.length ? "Degraded" : actionable.length ? "Warning" : groups.length ? "Healthy" : agentLogEntries.length ? "Healthy" : "Unknown",
    evidence: actionable.length
      ? `${actionable.length} current actionable grouped issue${actionable.length === 1 ? "" : "s"} from ${agentLogEntries.length} sanitized log entries.`
      : groups.length
        ? `${groups.length} historical grouped diagnostic issue${groups.length === 1 ? "" : "s"} from ${agentLogEntries.length} sanitized log entries; no recent actionable issue detected.`
        : `${groups.length} grouped issue${groups.length === 1 ? "" : "s"} from ${agentLogEntries.length} sanitized log entries.`,
    checkedAt: Date.now(),
    issueCount: actionable.length,
    historicalIssueCount: Math.max(0, groups.length - actionable.length),
    required: false,
    current: agentLogEntries.length > 0,
    workspace: "diagnostics",
    remediation: "Open Diagnostics",
    action: "open-diagnostics",
    actions: [
      { label: "Open Diagnostics", action: "open-diagnostics" },
      { label: "Export bundle", action: "export-diagnostics-bundle" },
    ],
  });
}

function buildUpdatesHealth() {
  const update = updateUiState || {};
  const hasUpdate = Boolean(update.latest?.hasUpdate || latestUpdateInfo?.hasUpdate);
  const failed = Boolean(update.error);
  return buildNodeHealthCategory({
    id: "updates",
    label: "Updates",
    state: !getDesktopApiState().hasUpdates ? "Unavailable" : failed ? "Warning" : hasUpdate ? "Warning" : update.lastCheckedAt ? "Healthy" : "Unknown",
    evidence: failed ? update.error : hasUpdate ? `Update ${update.latest?.latestVersion || latestUpdateInfo?.latestVersion || "available"} is available.` : "Update state is available from Settings.",
    checkedAt: update.lastCheckedAt || Date.now(),
    issueCount: failed || hasUpdate ? 1 : 0,
    required: false,
    applicable: getDesktopApiState().hasUpdates,
    current: Boolean(update.lastCheckedAt || failed || hasUpdate),
    workspace: "settings",
    remediation: "Check updates",
    action: "check-updates",
    actions: [{ label: "Open Updates", action: "open-updates" }],
  });
}

function buildMaintenanceHealth() {
  const warnings = maintenanceState.categories.filter((category) => category.status === "warning" || category.restartRequired).length;
  const scanned = Boolean(maintenanceState.lastScanAt);
  return buildNodeHealthCategory({
    id: "maintenance",
    label: "Maintenance",
    state: warnings ? "Warning" : scanned ? "Healthy" : "Not Tested",
    evidence: scanned ? `${warnings} warning categories after last scan.` : "No maintenance scan has run in this session.",
    checkedAt: maintenanceState.lastScanAt || null,
    issueCount: warnings,
    required: false,
    current: scanned,
    workspace: "maintenance",
    remediation: "Open Maintenance",
    action: "open-maintenance",
    actions: [{ label: "Open Maintenance", action: "open-maintenance" }],
  });
}

function buildNodeHealthModel(node = getSelectedNode()) {
  const selectedNode = node || getSelectedNode() || { id: "application-host", kind: "application-host", displayName: "Application Host" };
  const cacheKey = getNodeHealthCacheKey(selectedNode);
  const applicability = getNodeHealthApplicability(selectedNode);
  const ownsActiveRendererContext = selectedNode.id === getSelectedNodeId();
  const rawCategories = [
    buildConnectivityHealth(selectedNode),
    buildAgentHealth(selectedNode),
    buildDesktopRuntimeHealth(selectedNode),
    buildResourceHealth(selectedNode),
    buildStorageHealth(selectedNode),
    buildDependencyHealth(),
    buildMarketplaceHealth(),
    buildFilesHealth(),
    buildOperationsHealth(),
    buildDiagnosticsHealth(),
    buildUpdatesHealth(),
    buildMaintenanceHealth(),
  ];
  const categories = rawCategories.map((category) => {
    if (applicability.agentNode && ["updates", "maintenance"].includes(category.id)) {
      return { ...category, state: "Unavailable", applicable: false, current: false, issueCount: 0, evidence: `${category.label} is local-host-only and does not apply to remote Agent nodes.` };
    }
    if (isWindowsAgentNode(selectedNode) && getNodeCapabilities(selectedNode).supportsGameServers !== true && category.id === "marketplace-instances") {
      return { ...category, state: "Unavailable", applicable: false, current: false, issueCount: 0, evidence: "Windows Agent MVP does not enable game-server hosting yet. Health, files, Public Access, and Docker detection remain available." };
    }
    if (!ownsActiveRendererContext && ["resources", "storage", "dependencies", "marketplace-instances", "files", "operations", "diagnostics"].includes(category.id)) {
      return { ...category, current: false, issueCount: 0, evidence: `${category.label} evidence belongs to the active node and is not applied to ${selectedNode.displayName || selectedNode.id}.` };
    }
    return category;
  });
  const aggregate = aggregateNodeHealthCategories(categories);
  const currentIssueCategories = getNodeHealthIssueCategories(categories);
  const issueCount = currentIssueCategories.reduce((sum, category) => sum + (category.issueCount || 0), 0);
  const historicalIssueCount = categories.reduce((sum, category) => sum + (category.historicalIssueCount || 0), 0);
  const staleCount = categories.filter((category) => category.stale).length;
  const notTestedCount = categories.filter((category) => category.state === "Not Tested").length;
  const unavailableCount = categories.filter((category) => category.applicable === false || category.state === "Unavailable").length;
  return {
    nodeId: selectedNode.id || "application-host",
    cacheKey,
    nodeName: selectedNode.displayName || selectedNode.id || "Application Host",
    state: aggregate.state,
    reason: aggregate.reason,
    issueCount,
    historicalIssueCount,
    staleCount,
    notTestedCount,
    unavailableCount,
    categories,
    currentIssueCategories,
    updatedAt: Date.now(),
    summary: issueCount
      ? `${issueCount} current issue${issueCount === 1 ? "" : "s"} across ${categories.length} health categories. ${aggregate.reason}`
      : `No current health issues detected across ${categories.length} health categories. ${aggregate.reason}`,
  };
}

function getSharedNodeHealthModel(node = getSelectedNode()) {
  const selectedNode = node || getSelectedNode() || { id: "application-host", kind: "application-host", displayName: "Application Host" };
  const cacheKey = getNodeHealthCacheKey(selectedNode);
  if (nodeHealthState?.cacheKey === cacheKey) {
    return nodeHealthState;
  }
  const cached = nodeHealthSnapshotCache.get(cacheKey);
  if (cached) {
    return cached;
  }
  const health = buildNodeHealthModel(selectedNode);
  nodeHealthSnapshotCache.set(cacheKey, health);
  return health;
}

function syncNodeHealthNotifications(health) {
  if (!health || !previousNodeHealthState || previousNodeHealthState.nodeId !== health.nodeId) {
    previousNodeHealthState = health;
    return;
  }
  const previousRank = NODE_HEALTH_SEVERITY_RANK[normalizeNodeHealthState(previousNodeHealthState.state)] || 0;
  const nextRank = NODE_HEALTH_SEVERITY_RANK[normalizeNodeHealthState(health.state)] || 0;
  if (nextRank >= 2 && nextRank > previousRank) {
    createNotification({
      category: "Nodes",
      severity: health.state === "Degraded" ? "critical" : "warning",
      title: `${health.nodeName} health ${health.state.toLowerCase()}`,
      message: health.summary,
      dedupKey: `node-health:${health.nodeId}:${health.state}`,
      relatedWorkspace: "nodes",
      actions: ["openDiagnostics", "openOperations"],
      resolved: false,
    });
  } else if (previousRank >= 2 && nextRank <= 1) {
    createNotification({
      category: "Nodes",
      severity: "success",
      title: `${health.nodeName} health recovered`,
      message: health.summary,
      dedupKey: `node-health:${health.nodeId}:recovered`,
      relatedWorkspace: "nodes",
      actions: ["openDiagnostics"],
      resolved: true,
    });
  }
  previousNodeHealthState = health;
}

function refreshNodeHealth({ notify = true } = {}) {
  const generation = ++nodeHealthGeneration;
  const health = buildNodeHealthModel();
  health.generation = generation;
  nodeHealthSnapshotCache.set(health.cacheKey, health);
  if (generation !== nodeHealthGeneration) {
    return nodeHealthState || health;
  }
  nodeHealthState = health;
  if (notify) syncNodeHealthNotifications(nodeHealthState);
  renderNodeHealth(nodeHealthState);
  return nodeHealthState;
}

function createNodeHealthBadge(state) {
  return createTextElement("span", normalizeNodeHealthState(state), `status-pill status-pill--${nodeHealthTone(state)}`);
}

function getNodeHealthBreakdown(health) {
  const breakdown = {
    critical: 0,
    warnings: 0,
    healthy: 0,
    unknown: 0,
    notTested: 0,
    unavailable: 0,
  };
  (health?.categories || []).forEach((category) => {
    const state = normalizeNodeHealthState(category.state);
    if (category.applicable === false || state === "Unavailable") breakdown.unavailable += 1;
    else if (state === "Not Tested") breakdown.notTested += 1;
    else if (state === "Degraded") breakdown.critical += 1;
    else if (state === "Warning") breakdown.warnings += 1;
    else if (state === "Healthy") breakdown.healthy += 1;
    else breakdown.unknown += 1;
  });
  return breakdown;
}

function splitNodeHealthEvidence(evidence = "") {
  const parts = String(evidence || "No evidence available.")
    .split(" · ")
    .map((part) => part.trim())
    .filter(Boolean);
  return {
    summary: parts.slice(0, 2).join(" · ") || "No evidence available.",
    details: parts.slice(2),
    all: parts.length ? parts.join(" · ") : "No evidence available.",
  };
}

function createNodeHealthMeta(label, value) {
  const item = document.createElement("span");
  item.className = "node-health-meta-item";
  item.append(createTextElement("span", label), createTextElement("strong", value));
  return item;
}

function createNodeHealthDetails(category, evidence) {
  const details = document.createElement("details");
  details.className = "node-health-details";
  const summary = createTextElement("summary", "Evidence");
  const list = document.createElement("ul");
  const entries = evidence.details.length ? evidence.details : [evidence.summary];
  entries.forEach((entry) => {
    const row = document.createElement("li");
    row.append(createTextElement("span", entry, "node-health-long-value"));
    list.append(row);
  });
  details.append(summary, list);
  const copy = document.createElement("button");
  copy.type = "button";
  copy.className = "inline-action node-health-copy";
  copy.textContent = "Copy details";
  copy.setAttribute("aria-label", `Copy health details for ${category.label}`);
  copy.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(`${category.label}: ${evidence.all}`);
      showToast("Node health details copied.", "success");
    } catch {
      showToast("Could not copy node health details.", "warning");
    }
  });
  const wrapper = document.createElement("div");
  wrapper.className = "node-health-details-wrap";
  wrapper.append(details, copy);
  return wrapper;
}

function sortNodeHealthIssues(categories = []) {
  return [...categories].sort((a, b) => {
    const aRank = NODE_HEALTH_SEVERITY_RANK[normalizeNodeHealthState(a.state)] || 0;
    const bRank = NODE_HEALTH_SEVERITY_RANK[normalizeNodeHealthState(b.state)] || 0;
    if (bRank !== aRank) return bRank - aRank;
    return (b.issueCount || 0) - (a.issueCount || 0);
  });
}

function selectOperationFilter(filter = "all") {
  operationsState.filter = filter;
  renderOperationsCenter();
}

function selectInstanceStatusFilter(filter = "all") {
  if (instancesFilterSelect) {
    instancesFilterSelect.value = filter;
  }
  filterInstanceRows();
}

function openNodeHealthSettingsCategory(category, selector) {
  showPage("settings");
  setActiveSettingsCategory(category, selector);
}

function exportDiagnosticsSupportBundleFromHealth() {
  showPage("agent-control");
  return runDiagnosticsAction("export");
}

function runNodeHealthAction(action) {
  if (action === "open-node-details") return openNodeDetails(getSelectedNodeId());
  if (action === "test-node") return testSelectedNode();
  if (action === "ping-agent") return testAgentConnection({ silent: false });
  if (action === "reconnect-agent") { showPage("agent-control"); return refreshAgentControl({ includeConfig: true }); }
  if (action === "check-dependencies" || action === "recheck-dependencies") { showPage("agent-control"); return runDependencyAction("check"); }
  if (action === "prepare-node") { showPage("agent-control"); return runDependencyAction("install"); }
  if (action === "agent-diagnostics") { showPage("agent-control"); return runAgentControlAction("runDiagnostics"); }
  if (action === "open-agent-control") return showPage("agent-control");
  if (action === "open-dashboard") return showPage("dashboard");
  if (action === "live-metrics") { showPage("dashboard"); return refreshDashboard(); }
  if (action === "open-maintenance") return showPage("maintenance");
  if (action === "open-instances") return showPage("instances");
  if (action === "view-running-instances") { showPage("instances"); selectInstanceStatusFilter("running"); return refreshInstances({ refreshMetrics: false }); }
  if (action === "open-marketplace") return showPage("marketplace");
  if (action === "open-files") { showPage("files"); return refreshCurrentFilesDirectory(); }
  if (action === "storage-usage") return openNodeHealthSettingsCategory("storage", '[data-settings-category="storage"]');
  if (action === "open-operations") return showPage("operations");
  if (action === "failed-operations") { showPage("operations"); return selectOperationFilter("failed"); }
  if (action === "open-diagnostics") return showPage("agent-control");
  if (action === "export-diagnostics-bundle") return exportDiagnosticsSupportBundleFromHealth();
  if (action === "check-updates") return checkForUpdates({ silent: false });
  if (action === "open-updates") return openNodeHealthSettingsCategory("updates", '[data-settings-category="updates"]');
  return null;
}

function renderNodeHealthActions(container, category) {
  if (!container) return;
  const actions = Array.isArray(category.actions) ? category.actions : [];
  actions.forEach((entry) => {
    if (!entry?.action || !entry?.label) return;
    const action = document.createElement("button");
    action.type = "button";
    action.className = "inline-action";
    action.dataset.nodeHealthAction = entry.action;
    action.textContent = entry.label;
    action.setAttribute("aria-label", `${entry.label} for ${category.label}`);
    container.append(action);
  });
}

function renderNodeHealth(health = getSharedNodeHealthModel()) {
  if (nodeHealthStatus) {
    nodeHealthStatus.className = `status-pill status-pill--${nodeHealthTone(health.state)}`;
    nodeHealthStatus.textContent = normalizeNodeHealthState(health.state);
  }
  if (nodeHealthUpdated) {
    nodeHealthUpdated.textContent = `Last checked ${formatHealthCheckedAt(health.updatedAt)} · ${health.staleCount} stale categor${health.staleCount === 1 ? "y" : "ies"}.`;
  }
  if (nodeHealthOverview) {
    const breakdown = getNodeHealthBreakdown(health);
    renderSecuritySummaryGrid(nodeHealthOverview, [
      ["Overall", health.state],
      ["Issues", health.issueCount],
      ["Degraded", breakdown.critical],
      ["Warnings", breakdown.warnings],
      ["Healthy", breakdown.healthy],
      ["Unknown", breakdown.unknown],
      ["Not Tested", breakdown.notTested],
      ["Unavailable", breakdown.unavailable],
      ["Node", health.nodeName],
      ["Stale data", health.staleCount],
      ["History", health.historicalIssueCount || 0],
    ]);
  }
  if (nodeHealthCategories) {
    nodeHealthCategories.replaceChildren();
    health.categories.forEach((category) => {
      const item = document.createElement("article");
      item.className = "security-list-item";
      item.dataset.nodeHealthCategory = category.id;
      const row = document.createElement("div");
      row.className = "security-card-row";
      const body = document.createElement("div");
      body.className = "node-health-card-body";
      const evidence = splitNodeHealthEvidence(category.evidence);
      const meta = document.createElement("div");
      meta.className = "node-health-meta";
      meta.append(
        createNodeHealthMeta("Checked", formatHealthCheckedAt(category.checkedAt)),
        createNodeHealthMeta("Issues", String(category.issueCount || 0)),
        createNodeHealthMeta("Workspace", category.workspace || "Unavailable"),
      );
      body.append(
        createTextElement("strong", category.label),
        createTextElement("p", evidence.summary, "node-health-summary-text"),
        meta,
      );
      if (category.stale) body.append(createTextElement("p", "Stale or unavailable data", "security-event-meta"));
      body.append(createNodeHealthDetails(category, evidence));
      row.append(body, createNodeHealthBadge(category.state));
      const actions = document.createElement("div");
      actions.className = "settings-actions node-health-actions";
      renderNodeHealthActions(actions, category);
      item.append(row, actions);
      nodeHealthCategories.append(item);
    });
  }
  if (nodeHealthIssues) {
    nodeHealthIssues.replaceChildren();
    const issues = sortNodeHealthIssues(health.currentIssueCategories || getNodeHealthIssueCategories(health.categories));
    if (!issues.length) {
      nodeHealthIssues.append(createEmptyState("No node health issues detected from current data."));
    } else {
      issues.forEach((category) => {
        const item = document.createElement("article");
        item.className = "security-list-item node-health-issue-card";
        const evidence = splitNodeHealthEvidence(category.evidence);
        const row = document.createElement("div");
        row.className = "security-card-row";
        const body = document.createElement("div");
        body.className = "node-health-card-body";
        body.append(
          createTextElement("strong", category.label),
          createTextElement("p", evidence.summary, "node-health-summary-text"),
          createTextElement("p", `Related workspace: ${category.workspace || "Unavailable"}`, "security-event-meta"),
        );
        row.append(body, createNodeHealthBadge(category.state));
        const actions = document.createElement("div");
        actions.className = "settings-actions node-health-actions";
        renderNodeHealthActions(actions, category);
        item.append(
          row,
          createNodeHealthDetails(category, evidence),
          actions,
        );
        nodeHealthIssues.append(item);
      });
    }
  }
}

function createNodeBadge(label, state = "planned") {
  const badge = document.createElement("span");
  badge.className = `status-pill node-status-badge node-status-badge--${state}`;
  badge.dataset.agentState = state;
  badge.textContent = label;
  return badge;
}

function getNodeIdentity(node = {}) {
  const normalizedNode = node && typeof node === "object" ? node : {};
  return normalizedNode.kind === "application-host" ? normalizedNode.applicationHost || {} : normalizedNode.agentIdentity || {};
}

function getNodeCapabilities(node = {}) {
  return node?.capabilities && typeof node.capabilities === "object" ? node.capabilities : {};
}

function isWindowsAgentNode(node = {}) {
  const identity = getNodeIdentity(node);
  const capabilities = getNodeCapabilities(node);
  return node?.kind === "agent" && (capabilities.windowsMvp === true || capabilities.os === "windows" || identity.platform === "win32" || node.platform === "win32");
}

function getWindowsAgentMvpSummary(node = {}) {
  if (!isWindowsAgentNode(node)) return "";
  const capabilities = getNodeCapabilities(node);
  const docker = capabilities.supportsDocker === true
    ? "Docker supported"
    : capabilities.supportsDocker === false
      ? "Docker unavailable"
      : "Docker checked from Docker page";
  const files = capabilities.supportsFileRoots === false ? "file roots unavailable" : "safe file roots";
  return `Windows Agent MVP: health, ${files}, Public Access, and ${docker}. Game-server hosting comes later.`;
}

function formatNodeLastSeen(node = {}) {
  const value = node.connection?.lastSeen || node.updatedAt || node.createdAt;
  return value ? formatDateTime(value) : "Never";
}

function formatNodePlatform(node = {}) {
  const identity = getNodeIdentity(node);
  if (node.kind === "application-host") {
    return identity.operatingSystem || node.operatingSystem || "Local OS";
  }
  return identity.operatingSystem || identity.platform || "Agent OS unavailable";
}

function formatNodeAgentContext(node = {}) {
  const connectionState = getNodeConnectionState(node);
  if (node?.kind === "application-host") {
    return `${connectionState.label} · ${formatNodePlatform(node)} · ${node.modeLabel || "Local Application"}`;
  }
  const identity = getNodeIdentity(node);
  const version = identity.agentVersion ? `Agent ${identity.agentVersion}` : "Agent version unknown";
  return `${connectionState.label} · ${formatNodePlatform(node)} · ${version}`;
}

function getNodeTypeLabel(node = {}) {
  if (node.kind === "application-host") return node.nodeTypeLabel || "Application Host";
  if (isWindowsAgentNode(node)) return node.localAgent ? "Windows Local Agent Node" : "Windows Agent Node";
  return node.modeLabel || (node.localAgent ? "Registered Local Agent Node" : "Registered Remote Agent Node");
}

function formatNodeCpu(node = {}) {
  const identity = getNodeIdentity(node);
  const snapshot = getSystemSnapshotForNode(node);
  const model = snapshot?.cpu?.model || identity.cpu?.model || "CPU model unavailable";
  const cores = Number.isFinite(snapshot?.cpu?.cores) ? snapshot.cpu.cores : identity.cpu?.cores;
  const usage = Number.isFinite(snapshot?.cpu?.usagePercent) ? ` · ${formatPercent(snapshot.cpu.usagePercent)} used` : "";
  return `${model}${Number.isFinite(cores) ? ` · ${cores} core${cores === 1 ? "" : "s"}` : ""}${usage}`;
}

function formatNodeMemory(node = {}) {
  const identity = getNodeIdentity(node);
  const snapshot = getSystemSnapshotForNode(node);
  const memory = snapshot?.memory || identity.memory || null;
  if (!memory) return "Memory metrics unavailable.";
  const percent = Number.isFinite(memory.percent) ? `${formatPercent(memory.percent)} · ` : "";
  return `${percent}${formatBytes(memory.used)} / ${formatBytes(memory.total)} used`;
}

function formatNodeStorage(node = {}) {
  const snapshot = getSystemSnapshotForNode(node);
  if (snapshot?.disk) {
    return `${formatPercent(snapshot.disk.percent)} used · ${formatBytes(snapshot.disk.free)} free · ${snapshot.disk.mount || "mount unavailable"}`;
  }
  const identity = getNodeIdentity(node);
  if (node.kind === "application-host" && identity.storage?.message) {
    return identity.storage.message;
  }
  return "Storage metrics unavailable until this node is selected and Dashboard metrics load.";
}

function getNodeUnsupportedFeatureSummary(node = {}) {
  if (node.kind === "application-host") {
    return "Remote Agent APIs, Agent token management, and remote Docker controls require an Agent node. Local desktop files and dashboard metrics remain available.";
  }
  if (isWindowsAgentNode(node)) {
    const capabilities = getNodeCapabilities(node);
    return [
      getWindowsAgentMvpSummary(node),
      capabilities.unsupportedActions?.ssh || "SSH is unavailable for Windows Agent MVP nodes unless configured separately.",
      capabilities.unsupportedActions?.gameServers || "SteamCMD and game-server hosting are coming later for Windows nodes.",
    ].filter(Boolean).join(" ");
  }
  return "Desktop uptime, Electron version, and local developer-mode fields apply only to the application host.";
}

function setNodeSummary(name, value) {
  nodeSummaryFields.forEach((field) => {
    if (field.dataset.nodeSummary === name) {
      field.textContent = String(value ?? "0");
    }
  });
}

function renderNodeSummary() {
  const nodes = getNodePickerNodes();
  const remoteNodes = nodes.filter((node) => node.kind === "agent");
  const online = nodes.filter((node) => getNodeVisualState(node) === "online").length;
  const offline = nodes.filter((node) => ["offline", "error"].includes(getNodeVisualState(node))).length;
  const docker = remoteNodes.filter((node) => node.docker?.enabled !== false).length;
  const connectedAgent = remoteNodes.find((node) => getNodeConnectionState(node).state === "Connected");
  setNodeSummary("total", nodes.length);
  setNodeSummary("online", online);
  setNodeSummary("offline", offline);
  setNodeSummary("docker", docker);
  setNodeSummary("connected", connectedAgent ? connectedAgent.displayName || connectedAgent.name || "Agent" : "None");
  const health = getSharedNodeHealthModel();
  setNodeSummary("health", health.state);
  setNodeSummary("healthIssues", health.issueCount);
}

function setNodeFormBusy(isBusy, label = "") {
  nodeFormBusy = Boolean(isBusy);
  nodeModal?.querySelectorAll('[data-node-action="save"], [data-node-action="test-form"], [data-node-action="delete"], [data-node-action="generate-token"], [data-node-action="pair-code"], [data-node-action="paste-pairing-code"], [data-node-action="restart-pairing"], [data-node-action="pairing-retry-help"], [data-node-action="cancel-pairing"]').forEach((button) => {
    button.disabled = nodeFormBusy;
  });
  updateNodePairingControls();
  updateNodeTokenControls();
  if (nodeFormStatus) {
    nodeFormStatus.hidden = !label;
    nodeFormStatus.textContent = label || "";
  }
}

function updateNodePairingControls() {
  const pairButton = nodeModal?.querySelector('[data-node-action="pair-code"]');
  if (pairButton) {
    pairButton.disabled = nodeFormBusy || nodePairingSubmitInFlight || !String(nodePairingCodeInput?.value || "").trim();
  }
}

function setNodeFormErrors(errors = {}) {
  nodeFieldErrors.forEach((target) => {
    const fieldName = target.dataset.nodeFieldError;
    const message = errors[fieldName] || "";
    target.textContent = message;
    const input = nodeModal?.querySelector(`[data-node-field="${fieldName}"]`);
    input?.setAttribute("aria-invalid", message ? "true" : "false");
  });
}

function setNodePairingError(message = "") {
  nodeFieldErrors.forEach((target) => {
    if (target.dataset.nodeFieldError === "pairingCode") {
      target.textContent = message;
    }
  });
  nodePairingCodeInput?.setAttribute("aria-invalid", message ? "true" : "false");
}

function setNodePairingRetryVisible(visible) {
  if (nodePairingRetryActions) nodePairingRetryActions.hidden = !visible;
}

function isExpiredPairingError(error, message = "") {
  const combined = `${error?.code || ""} ${error?.statusCode || ""} ${message || error?.message || ""}`;
  return /PAIRING_EXPIRED|PAIRING_REJECTED|pairing session.*(expired|no longer|unavailable)|session is no longer available/i.test(combined);
}

function getNodePairingCodeAgentUrl(code = "") {
  const [, encoded] = String(code || "").trim().split(".", 2);
  if (!encoded) return "";
  try {
    const base64 = encoded.replace(/-/g, "+").replace(/_/g, "/");
    const padded = `${base64}${"=".repeat((4 - (base64.length % 4)) % 4)}`;
    const payload = JSON.parse(atob(padded));
    return String(payload?.agentUrl || "").trim();
  } catch {
    return "";
  }
}

function getNodePairingMismatchMessage(pairingUrl = "", expectedUrl = "", expectedName = "selected Agent") {
  if (!pairingUrl || !expectedUrl || pairingUrl === expectedUrl) return "";
  let pairingHost = pairingUrl;
  try {
    const parsed = new URL(pairingUrl);
    pairingHost = parsed.host;
  } catch {}
  let expectedHost = expectedUrl;
  try {
    expectedHost = new URL(expectedUrl).host;
  } catch {}
  const isLocalhost = /^127\.0\.0\.1(?::|$)|^localhost(?::|$)/i.test(pairingHost);
  return `This code belongs to the ${isLocalhost ? "Windows Local Agent" : "Agent"} at ${pairingHost}. Generate a code from ${expectedName} at ${expectedHost} instead.`;
}

function validateNodeFormPayload(payload = {}) {
  const errors = {};
  if (!String(payload.displayName || "").trim()) errors.displayName = "Enter a node name.";
  else if (String(payload.displayName || "").trim().length > 80) errors.displayName = "Use 80 characters or fewer.";
  try {
    const url = new URL(String(payload.agentUrl || "").trim());
    if (!["http:", "https:"].includes(url.protocol)) errors.agentUrl = "Use an http or https Agent URL.";
    if (!url.hostname) errors.agentUrl = "Enter a host for this Agent URL.";
  } catch {
    errors.agentUrl = "Enter a valid Agent URL.";
  }
  if (!nodeEditId && !String(payload.agentToken || "").trim()) {
    errors.agentToken = "Enter the Agent token for this node.";
  }
  return errors;
}

function getNodeTokenInput() {
  return nodeModal?.querySelector('[data-node-field="agentToken"]') || null;
}

function updateNodeTokenControls(options = {}) {
  const tokenInput = getNodeTokenInput();
  const copyButton = nodeModal?.querySelector('[data-node-action="copy-token"]');
  const generateButton = nodeModal?.querySelector('[data-node-action="generate-token"]');
  const hasUnsavedToken = Boolean(String(tokenInput?.value || "").trim());
  if (copyButton) {
    copyButton.disabled = nodeFormBusy || !hasUnsavedToken;
  }
  if (generateButton) {
    generateButton.textContent = nodeEditId ? "Generate New Token" : "Generate Token";
  }
  if (nodeTokenNote) {
    if (options.generated) {
      nodeTokenNote.textContent = "Generating a new token does not update the Agent automatically. No connection changes occur until you save.";
    } else if (nodeEditId && !hasUnsavedToken) {
      nodeTokenNote.textContent = "Your saved token is stored securely and cannot be displayed here. Generate a new token to replace it.";
    } else {
      nodeTokenNote.textContent = "Generate a secure token, copy it to the Agent machine, and configure the same token on both sides.";
    }
  }
  if (nodeTokenSetup) {
    nodeTokenSetup.hidden = !hasUnsavedToken;
  }
}

async function generateNodeAgentToken() {
  const desktopApiState = getDesktopApiState();
  const tokenInput = getNodeTokenInput();
  if (!desktopApiState.hasNodes || nodeFormBusy || !tokenInput || typeof desktopApiState.api.nodes.generateToken !== "function") {
    return;
  }
  try {
    setNodeFormBusy(true, "Generating secure Agent token...");
    const result = await desktopApiState.api.nodes.generateToken();
    tokenInput.value = String(result?.token || "");
    tokenInput.dataset.unsavedCredential = tokenInput.value ? "true" : "false";
    updateNodeTokenControls({ generated: true });
    setNodeFormBusy(false, nodeEditId
      ? "After saving this new token, update the Agent configuration on this machine and restart the Agent. The node may appear offline until both sides use the same token."
      : "Agent token generated. Copy it to the Agent machine before saving.");
    showToast("Secure Agent token generated.", "success");
  } catch (error) {
    const message = normalizeIpcErrorMessage(error, "Agent token could not be generated.");
    setNodeFormBusy(false, message);
    showToast(message, "error");
  }
}

async function copyNodeAgentToken() {
  const tokenInput = getNodeTokenInput();
  const value = String(tokenInput?.value || "").trim();
  if (!value) {
    showToast("Generate or enter a new token before copying.", "warning");
    return;
  }
  try {
    await navigator.clipboard.writeText(value);
    showToast("Agent token copied.", "success");
  } catch {
    showToast("Agent token could not be copied.", "error");
  }
}

function setNodeModalVisible(isVisible, node = null) {
  if (!nodeModal) return;
  nodeModal.hidden = !isVisible;
  if (isVisible) {
    nodeEditId = node?.kind === "agent" ? node.id : null;
    nodePairingSubmitInFlight = false;
    nodePairingLastSubmittedCode = "";
    setNodeFormErrors({});
    setNodePairingError("");
    setNodePairingRetryVisible(false);
    if (nodePairingCodeInput) nodePairingCodeInput.value = "";
    setNodeFormBusy(false, "");
    if (nodeModalTitle) nodeModalTitle.textContent = nodeEditId ? "Edit Node" : "Add Node";
    const saveButton = nodeModal.querySelector('[data-node-action="save"]');
    if (saveButton) saveButton.textContent = nodeEditId ? "Save Node" : "Register Node";
    const deleteButton = nodeModal.querySelector('[data-node-action="delete"]');
    if (deleteButton) deleteButton.hidden = !nodeEditId;
    nodeFields.forEach((field) => {
      const key = field.dataset.nodeField;
      if (key === "dockerEnabled") {
        field.checked = node?.docker?.enabled !== false;
      } else if (key === "enabled") {
        field.checked = node?.enabled !== false;
      } else if (key === "displayName") {
        field.value = node?.displayName || "";
      } else if (key === "agentUrl") {
        field.value = node?.agentUrl || "";
      } else if (key === "agentToken") {
        field.value = "";
        field.dataset.unsavedCredential = "false";
        field.placeholder = nodeEditId ? "Saved token is stored securely" : "Enter or generate an Agent token";
      } else if (key === "description") {
        field.value = node?.description || "";
      } else if (key === "tags") {
        field.value = Array.isArray(node?.tags) ? node.tags.join(", ") : "";
      }
    });
    if (!nodeModalCleanup) {
      nodeModalCleanup = activateModal(nodeModal, { initialFocus: () => nodeModal.querySelector("[data-node-field=\"displayName\"]") });
    }
    updateNodeTokenControls();
  } else if (nodeModalCleanup) {
    nodePairingSubmitInFlight = false;
    nodePairingLastSubmittedCode = "";
    nodePairingSubmissionSerial += 1;
    nodeModalCleanup();
    nodeModalCleanup = null;
    nodeEditId = null;
    setNodeFormErrors({});
    setNodePairingError("");
    setNodePairingRetryVisible(false);
    setNodeFormBusy(false, "");
    if (nodeTokenSetup) nodeTokenSetup.hidden = true;
  }
}

function openNodeDetails(nodeId) {
  const node = getNodePickerNodes().find((candidate) => candidate.id === nodeId);
  if (!node || !nodeDetailsModal) return;
  nodeDetailsId = node.id;
  const identity = getNodeIdentity(node);
  const visualState = getNodeVisualState(node);
  const health = node.id === getSelectedNodeId() ? refreshNodeHealth({ notify: false }) : getSharedNodeHealthModel(node);
  if (nodeDetailsTitle) nodeDetailsTitle.textContent = node.displayName || node.id || "Node";
  if (nodeDetailsSummary) {
    const connectionState = getNodeConnectionState(node);
    nodeDetailsSummary.textContent = `${getNodeTypeLabel(node)} · ${connectionState.label} · ${health.issueCount} health issue${health.issueCount === 1 ? "" : "s"}`;
  }
  if (nodeDetailsBadges) {
    const badges = [createNodeBadge(getNodeStatusLabel(node), visualState)];
    if (isWindowsAgentNode(node)) {
      badges.push(createNodeBadge("Windows node", "planned"));
      if (getNodeCapabilities(node).supportsGameServers !== true) {
        badges.push(createNodeBadge("Hosting later", "warning"));
      }
    }
    nodeDetailsBadges.replaceChildren(...badges);
  }
  const capabilities = getNodeCapabilities(node);
  const values = {
    hostname: identity.hostname || node.displayName || "Unavailable",
    os: formatNodePlatform(node),
    version: identity.agentVersion || (node.kind === "application-host" ? runtimeInfoState?.releaseLabel || runtimeInfoState?.version : null) || "Unavailable",
    cpu: formatNodeCpu(node),
    memory: formatNodeMemory(node),
    storage: formatNodeStorage(node),
    desktopUptime: node.kind === "application-host" ? formatDuration(identity.desktopUptimeSeconds || 0) : "Unavailable: desktop uptime applies only to the application host.",
    electronVersion: node.kind === "application-host" ? identity.electronVersion || runtimeInfoState?.electron || "Unavailable" : "Unavailable: Electron runs on the application host, not this Agent.",
    appVersion: node.kind === "application-host" ? identity.appVersion || runtimeInfoState?.releaseLabel || runtimeInfoState?.appVersion || "Unavailable" : "Unavailable: app version belongs to the desktop shell.",
    developerMode: node.kind === "application-host" ? (identity.developerMode || runtimeInfoState?.developmentMode ? "Enabled" : "Disabled") : "Unavailable: developer mode belongs to the desktop shell.",
    runningState: node.kind === "application-host" ? identity.runningState || "running" : node.connection?.connected ? "Agent connected" : "Agent unavailable",
    docker: node.kind === "application-host"
      ? "Unsupported here: Docker workspace controls require an Agent node."
      : node.docker?.enabled === false
        ? "Disabled"
        : capabilities.supportsDocker === true
          ? "Enabled: Docker support reported by Agent."
          : capabilities.supportsDocker === false
            ? "Not supported on this Windows node."
            : isWindowsAgentNode(node)
              ? "Conditional: refresh Docker to detect Docker Desktop or Docker Engine."
              : "Enabled",
    lastSeen: formatNodeLastSeen(node),
    connection: getNodeConnectionSummary(node),
    url: node.kind === "application-host" ? "Local Application" : node.agentUrl || "Unavailable",
    token: node.kind === "application-host" ? "Not required" : node.hasToken ? "Configured" : "Missing",
    unsupportedFeatures: getNodeUnsupportedFeatureSummary(node),
  };
  nodeDetailsFields.forEach((field) => {
    field.textContent = values[field.dataset.nodeDetail] || "Unavailable";
  });
  renderNodeHealth(health);
  nodeDetailsModal.hidden = false;
  if (!nodeDetailsCleanup) {
    nodeDetailsCleanup = activateModal(nodeDetailsModal, { initialFocus: () => nodeDetailsModal.querySelector("[data-node-action=\"close-details\"]") });
  }
}

function setNodeDetailsVisible(isVisible) {
  if (!nodeDetailsModal) return;
  nodeDetailsModal.hidden = !isVisible;
  if (!isVisible && nodeDetailsCleanup) {
    nodeDetailsCleanup();
    nodeDetailsCleanup = null;
    nodeDetailsId = null;
  }
}

function getNodePickerNodes() {
  return Array.isArray(nodesState.nodes) ? nodesState.nodes : [];
}

function syncNodeSelectorControls() {
  const selectedNodeId = getSelectedNodeId();
  nodeTargetSelects.forEach((select) => {
    select.value = selectedNodeId;
  });
  renderNodePicker();
}

function positionNodePicker() {
  if (!nodePicker || !nodePickerTrigger || nodePicker.hidden) {
    return;
  }
  const triggerRect = nodePickerTrigger.getBoundingClientRect();
  const width = Math.min(340, Math.max(260, Math.round(triggerRect.width + 48)));
  const viewportGap = 14;
  const pickerHeight = Math.min(420, Math.max(220, nodePicker.offsetHeight || 280));
  const left = Math.min(
    Math.max(viewportGap, triggerRect.left),
    Math.max(viewportGap, window.innerWidth - width - viewportGap),
  );
  const top = Math.max(viewportGap, Math.min(triggerRect.top - pickerHeight - 10, window.innerHeight - pickerHeight - viewportGap));
  nodePicker.style.width = `${width}px`;
  nodePicker.style.left = `${left}px`;
  nodePicker.style.top = `${top}px`;
}

function updateNodePickerActiveDescendant() {
  if (!nodePickerList) {
    return;
  }
  const options = Array.from(nodePickerList.querySelectorAll("[data-node-picker-option]"));
  options.forEach((option, index) => {
    option.classList.toggle("is-active", index === nodePickerActiveIndex);
    option.tabIndex = index === nodePickerActiveIndex ? 0 : -1;
  });
  const active = options[nodePickerActiveIndex];
  if (active) {
    nodePickerList.setAttribute("aria-activedescendant", active.id);
  } else {
    nodePickerList.removeAttribute("aria-activedescendant");
  }
}

function renderNodePicker() {
  if (!nodePickerList) {
    return;
  }
  const nodes = getNodePickerNodes();
  nodePickerList.replaceChildren();
  if (nodePickerStatus) {
    nodePickerStatus.textContent = nodes.length
      ? "Choose a system to manage."
      : getDesktopApiState().hasNodes
        ? "No selectable nodes are available."
        : "Node service is loading.";
  }
  if (!nodes.length) {
    const empty = document.createElement("div");
    empty.className = "node-picker-empty";
    empty.textContent = getDesktopApiState().hasNodes
      ? "No selectable nodes are available. This PC will appear after node setup finishes."
      : "Node service is unavailable. This PC mode will remain available when startup completes.";
    nodePickerList.append(empty);
    return;
  }

  const selectedIndex = Math.max(0, nodes.findIndex((node) => node.id === getSelectedNodeId()));
  nodePickerActiveIndex = Math.min(Math.max(nodePickerActiveIndex, 0), nodes.length - 1);
  if (!nodePickerOpen) {
    nodePickerActiveIndex = selectedIndex;
  }

  nodes.forEach((node, index) => {
    const visualState = getNodeVisualState(node);
    const connectionState = getNodeConnectionState(node);
    const option = document.createElement("button");
    option.type = "button";
    option.id = `node-picker-option-${String(node.id || index).replace(/[^a-z0-9_-]/gi, "-")}`;
    option.className = "node-picker-option";
    option.dataset.nodePickerOption = node.id;
    option.dataset.agentState = visualState;
    option.setAttribute("role", "option");
    option.setAttribute("aria-selected", node.id === getSelectedNodeId() ? "true" : "false");
    option.append(createAgentRobotIcon(visualState));
    const copy = document.createElement("span");
    copy.className = "node-picker-option__copy";
    const title = document.createElement("strong");
    title.textContent = node.displayName || node.id || "Unnamed node";
    const detail = document.createElement("small");
    detail.textContent = node.kind === "application-host"
      ? `${formatNodeAgentContext(node)} · Built in`
      : `${formatNodeAgentContext(node)} · ${getNodeTypeLabel(node)} · ${node.agentUrl || "Agent API"}`;
    copy.append(title, detail);
    const badge = document.createElement("span");
    badge.className = "node-picker-option__badge";
    badge.textContent = node.id === getSelectedNodeId() ? "Current" : connectionState.label;
    option.append(copy, badge);
    option.addEventListener("click", async (event) => {
      event.stopPropagation();
      closeNodePicker();
      await selectNode(node.id || "application-host");
    });
    nodePickerList.append(option);
  });
  updateNodePickerActiveDescendant();
  positionNodePicker();
}

function setNodePickerOpen(open) {
  if (!nodePicker || !nodePickerTrigger) {
    return;
  }
  const nextOpen = Boolean(open);
  nodePickerOpen = nextOpen;
  nodePicker.hidden = !nextOpen;
  nodePickerTrigger.setAttribute("aria-expanded", nextOpen ? "true" : "false");
  nodePickerTrigger.classList.toggle("is-node-picker-open", nextOpen);
  if (nextOpen) {
    const nodes = getNodePickerNodes();
    nodePickerActiveIndex = Math.max(0, nodes.findIndex((node) => node.id === getSelectedNodeId()));
    renderNodePicker();
    requestAnimationFrame(positionNodePicker);
  }
}

function openNodePicker() {
  setNodePickerOpen(true);
}

function closeNodePicker() {
  setNodePickerOpen(false);
}

function toggleNodePicker() {
  if (nodePickerOpen) {
    closeNodePicker();
    return;
  }
  openNodePicker();
}

async function activateNodePickerOption(index) {
  const nodes = getNodePickerNodes();
  const node = nodes[index];
  if (!node) {
    return;
  }
  closeNodePicker();
  await selectNode(node.id || "application-host");
}

function renderNodes() {
  renderRoutingDiagnostics();
  syncAgentConnectionDisplayWithSelectedNode();
  renderNodeSummary();
  renderFriendlyDashboard();
  nodeTargetSelects.forEach((select) => {
    select.replaceChildren();
    (nodesState.nodes || []).forEach((node) => {
      const option = document.createElement("option");
      option.value = node.id;
      option.textContent = node.default ? `${node.displayName} (default)` : node.displayName;
      select.append(option);
    });
    select.value = (nodesState.nodes || []).some((node) => node.id === getSelectedNodeId()) ? getSelectedNodeId() : "application-host";
  });

  if (nodeStatus) {
    const selected = (nodesState.nodes || []).find((node) => node.id === getSelectedNodeId());
    nodeStatus.textContent = selected?.displayName || "Default";
    nodeStatus.dataset.agentState = getNodeVisualState(selected);
  }

  if (sidebarFooter) {
    const selected = getSelectedNode();
    const nodeName = selected?.displayName || "Application Host";
    const nodeState = getNodeVisualState(selected);
    const connectionState = getNodeConnectionState(selected);
    const nameTarget = sidebarFooter.querySelector("[data-node-picker-label]");
    const detailTarget = sidebarFooter.querySelector("[data-node-picker-detail]");
    if (nameTarget) {
      nameTarget.textContent = nodeName;
    }
    if (detailTarget) {
      detailTarget.textContent = nodeSwitchInProgress
        ? "Switching node..."
        : securityState?.localOwnerAuthenticated !== true
          ? "Unlock AnxOS to start the Application Host."
        : !selected
          ? "Application Host unavailable."
        : selected.kind === "application-host"
          ? selected.modeLabel || "Local Application"
          : formatNodeAgentContext(selected);
    }
    sidebarFooter.dataset.agentState = nodeState;
    sidebarFooter.dataset.tooltip = `${nodeName} | ${nodeSwitchInProgress ? "Switching node" : connectionState.secondary}`;
  }

  if (nodeMessage) {
    const remoteCount = (nodesState.nodes || []).filter((node) => node.kind === "agent").length;
    nodeMessage.textContent = remoteCount > 0
      ? `${remoteCount} Agent node(s) registered. The application host remains available.`
      : "The application host is selected. Register an Agent node to manage another machine.";
  }

  if (nodeList) {
    nodeList.replaceChildren();
    const nodes = nodesState.nodes || [];
    const remoteCount = nodes.filter((node) => node.kind === "agent").length;
    if (remoteCount === 0) {
      const empty = document.createElement("div");
      empty.className = "nodes-empty-state";
      const title = document.createElement("strong");
      title.textContent = "No remote nodes have been registered yet.";
      const copy = document.createElement("p");
      copy.textContent = "This PC is ready. Add a remote Agent node to manage another PC or server.";
      const action = document.createElement("button");
      action.type = "button";
      action.className = "primary-button";
      action.textContent = "Add Node";
      action.addEventListener("click", () => setNodeModalVisible(true));
      empty.append(title, copy, action);
      nodeList.append(empty);
    }
    nodes.forEach((node) => {
      const state = getNodeVisualState(node);
      const connectionState = getNodeConnectionState(node);
      const health = getSharedNodeHealthModel(node);
      const item = document.createElement("article");
      item.className = "download-item node-card";
      item.dataset.agentState = state;
      item.classList.toggle("is-selected", node.id === getSelectedNodeId());
      item.append(createAgentRobotIcon(state));
      const body = document.createElement("div");
      body.className = "agent-node-copy node-card__body";
      const header = document.createElement("div");
      header.className = "node-card__header";
      const titleGroup = document.createElement("div");
      const title = document.createElement("strong");
      title.textContent = node.displayName || node.id;
      const detail = document.createElement("small");
      detail.textContent = node.kind === "application-host"
        ? `${formatNodePlatform(node)} · ${node.modeLabel || "Local Application"} · Built in`
        : `${formatNodePlatform(node)} · ${getNodeTypeLabel(node)} · ${node.agentUrl || "Agent API"}`;
      titleGroup.append(title, detail);
      const badges = document.createElement("div");
      badges.className = "node-card__badges";
      badges.append(createNodeBadge(getNodeStatusLabel(node), state));
      if (isWindowsAgentNode(node)) {
        badges.append(createNodeBadge("Windows", "planned"));
        if (getNodeCapabilities(node).supportsGameServers !== true) {
          badges.append(createNodeBadge("MVP", "warning"));
        }
      }
      header.append(titleGroup, badges);
      const meta = document.createElement("dl");
      meta.className = "node-card__meta";
      [
        ["Context", node.kind === "application-host" ? "Local Application Host" : `${getNodeTypeLabel(node)} · ${node.agentUrl || "Unavailable"}`],
        ["Connection", `${connectionState.primary} - ${connectionState.secondary}`],
        ...(isWindowsAgentNode(node) ? [["Windows MVP", getWindowsAgentMvpSummary(node)]] : []),
        ["Last seen", formatNodeLastSeen(node)],
        ["Health", `${health.state} · ${health.issueCount} issue${health.issueCount === 1 ? "" : "s"}`],
      ].forEach(([label, value]) => {
        const wrapper = document.createElement("div");
        const dt = document.createElement("dt");
        const dd = document.createElement("dd");
        dt.textContent = label;
        dd.textContent = value;
        wrapper.append(dt, dd);
        meta.append(wrapper);
      });
      const actions = document.createElement("div");
      actions.className = "node-card__actions";
      const nodeActions = [
        ["select", node.id === getSelectedNodeId() ? "Selected" : "Select"],
        ["test", "Test Connection"],
        ["edit", "Edit"],
        ["refresh", "Refresh"],
        ["details", "View Details"],
        ["remove", node.kind === "application-host" ? "Built In" : "Remove"],
      ];
      if (getNodeConnectionState(node).state === "Authentication Required") {
        nodeActions.splice(3, 0, ["repair", "Re-pair Existing Node"]);
      }
      nodeActions.forEach(([actionName, label]) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = actionName === "remove" ? "inline-action inline-action--danger" : "inline-action";
        button.dataset.nodeCardAction = actionName;
        button.dataset.nodeId = node.id;
        button.textContent = label;
        button.disabled = (node.kind === "application-host" && ["edit", "remove"].includes(actionName)) || (actionName === "select" && node.id === getSelectedNodeId());
        if (node.kind === "application-host" && actionName === "remove") {
          button.title = node.removeUnavailableReason || "The built-in Application Host cannot be removed.";
          button.setAttribute("aria-label", button.title);
        }
        actions.append(button);
      });
      body.append(header, meta, actions);
      item.append(body);
      item.addEventListener("click", (event) => {
        if (event.target.closest("[data-node-card-action]")) return;
        openNodeDetails(node.id);
      });
      nodeList.append(item);
    });
  }
  renderNodePicker();
}

async function refreshNodes(options = {}) {
  const desktopApiState = getDesktopApiState();
  const previousSelectedNodeId = nodesState.selectedNodeId || "application-host";
  if (!desktopApiState.hasNodes) {
    nodesState = { selectedNodeId: "application-host", applicationHost: null, nodes: [{ id: "application-host", kind: "application-host", displayName: "Application Host", default: true, local: true }] };
    nodeHealthSnapshotCache.clear();
    refreshNodeHealth({ notify: false });
    renderNodes();
    return;
  }
  const requestContext = getNodeRequestContext("nodes-refresh");
  try {
    const nextNodesState = options.forceHealthRefresh || typeof desktopApiState.api.nodes.restore !== "function"
      ? await desktopApiState.api.nodes.list()
      : await desktopApiState.api.nodes.restore();
    if (!isNodeRequestCurrent(requestContext)) return;
    nodesState = nextNodesState;
    if (previousSelectedNodeId !== "application-host" && nodesState.selectedNodeId !== previousSelectedNodeId) {
      const selected = (nodesState.nodes || []).find((node) => node.id === nodesState.selectedNodeId);
      showToast(`Selected node was unavailable. Switched to ${selected?.displayName || "the available default node"}.`, "warning");
    }
  } catch (error) {
    if (!isNodeRequestCurrent(requestContext)) return;
    nodesState = {
      ...nodesState,
      selectedNodeId: previousSelectedNodeId,
      stale: true,
      error: normalizeIpcErrorMessage(error, "Node registry unavailable."),
    };
  }
  nodeHealthSnapshotCache.clear();
  if (nodesState.credentialsLocked === true || securityState?.localOwnerAuthenticated !== true) {
    renderNodes();
    return;
  }
  refreshNodeHealth();
  renderNodes();
}

function startNodeRefreshPolling() {
  if (nodeRefreshTimer || document.hidden) return;
  nodeRefreshTimer = window.setInterval(() => {
    if (getActivePageName() !== "nodes" || document.hidden) {
      return;
    }
    refreshNodes();
  }, 5000);
}

function stopNodeRefreshPolling() {
  if (nodeRefreshTimer) {
    window.clearInterval(nodeRefreshTimer);
    nodeRefreshTimer = null;
  }
}

async function selectNode(nodeId) {
  const desktopApiState = getDesktopApiState();
  const nextNodeId = nodeId || "application-host";
  const previousNodeId = getSelectedNodeId();
  const previousNodesState = {
    selectedNodeId: nodesState.selectedNodeId || "application-host",
    nodes: Array.isArray(nodesState.nodes) ? [...nodesState.nodes] : [],
  };
  if (nextNodeId === previousNodeId && !nodeSwitchInProgress) {
    renderNodes();
    return { changed: false, selectedNodeId: previousNodeId };
  }
  if (!((nodesState.nodes || []).some((node) => node.id === nextNodeId))) {
    showToast("That node is no longer available.", "warning");
    renderNodes();
    return { changed: false, selectedNodeId: previousNodeId };
  }

  nodesState.selectedNodeId = nextNodeId;
  selectedNodeContextVersion += 1;
  nodeSwitchInProgress = true;
  const context = getNodeRequestContext("select-node");
  syncNodeSelectorControls();
  resetNodeScopedRendererState(`Switching to ${getSelectedNode()?.displayName || nodesState.selectedNodeId}...`);
  if (desktopApiState.hasNodes) {
    try {
      const persistedState = await desktopApiState.api.nodes.select(nodesState.selectedNodeId);
      if (persistedState?.selectedNodeId && Array.isArray(persistedState.nodes)) {
        nodesState = persistedState;
      }
    } catch (error) {
      nodesState = previousNodesState;
      nodeSwitchInProgress = false;
      selectedNodeContextVersion += 1;
      renderNodes();
      showToast(normalizeIpcErrorMessage(error, "Node could not be selected."), "warning");
      return { changed: false, selectedNodeId: getSelectedNodeId(), error };
    }
  }
  renderNodes();
  if (isNodeRequestCurrent(context)) {
    await reloadActiveNodeData(context);
  }
  return { changed: true, selectedNodeId: getSelectedNodeId() };
}

function getNodeFormPayload() {
  const payload = { docker: {} };
  if (nodeEditId) {
    payload.id = nodeEditId;
  }
  nodeFields.forEach((field) => {
    if (field.dataset.nodeField === "dockerEnabled") {
      payload.docker.enabled = field.checked;
    } else if (field.dataset.nodeField === "enabled") {
      payload.enabled = field.checked;
    } else if (field.dataset.nodeField === "tags") {
      payload.tags = String(field.value || "").split(",").map((tag) => tag.trim()).filter(Boolean);
    } else {
      payload[field.dataset.nodeField] = field.value;
    }
  });
  return payload;
}

async function saveNodeFromSettings() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasNodes || nodeFormBusy) {
    return;
  }
  if (blockProtectedAction("Unlock AnxOS to add nodes.")) return;
  const payload = getNodeFormPayload();
  const errors = validateNodeFormPayload(payload);
  setNodeFormErrors(errors);
  if (Object.keys(errors).length) {
    setNodeFormBusy(false, "Fix the highlighted fields before saving.");
    showToast("Node form needs attention.", "warning");
    return;
  }
  try {
    const wasEditing = Boolean(nodeEditId);
    setNodeFormBusy(true, wasEditing ? "Saving node..." : "Registering node...");
    await desktopApiState.api.nodes.save(payload);
    nodeFields.forEach((field) => {
      if (field.type !== "checkbox") {
        field.value = "";
      }
    });
    setNodeModalVisible(false);
    await refreshNodes();
    showToast(wasEditing ? "Node updated." : "Node registered.");
  } catch (error) {
    const message = normalizeIpcErrorMessage(error, "Node could not be saved.");
    setNodeFormBusy(false, message);
    showToast(message, "error");
    return;
  }
  setNodeFormBusy(false, "");
}

async function testNodeFormConnection() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasNodes || nodeFormBusy) {
    return;
  }
  if (blockProtectedAction("Unlock AnxOS to test node connections.")) return;
  const payload = getNodeFormPayload();
  const errors = validateNodeFormPayload(payload);
  setNodeFormErrors(errors);
  if (Object.keys(errors).length) {
    setNodeFormBusy(false, "Fix the highlighted fields before testing.");
    showToast("Node form needs attention.", "warning");
    return;
  }
  try {
    setNodeFormBusy(true, "Testing Agent connection...");
    const result = await desktopApiState.api.nodes.testConnection(payload);
    const detail = [
      result.agentVersion ? `Agent ${result.agentVersion}` : null,
      result.apiVersion ? `API ${result.apiVersion}` : null,
      Number.isFinite(result.latencyMs) ? `${result.latencyMs} ms` : null,
    ].filter(Boolean).join(" · ");
    setNodeFormBusy(false, detail ? `Connection verified. ${detail}` : "Connection verified.");
    showToast(result.connected ? "Node connection verified." : result.message || "Node connection needs attention.", result.connected ? "success" : "warning");
  } catch (error) {
    const message = normalizeIpcErrorMessage(error, "Node connection test failed.");
    setNodeFormBusy(false, message);
    showToast(message, "error");
  }
}

async function pairNodeFromSettings(options = {}) {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasNodes || nodeFormBusy || nodePairingSubmitInFlight || typeof desktopApiState.api.nodes.pair !== "function") {
    return;
  }
  const pairingCode = String(nodePairingCodeInput?.value || "").trim();
  if (!pairingCode) {
    setNodePairingError("Paste the temporary pairing code displayed by the Agent.");
    showToast("Pairing code is required.", "warning");
    return;
  }
  if (!options.confirmUrlChange && pairingCode === nodePairingLastSubmittedCode) {
    setNodePairingError("Generate or paste a new pairing code before trying again.");
    setNodePairingRetryVisible(true);
    showToast("Generate a new pairing code before retrying.", "warning");
    return;
  }
  const expectedNode = nodeEditId ? (nodesState.nodes || []).find((node) => node.id === nodeEditId) : null;
  const pairingAgentUrl = getNodePairingCodeAgentUrl(pairingCode);
  const expectedAgentUrl = expectedNode?.agentUrl || expectedNode?.baseUrl || "";
  const mismatchMessage = getNodePairingMismatchMessage(pairingAgentUrl, expectedAgentUrl, expectedNode?.displayName || expectedNode?.name || "the selected Agent");
  if (!options.confirmUrlChange && mismatchMessage) {
    setNodePairingError(mismatchMessage);
    setNodePairingRetryVisible(true);
    showToast(mismatchMessage, "error");
    return;
  }
  const submissionSerial = ++nodePairingSubmissionSerial;
  nodePairingSubmitInFlight = true;
  nodePairingLastSubmittedCode = pairingCode;
  try {
    setNodePairingError("");
    setNodeFormBusy(true, "Pairing Agent and securing connection...");
    const result = await desktopApiState.api.nodes.pair({ pairingCode, id: nodeEditId || null, confirmUrlChange: options.confirmUrlChange === true });
    if (submissionSerial !== nodePairingSubmissionSerial) return;
    if (nodePairingCodeInput) nodePairingCodeInput.value = "";
    nodePairingLastSubmittedCode = "";
    renderAgentPairingSetup(null, { clearCode: true });
    setNodeModalVisible(false);
    await refreshNodes();
    if (result?.selectedNodeId) {
      nodesState.selectedNodeId = result.selectedNodeId;
      syncNodeSelectorControls();
      await reloadActiveNodeData(getNodeRequestContext("node-pairing"));
    }
    showToast(`${result?.node?.displayName || "Agent"} paired successfully.`, "success");
  } catch (error) {
    if (submissionSerial !== nodePairingSubmissionSerial) return;
    const message = normalizeIpcErrorMessage(error, "Agent pairing failed.");
    if (isExpiredPairingError(error, message)) {
      const retryMessage = "Pairing code expired. Generate a new code, then paste it here.";
      if (nodePairingCodeInput) nodePairingCodeInput.value = "";
      nodePairingLastSubmittedCode = "";
      setNodePairingError(retryMessage);
      setNodePairingRetryVisible(true);
      setNodeFormBusy(false, retryMessage);
      showToast("Pairing code expired.", "warning");
      return;
    }
    if (getAgentErrorCode(error) === "PAIRING_CODE_INVALID") {
      if (nodePairingCodeInput) nodePairingCodeInput.value = "";
      nodePairingLastSubmittedCode = "";
      setNodePairingRetryVisible(true);
      setNodePairingError("Pairing code is invalid. Generate a new code, then paste it here.");
      setNodeFormBusy(false, "Pairing code is invalid. Generate a new code, then paste it here.");
      showToast("Pairing code is invalid.", "error");
      return;
    }
    if (getAgentErrorCode(error) === "NODE_REPAIR_URL_CONFIRMATION_REQUIRED") {
      const details = error?.details || {};
      const currentAgentUrl = details.currentAgentUrl || expectedAgentUrl || "Current Agent URL unavailable";
      const nextAgentUrl = details.pairingAgentUrl || pairingAgentUrl || "New Agent URL unavailable";
      const confirmed = await createSecurityConfirmation({
        title: "Confirm Agent URL change",
        message: `This will repair ${expectedNode?.displayName || "the selected node"} using a different Agent address.\n\nOld URL: ${currentAgentUrl}\nNew URL: ${nextAgentUrl}`,
        confirmLabel: "Confirm URL Change",
      });
      if (confirmed) {
        nodePairingSubmitInFlight = false;
        setNodeFormBusy(false, "Confirming Agent URL change...");
        await pairNodeFromSettings({ confirmUrlChange: true });
        return;
      }
    }
    setNodePairingError(message);
    setNodePairingRetryVisible(false);
    setNodeFormBusy(false, message);
    showToast(message, "error");
  } finally {
    if (submissionSerial === nodePairingSubmissionSerial) {
      nodePairingSubmitInFlight = false;
    }
  }
}

function restartNodePairingEntry() {
  if (nodePairingCodeInput) {
    nodePairingCodeInput.value = "";
    nodePairingCodeInput.focus();
  }
  nodePairingLastSubmittedCode = "";
  setNodePairingError("Paste the new temporary pairing code displayed by Agent setup.");
  setNodePairingRetryVisible(false);
  setNodeFormBusy(false, "Restart pairing from Agent setup, then paste the new code here.");
}

function showNodePairingRetryHelp() {
  setNodePairingRetryVisible(true);
  setNodePairingError("Open Agent Setup on that machine, select Generate New Pairing Code, then paste the new code here.");
  showToast("Open Agent Setup and generate a new pairing code.", "warning");
}

async function pasteNodePairingCode() {
  try {
    const value = await navigator.clipboard.readText();
    if (nodePairingCodeInput) {
      nodePairingCodeInput.value = String(value || "").trim();
      nodePairingLastSubmittedCode = "";
      setNodePairingError("");
      setNodePairingRetryVisible(false);
    }
    showToast("Pairing code pasted.", "success");
  } catch {
    showToast("Pairing code could not be pasted.", "error");
  }
}

async function testSelectedNode() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasNodes) {
    return;
  }
  const result = await desktopApiState.api.nodes.test(getSelectedNodeId()).catch((error) => ({ connected: false, message: error.message }));
  await refreshNodes();
  showToast(result.connected ? "Node connected." : getFriendlyErrorMessage(result.message || "Node unavailable."));
}

async function deleteSelectedNode() {
  const desktopApiState = getDesktopApiState();
  const nodeId = nodeEditId || getSelectedNodeId();
  const node = getNodePickerNodes().find((candidate) => candidate.id === nodeId);
  if (!desktopApiState.hasNodes || node?.kind === "application-host") {
    return;
  }
  if (!(await confirmDestructiveAction({
    title: "Remove this connected system?",
    message: `${node?.displayName || nodeId} will be removed from AnxOS. This does not uninstall the Agent from that system.`,
    confirmLabel: "Remove System",
  }))) {
    return;
  }
  try {
    await desktopApiState.api.nodes.delete(nodeId);
    await refreshNodes();
    showToast("Node deleted.");
  } catch (error) {
    showToast(error?.message || "Node could not be deleted.");
  }
}

async function testNodeById(nodeId) {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasNodes) return;
  const result = await desktopApiState.api.nodes.test(nodeId || getSelectedNodeId()).catch((error) => ({ connected: false, message: error.message }));
  await refreshNodes();
  showToast(result.connected ? "Node connected." : getFriendlyErrorMessage(result.message || "Node unavailable."));
}

async function deleteNodeById(nodeId) {
  const desktopApiState = getDesktopApiState();
  const node = getNodePickerNodes().find((candidate) => candidate.id === nodeId);
  if (!desktopApiState.hasNodes || !node || node.kind === "application-host") {
    return;
  }
  if (!(await confirmDestructiveAction({
    title: "Remove this connected system?",
    message: `${node.displayName || node.id} will be removed from AnxOS. This does not uninstall the Agent from that system.`,
    confirmLabel: "Remove System",
  }))) {
    return;
  }
  try {
    await desktopApiState.api.nodes.delete(node.id);
    setNodeDetailsVisible(false);
    setNodeModalVisible(false);
    await refreshNodes();
    showToast("Node removed.");
  } catch (error) {
    showToast(error?.message || "Node could not be removed.");
  }
}

function editNodeById(nodeId) {
  const node = getNodePickerNodes().find((candidate) => candidate.id === nodeId);
  if (!node || node.kind === "application-host") return;
  setNodeDetailsVisible(false);
  setNodeModalVisible(true, node);
}

async function repairNodeById(nodeId) {
  const desktopApiState = getDesktopApiState();
  const node = getNodePickerNodes().find((candidate) => candidate.id === nodeId);
  if (!desktopApiState.hasNodes || !node || node.kind === "application-host") return;
  if (typeof desktopApiState.api.nodes.repairCredential !== "function") {
    editNodeById(nodeId);
    setNodeFormBusy(false, "Paste the temporary pairing code from this Agent. Re-pairing updates this node in place and keeps its name, tags, and preferences.");
    nodePairingCodeInput?.focus();
    return;
  }
  try {
    showToast(`Checking ${node.displayName || "node"} credential fingerprints...`, "info");
    const result = await desktopApiState.api.nodes.repairCredential({ nodeId });
    const before = result?.before || {};
    const after = result?.after || before;
    const repaired = result?.repaired === true || result?.repairStatus === "already-valid";
    await refreshNodes({ forceHealthRefresh: true });
    if (nodeId === getSelectedNodeId()) {
      await reloadActiveNodeData(getNodeRequestContext("node-credential-repair"));
    }
    if (repaired && after.status === "valid") {
      const action = result?.repairStatus === "already-valid" ? "already matched" : "repaired";
      showToast(`Node credential ${action}. Fingerprint ${after.storedCredentialFingerprint || "available"}.`, "success");
      return;
    }
    editNodeById(nodeId);
    const stored = before.storedCredentialFingerprint || "missing";
    const live = before.liveHealthFingerprint || "unavailable";
    setNodeFormBusy(false, `Credential repair needs a new pairing code. Stored fingerprint ${stored}; Agent fingerprint ${live}.`);
    nodePairingCodeInput?.focus();
  } catch (error) {
    showToast(normalizeIpcErrorMessage(error, "Node credential repair failed."), "error");
    editNodeById(nodeId);
    setNodeFormBusy(false, "Paste the temporary pairing code from this Agent. Re-pairing updates this node in place and keeps its name, tags, and preferences.");
    nodePairingCodeInput?.focus();
  }
}

async function handleNodeCardAction(action, nodeId) {
  if (action === "select") await selectNode(nodeId);
  else if (action === "test") await testNodeById(nodeId);
  else if (action === "edit") editNodeById(nodeId);
  else if (action === "repair") await repairNodeById(nodeId);
  else if (action === "refresh") await refreshNodes({ forceHealthRefresh: true });
  else if (action === "details") openNodeDetails(nodeId);
  else if (action === "remove") await deleteNodeById(nodeId);
}

function getSettingInputValue(input) {
  if (input.type === "checkbox") {
    return input.checked;
  }

  return input.value;
}

function setSettingInputValue(input, value) {
  if (input.type === "checkbox") {
    input.checked = value === true;
    return;
  }

  if (value !== undefined && value !== null) {
    input.value = value;
  }
}

function syncAccentSwatches() {
  const accentInput = document.querySelector('[data-setting="appearance.accentColor"]');
  const currentAccent = String(accentInput?.value || "").toLowerCase();

  accentSwatchButtons.forEach((button) => {
    button.classList.toggle("is-active", String(button.dataset.accentSwatch || "").toLowerCase() === currentAccent);
  });
}

function getAgentSettingInputValue(input) {
  return typeof input?.value === "string" ? input.value : "";
}

function setAgentSettingInputValue(input, value) {
  if (!input) {
    return;
  }

  input.value = value !== undefined && value !== null ? value : "";
}

function getAgentSettingsFormValues() {
  const settings = { ...DEFAULT_AGENT_SETTINGS };

  agentSettingsInputs.forEach((input) => {
    const key = input.dataset.agentSetting;
    const value = getAgentSettingInputValue(input);
    if (key === "agentToken" && !value) {
      delete settings.agentToken;
      return;
    }
    settings[key] = value;
  });

  return settings;
}

function setAgentActionButtonsDisabled(disabled) {
  if (agentSettingsSaveButton) {
    agentSettingsSaveButton.disabled = disabled;
  }

  if (agentSettingsTestButton) {
    agentSettingsTestButton.disabled = disabled;
  }

  if (agentSettingsPairButton) {
    agentSettingsPairButton.disabled = disabled;
  }

  if (agentSettingsRepairButton) {
    agentSettingsRepairButton.disabled = disabled;
  }
}

function setAgentConnectionDisplay(status, message, options = {}) {
  agentConnectionState = status;

  if (agentConnectionPill) {
    const connected = status === "connected";
    const testing = status === "testing";
    agentConnectionPill.textContent = options.label || (testing ? "Testing..." : connected ? "Connected" : "Disconnected");
    agentConnectionPill.dataset.agentState = testing ? "installing" : connected ? "online" : status === "error" ? "error" : "offline";
    agentConnectionPill.classList.toggle("is-connected", connected);
    agentConnectionPill.classList.toggle("is-disconnected", !connected && !testing);
  }

  if (agentConnectionMessage) {
    agentConnectionMessage.textContent = message;
  }

  if (agentConfigSource && options.configSourceText) {
    agentConfigSource.textContent = options.configSourceText;
  }

  if (agentSettingsRepairButton) {
    agentSettingsRepairButton.hidden = options.repairAvailable !== true;
  }

  updateTitlebar();
  if (getActivePageName() === "backups") {
    renderBackups();
  }
}

function syncAgentConnectionDisplayWithSelectedNode() {
  const selected = getSelectedNode();
  const connectionState = getNodeConnectionState(selected);
  if (securityState?.localOwnerAuthenticated !== true) {
    setAgentConnectionDisplay("disconnected", "Unlock AnxOS to start the Application Host.", {
      label: "Unlock required",
    });
    return;
  }
  if (nodesState?.credentialRecovery?.degraded === true && selected?.kind === "agent") {
    setAgentConnectionDisplay("error", "Saved node credentials could not be restored. Unlock AnxOS to continue.", {
      label: "Credential recovery required",
    });
    return;
  }
  if (!selected || selected.kind === "application-host") {
    setAgentConnectionDisplay("connected", "Application Host is available locally.", {
      label: "Application Host",
    });
    return;
  }
  if (connectionState.state === "Connected") {
    setAgentConnectionDisplay("connected", `${selected.displayName || "Selected Agent"} is authenticated and reachable.`, {
      label: "Agent Connected",
    });
    return;
  }
  if (connectionState.state === "Authentication Required") {
    setAgentConnectionDisplay("error", `${selected.displayName || "Selected Agent"} rejected its saved credential.`, {
      label: "Authentication Rejected",
      repairAvailable: true,
    });
    return;
  }
  setAgentConnectionDisplay("disconnected", `${selected.displayName || "Selected Agent"} is not reachable.`, {
    label: "Agent Unavailable",
  });
}

function getAgentConfigSourceText(settingsPayload) {
  const overrides = settingsPayload?.overrides || {};
  const tokenStatus = settingsPayload?.tokenStatus || {};
  const activeOverrides = [];

  if (overrides.backendMode) {
    activeOverrides.push("Backend Mode");
  }

  if (overrides.agentUrl) {
    activeOverrides.push("Agent URL");
  }

  if (overrides.agentToken) {
    activeOverrides.push("Agent Token");
  }

  const tokenText = tokenStatus.configured
    ? "Token configured."
    : "Token not configured.";

  if (activeOverrides.length === 0) {
    return `Saved securely on this device. ${tokenText}`;
  }

  return `Saved securely on this device. Runtime overrides active for ${activeOverrides.join(", ")}. ${tokenText}`;
}

function renderAgentSettings(settingsPayload) {
  latestAgentSettingsPayload = settingsPayload || null;
  const storedSettings = {
    ...DEFAULT_AGENT_SETTINGS,
    ...(settingsPayload?.stored || {}),
  };

  agentSettingsInputs.forEach((input) => {
    if (input.dataset.agentSetting === "agentToken") {
      setAgentSettingInputValue(input, "");
      input.placeholder = settingsPayload?.tokenStatus?.configured
        ? "Shared token configured - leave blank to keep"
        : "Shared token will be generated automatically";
      return;
    }
    setAgentSettingInputValue(input, storedSettings[input.dataset.agentSetting]);
  });

  setAgentConnectionDisplay(
    "disconnected",
    "Use Test Connection to verify the current Agent settings.",
    {
      configSourceText: getAgentConfigSourceText(settingsPayload),
    },
  );
}

function renderMarketplaceSettings(settingsPayload) {
  const configured = Boolean(settingsPayload?.curseForge?.configured || settingsPayload?.stored?.hasCurseForgeApiKey);
  const diagnostics = settingsPayload?.curseForge?.diagnostics || {};
  const degraded = settingsPayload?.recovery?.degraded === true || diagnostics.degraded === true;
  const mode = diagnostics.mode || (configured ? "owner-local" : "unavailable");
  const fingerprint = diagnostics.keyFingerprint ? ` fingerprint ${diagnostics.keyFingerprint}` : "";

  if (marketplaceConfigInput) {
    marketplaceConfigInput.value = "";
    marketplaceConfigInput.disabled = degraded;
    marketplaceConfigInput.placeholder = configured ? "Temporary owner key saved - enter a new key to replace" : "Temporary owner/private-alpha key";
  }

  if (marketplaceConfigPill) {
    marketplaceConfigPill.textContent = degraded ? "Degraded" : configured ? "Configured" : "Unavailable";
    marketplaceConfigPill.classList.toggle("is-connected", configured);
    marketplaceConfigPill.classList.toggle("is-disconnected", !configured);
  }

  if (marketplaceConfigMessage) {
    marketplaceConfigMessage.textContent = degraded
      ? "Marketplace provider settings could not be restored. Marketplace providers that require saved credentials are temporarily disabled."
      : configured
      ? `CurseForge configuration mode: ${mode}.${fingerprint ? ` Key${fingerprint}.` : ""}`
      : "CurseForge is unavailable until a hosted proxy, Agent configuration, or temporary owner/private-alpha key is configured.";
  }

  if (marketplaceConfigSource) {
    marketplaceConfigSource.textContent = degraded
      ? "Saved provider credentials were preserved. Unlock AnxOS or reset Marketplace provider settings to use this provider again."
      : `Source: ${diagnostics.keySource || mode}. Proxy: ${diagnostics.hostedProxyConfigured ? "configured" : "not configured"}. Agent proxy: ${diagnostics.agentProxyEligible ? "eligible" : "not active"}.`;
  }
  renderCurseForgeDiagnostics(diagnostics);
}

function setCurseForgeDiagnosticField(name, value) {
  curseForgeDiagnosticFields.forEach((field) => {
    if (field.dataset.curseforgeDiagnostic === name) {
      field.textContent = value || "Unknown";
    }
  });
}

function renderCurseForgeDiagnostics(diagnostics = {}) {
  setCurseForgeDiagnosticField("agent", diagnostics.selectedAgentName || diagnostics.agentNodeLabel || diagnostics.selectedAgentId || "Unknown");
  setCurseForgeDiagnosticField("reachable", diagnostics.agentReachable === true ? "Yes" : diagnostics.agentReachable === false ? "No" : "Unknown");
  setCurseForgeDiagnosticField("configured", diagnostics.configured === true ? "Yes" : diagnostics.configured === false ? "No" : "Unknown");
  setCurseForgeDiagnosticField("source", diagnostics.source || diagnostics.keySource || diagnostics.mode || "Unknown");
  setCurseForgeDiagnosticField("fingerprint", diagnostics.fingerprint || diagnostics.keyFingerprint || "Unavailable");
  setCurseForgeDiagnosticField("api", diagnostics.apiConnectivity || diagnostics.browsing || "Not tested");
  setCurseForgeDiagnosticField("cdn", diagnostics.cdnAuthenticationConnectivity || diagnostics.fileDownloadAuthentication || "Not tested");
  setCurseForgeDiagnosticField("lastTest", diagnostics.lastTestTime || diagnostics.checkedAt || "Never");
  setCurseForgeDiagnosticField("error", diagnostics.errorCode || "None");
}

function setSettingsStatus(message, tone = "neutral") {
  document.querySelectorAll("[data-settings-status]").forEach((target) => {
    target.textContent = message;
    target.dataset.tone = tone;
  });
}

async function saveSettingsPatch(patch = {}, { statusMessage = null } = {}) {
  const settings = { ...DEFAULT_SETTINGS, ...getCurrentSettings(), ...(patch || {}) };
  writeStoredSettings(settings);
  applySettings(settings);
  settingsInputs.forEach((input) => {
    if (Object.prototype.hasOwnProperty.call(patch, input.dataset.setting)) {
      setSettingInputValue(input, settings[input.dataset.setting]);
    }
  });
  const desktopApiState = getDesktopApiState();
  if (desktopApiState.hasPreferences) {
    try {
      const payload = await desktopApiState.api.settings.savePreferences(Object.fromEntries(
        Object.entries(patch || {}).filter(([key]) => isSettingKeyAuthorized(key)),
      ));
      const saved = { ...DEFAULT_SETTINGS, ...(payload?.settings || settings) };
      writeStoredSettings(saved);
      applySettings(saved);
      settingsInputs.forEach((input) => {
        if (Object.prototype.hasOwnProperty.call(patch, input.dataset.setting)) {
          setSettingInputValue(input, saved[input.dataset.setting]);
        }
      });
    } catch (error) {
      setSettingsStatus(normalizeIpcErrorMessage(error, "Settings could not be saved."), "error");
      throw error;
    }
  }
  if (statusMessage) setSettingsStatus(statusMessage);
  return settings;
}

function shouldShowOnboardingWelcome(settings = getCurrentSettings()) {
  return setupDetectionResolved &&
    !shouldBlockOnboardingForAccount() &&
    settings["onboarding.welcomeGuidance"] !== false &&
    settings["onboarding.completed"] !== true &&
    settings["onboarding.skipped"] !== true;
}

function getExistingSetupEvidence() {
  const configuredNodes = (nodesState.nodes || []).filter((node) => (
    node && node.kind !== "application-host" && node.id !== "application-host"
  ));
  const savedAccount = accountState.account || {};
  return {
    localOwnerConfigured: securityState.setupRequired === false,
    localSetupComplete: isLocalSetupComplete(),
    rememberedLocalSession: securityState.persistentSession === true ||
      Number(securityState.persistentSessionCount || 0) > 0,
    savedAccountSession: accountState.authenticated === true ||
      accountState.canRefresh === true ||
      Boolean(savedAccount.id || savedAccount.email),
    configuredNodeCount: configuredNodes.length,
  };
}

function shouldRepairOnboardingForExistingSetup(settings = getCurrentSettings(), evidence = getExistingSetupEvidence()) {
  if (!setupDetectionResolved) return false;
  if (settings["onboarding.completed"] === true || settings["onboarding.skipped"] === true) return false;
  return evidence.localOwnerConfigured ||
    evidence.localSetupComplete ||
    evidence.rememberedLocalSession ||
    evidence.savedAccountSession ||
    evidence.configuredNodeCount > 0;
}

async function reconcileOnboardingForExistingSetup(settings = getCurrentSettings()) {
  const evidence = getExistingSetupEvidence();
  if (!shouldRepairOnboardingForExistingSetup(settings, evidence)) return settings;
  const patch = {
    "onboarding.started": true,
    "onboarding.completed": true,
    "onboarding.skipped": false,
    "onboarding.currentStep": "complete",
    "onboarding.version": DEFAULT_SETTINGS["onboarding.version"],
  };
  console.info("[Onboarding] Repaired stale first-launch state for an existing setup.", {
    localOwnerConfigured: evidence.localOwnerConfigured,
    localSetupComplete: evidence.localSetupComplete,
    rememberedLocalSession: evidence.rememberedLocalSession,
    savedAccountSession: evidence.savedAccountSession,
    configuredNodeCount: evidence.configuredNodeCount,
  });
  try {
    return await saveSettingsPatch(patch);
  } catch (error) {
    console.warn("[Onboarding] Could not persist upgraded setup state; using the repaired state for this launch.", {
      code: error?.code || "ONBOARDING_REPAIR_FAILED",
    });
    return { ...settings, ...patch };
  }
}

function setOnboardingWelcomeVisible(visible) {
  if (!onboardingWelcomeModal) return;
  if (visible) {
    onboardingWelcomeModal.hidden = false;
    onboardingWelcomeCleanup = activateModal(onboardingWelcomeModal, {
      initialFocus: () => onboardingWelcomeModal.querySelector('[data-onboarding-action="start"]'),
    });
  } else {
    onboardingWelcomeCleanup?.();
    onboardingWelcomeCleanup = null;
    onboardingWelcomeModal.hidden = true;
  }
}

function maybeOpenOnboardingWelcome(settings = getCurrentSettings()) {
  if (!shouldShowOnboardingWelcome(settings)) return;
  const generation = ++onboardingOpenGeneration;
  window.setTimeout(() => {
    if (generation !== onboardingOpenGeneration || !shouldShowOnboardingWelcome(settings)) return;
    if (settings["onboarding.started"] === true) {
      setOnboardingWizardVisible(true);
    } else {
      setOnboardingWelcomeVisible(true);
    }
  }, 350);
}

function isAccountRestorationPending() {
  return !accountRestorationResolved ||
    accountState.state === "restoring" ||
    accountState.restorationState === "restoring";
}

function shouldRequireAccountBeforeOnboarding() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasAccount) return false;
  if (isAccountRestorationPending()) return true;
  if (accountState.authenticated === true) return false;
  if (accountState.configured === false) return false;
  return true;
}

function shouldBlockOnboardingForAccount() {
  if (shouldRequireAccountBeforeOnboarding()) return true;
  return accountState.state === "temporarily-offline" ||
    accountState.restorationState === "temporarily-offline";
}

function getOnboardingStepIndex(stepId = getCurrentSettings()["onboarding.currentStep"]) {
  const index = ONBOARDING_STEPS.findIndex((step) => step.id === stepId);
  return index >= 0 ? index : 0;
}

function appendOnboardingPageAction(container, label, page, beforeOpen = null) {
  const button = createTextElement("button", label, "inline-action");
  button.type = "button";
  button.addEventListener("click", () => {
    beforeOpen?.();
    setOnboardingWizardVisible(false);
    showPage(page);
  });
  container.append(button);
  return button;
}

function renderOnboardingSignInStep(container) {
  const signedIn = accountState.authenticated === true;
  const pending = Boolean(accountState.pending);
  container.append(createTextElement("p", "Your AnxOS account is separate from Local Owner. Account sign-in enables cloud and remote features; local server management can be set up without it."));
  container.append(onboardingStatus("AnxOS account", signedIn ? "Completed" : pending ? "Waiting for sign-in" : "Optional", signedIn ? "ok" : pending ? "warning" : "planned", signedIn ? "This device has an active account session." : "You can skip this optional step and sign in later from Security."));
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  if (!signedIn) {
    const signIn = createTextElement("button", pending ? "Resume Sign In" : "Sign In", "primary-button");
    signIn.type = "button";
    signIn.disabled = accountStartInFlight;
    signIn.addEventListener("click", () => startAnxOsAccountLogin().finally(renderOnboardingWizard));
    actions.append(signIn);
  }
  appendOnboardingPageAction(actions, "Open Account Settings", "security");
  container.append(actions);
}

function renderOnboardingLocalOwnerStep(container) {
  const available = getDesktopApiState().hasSecurity;
  const ready = securityState.setupRequired === false;
  const unlocked = securityState.authenticated === true;
  container.append(createTextElement("p", "Local Owner protects privileged settings on this computer. It is stored locally and is not your online AnxOS account."));
  container.append(onboardingStatus("Local Owner", !available ? "Unavailable" : unlocked ? "Completed" : ready ? "Locked" : "Setup required", unlocked ? "ok" : available ? "warning" : "critical", unlocked ? "Privileged local settings are unlocked." : ready ? "Unlock Local Owner to continue privileged setup." : "Create Local Owner to protect privileged actions."));
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  appendOnboardingPageAction(actions, securityState.setupRequired ? "Create Local Owner" : "Unlock Local Owner", "security", showRemoteControlSetup);
  container.append(actions);
}

function renderOnboardingConnectAgentStep(container) {
  container.append(createTextElement("p", "The Local Agent is the trusted service that installs servers, manages files, creates backups, and checks system health. The desktop interface never replaces its authorization checks."));
  renderOnboardingInstallLocalAgentStep(container);
  renderOnboardingPairSecurelyStep(container);
}

function renderOnboardingPrepareNodeStep(container) {
  renderOnboardingPrepareThisPcStep(container);
  renderOnboardingDependenciesStep(container);
  const actions = container.querySelector(".onboarding-inline-actions:last-of-type") || document.createElement("div");
  if (!actions.parentNode) {
    actions.className = "onboarding-inline-actions";
    container.append(actions);
  }
  appendOnboardingPageAction(actions, "Open Prepare Node", "agent-control");
}

function renderOnboardingFirstServerStep(container) {
  const instances = Array.isArray(instancesState?.instances) ? instancesState.instances : [];
  const ready = instances.length > 0;
  container.append(createTextElement("p", "Marketplace uses supported providers and the Local Agent to check dependencies and install into managed storage. You will review the template before anything is installed."));
  container.append(onboardingStatus("First server", ready ? "Completed" : "Current", ready ? "ok" : "warning", ready ? `${instances.length} managed ${instances.length === 1 ? "server is" : "servers are"} available.` : "Choose a Marketplace template to create your first server."));
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  const create = appendOnboardingPageAction(actions, ready ? "Open Instances" : "Create First Server", ready ? "instances" : "marketplace");
  if (!ready) create.addEventListener("click", () => window.setTimeout(openFirstServerGuide, 0));
  container.append(actions);
}

function renderOnboardingPublicAccessStep(container) {
  container.append(createTextElement("p", "Public Access is optional. Playit is the easiest public option, Tailscale is private to your tailnet, and Cloudflare is shown only for the HTTP capabilities currently supported."));
  container.append(onboardingStatus("Public Access", "Optional", "planned", "Keep services on LAN or localhost unless outside access is needed. Avoid exposing unnecessary ports."));
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  appendOnboardingPageAction(actions, "Configure Public Access", "playit");
  container.append(actions);
}

function setOnboardingWizardVisible(visible) {
  if (!onboardingWizardModal) return;
  if (visible) {
    onboardingWizardModal.hidden = false;
    renderOnboardingWizard();
    onboardingWizardCleanup = activateModal(onboardingWizardModal, {
      initialFocus: () => onboardingWizardModal.querySelector('[data-onboarding-wizard-action="continue"], [data-onboarding-wizard-action="finish"]'),
    });
  } else {
    onboardingWizardCleanup?.();
    onboardingWizardCleanup = null;
    onboardingWizardModal.hidden = true;
  }
}

function onboardingSelectionSet() {
  return new Set(String(getCurrentSettings()["onboarding.usageSelections"] || "").split(",").map((entry) => entry.trim()).filter(Boolean));
}

function getOnboardingSetupType() {
  const value = String(getCurrentSettings()["onboarding.setupType"] || "this-pc");
  return ONBOARDING_SETUP_TYPES.some(([id]) => id === value) ? value : "this-pc";
}

function onboardingUsesLocalAgent() {
  return getOnboardingSetupType() !== "remote";
}

function onboardingUsesRemoteAgent() {
  return getOnboardingSetupType() !== "this-pc";
}

function getLocalAgentOnboardingStatus() {
  const target = getAgentControlOverviewTarget(agentControlState);
  const runtime = target ? getAgentRuntime(target) : null;
  const service = target?.service || {};
  const pairing = target?.pairing || {};
  const running = Boolean(runtime?.reachable || runtime?.connected || isAgentTargetRunning(target));
  const serviceInstalled = service.installed === true || service.registrationStatus === "valid";
  return {
    target,
    runtime,
    pairing,
    desktopReady: Boolean(runtimeInfoState),
    installed: Boolean(target?.runtimeBundle?.exists || service.installed || running),
    serviceInstalled,
    running,
    authenticated: pairing.configured === true && pairing.localOnly === true,
    versionCompatible: !String(target?.state || "").toLowerCase().includes("version"),
    storageWritable: Array.isArray(target?.config?.storageRoots) && target.config.storageRoots.length > 0,
  };
}

function onboardingStatus(label, value, tone = "planned", detail = "") {
  const row = document.createElement("article");
  row.className = "onboarding-status-card";
  const header = document.createElement("div");
  header.append(createTextElement("strong", label), createTextElement("span", value, `status-pill status-pill--${tone}`));
  row.append(header);
  if (detail) row.append(createTextElement("p", detail));
  return row;
}

function appendOnboardingTechnicalDetails(container, title, details = []) {
  const cleanDetails = details.filter(Boolean);
  if (!cleanDetails.length) return;
  const disclosure = document.createElement("details");
  disclosure.className = "onboarding-technical-details";
  disclosure.append(createTextElement("summary", title));
  const list = document.createElement("dl");
  cleanDetails.forEach(([label, value]) => {
    const row = document.createElement("div");
    row.append(createTextElement("dt", label), createTextElement("dd", value || "Unavailable"));
    list.append(row);
  });
  disclosure.append(list);
  container.append(disclosure);
}

function renderOnboardingSetupTypeStep(container) {
  container.append(createTextElement("p", "Most users should start with this PC. Remote servers remain optional and can be added later."));
  const current = getOnboardingSetupType();
  const grid = document.createElement("div");
  grid.className = "onboarding-choice-grid";
  ONBOARDING_SETUP_TYPES.forEach(([id, labelText, description]) => {
    const label = document.createElement("label");
    label.className = "settings-check settings-check--toggle onboarding-choice";
    const input = document.createElement("input");
    input.type = "radio";
    input.name = "onboarding-setup-type";
    input.checked = current === id;
    input.addEventListener("change", () => {
      if (!input.checked) return;
      updateOnboardingState({ "onboarding.setupType": id }).catch((error) => {
        showToast(normalizeIpcErrorMessage(error, "Setup type could not be saved."), "error");
      }).finally(() => renderOnboardingWizard());
    });
    const text = document.createElement("span");
    text.append(createTextElement("strong", labelText), createTextElement("small", description));
    label.append(input, text);
    grid.append(label);
  });
  container.append(grid);
}

function renderOnboardingPrepareThisPcStep(container) {
  const info = runtimeInfoState || {};
  const hasRuntime = Boolean(runtimeInfoState);
  const agent = getLocalAgentOnboardingStatus();
  const platform = info.platform || navigator.platform || "Unable to confirm";
  const status = hasRuntime ? "Ready" : "Unable to confirm";
  const message = hasRuntime
    ? "This computer is ready to use with AnxOS."
    : "Local management information is not loaded yet. Retry the check or open Diagnostics.";
  const grid = document.createElement("div");
  grid.className = "onboarding-status-grid";
  grid.append(
    onboardingStatus("Desktop application", status, hasRuntime ? "ok" : "planned", message),
    onboardingStatus("Local Agent runtime", agent.installed ? "Ready" : "Ready to install", agent.installed ? "ok" : "planned", onboardingUsesLocalAgent() ? "The bundled runtime is managed by AnxOS." : "Skipped for remote-only setup."),
    onboardingStatus("Windows service", agent.serviceInstalled ? "Registered" : onboardingUsesLocalAgent() ? "Not installed yet" : "Skipped", agent.serviceInstalled ? "ok" : "planned"),
    onboardingStatus("Storage paths", agent.storageWritable ? "Writable" : "Will be created", agent.storageWritable ? "ok" : "planned"),
  );
  container.append(grid);
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  const retry = createTextElement("button", "Retry Check", "inline-action");
  retry.type = "button";
  retry.addEventListener("click", async () => { await loadRuntimeInfo(); renderOnboardingWizard(); });
  const diagnostics = createTextElement("button", "View Diagnostics", "inline-action");
  diagnostics.type = "button";
  diagnostics.addEventListener("click", () => { setOnboardingWizardVisible(false); showPage("agent-control"); });
  actions.append(retry, diagnostics);
  container.append(actions);
  appendOnboardingTechnicalDetails(container, "Technical details", [
    ["Operating system", info.operatingSystem || info.os || platform],
    ["Platform", platform],
    ["Hostname", info.hostname],
    ["Application version", info.releaseLabel || info.appVersion || info.version],
    ["Architecture", info.architecture || info.arch],
    ["Setup type", getOnboardingSetupType()],
    ["Local Agent", onboardingUsesLocalAgent() ? "Included in this setup" : "Skipped by setup choice"],
  ]);
}

function getOnboardingAgentSummary() {
  const target = getAgentControlOverviewTarget(agentControlState);
  const agentStatus = target ? getAgentStatusSnapshot(target) : getActiveAgentStatusSnapshot();
  if (!agentControlState) {
    return {
      status: agentStatus.primary || "Unable to check",
      tone: getAgentStatusPillTone(agentStatus),
      message: agentStatus.secondary || "Agent state has not been checked in this session.",
    };
  }
  return {
    status: agentStatus.primary,
    tone: getAgentStatusPillTone(agentStatus),
    message: agentStatus.secondary,
  };
}

function renderOnboardingInstallLocalAgentStep(container) {
  if (!onboardingUsesLocalAgent()) {
    container.append(onboardingStatus("Local Agent", "Skipped", "planned", "You chose remote-only setup. AnxOS will not install the Local Agent on this PC."));
    const actions = document.createElement("div");
    actions.className = "onboarding-inline-actions";
    const remote = createTextElement("button", "Add Remote Server", "primary-button");
    remote.type = "button";
    remote.addEventListener("click", () => { setOnboardingWizardVisible(false); showPage("nodes"); setNodeModalVisible(true); });
    actions.append(remote);
    container.append(actions);
    return;
  }
  container.append(createTextElement("p", "AnxOS Local Agent lets AnxOS manage servers, files, backups, dependencies, and services on this computer."));
  const summary = getOnboardingAgentSummary();
  const agent = getLocalAgentOnboardingStatus();
  const grid = document.createElement("div");
  grid.className = "onboarding-status-grid";
  grid.append(
    onboardingStatus("Local Agent installed", agent.installed ? "Ready" : "Missing", agent.installed ? "ok" : "warning", summary.message),
    onboardingStatus("Windows service", agent.serviceInstalled ? "Registered" : "Not installed", agent.serviceInstalled ? "ok" : "planned", "The service lets the Agent start with Windows."),
    onboardingStatus("Agent running", agent.running ? "Running" : "Stopped", agent.running ? "ok" : "planned"),
  );
  container.append(grid);
  const progress = document.createElement("div");
  progress.className = "onboarding-status-grid";
  [
    "Preparing your computer...",
    "Installing the Local Agent...",
    "Starting the Agent...",
    "Creating a secure connection...",
    "Checking system dependencies...",
    "Finalizing setup...",
    "Your PC is ready.",
  ].forEach((message) => progress.append(onboardingStatus(message, agent.running ? "Done" : "Pending", agent.running ? "ok" : "planned")));
  container.append(progress);
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  [
    ["Retry Check", async () => { await refreshAgentControl({ includeConfig: true }); renderOnboardingWizard(); }],
    [agent.installed ? "Repair Local Agent" : "Install Local Agent", async () => { await runAgentControlAction(agent.installed ? "repairAgent" : "installLocalAgent"); await refreshAgentControl({ includeConfig: true }); renderOnboardingWizard(); }],
    ["Open Agent Control", () => { setOnboardingWizardVisible(false); showPage("agent-control"); }],
  ].forEach(([labelText, handler]) => {
    const button = createTextElement("button", labelText, /Install|Repair/.test(labelText) ? "primary-button" : "inline-action");
    button.type = "button";
    button.addEventListener("click", handler);
    actions.append(button);
  });
  container.append(actions);
}

function renderOnboardingPairSecurelyStep(container) {
  if (!onboardingUsesLocalAgent()) {
    container.append(onboardingStatus("Local pairing", "Skipped", "planned", "Remote Agent pairing stays available from Agent Connection settings."));
    return;
  }
  const agent = getLocalAgentOnboardingStatus();
  container.append(onboardingStatus("Secure local connection", agent.authenticated ? "Paired" : "Needs pairing", agent.authenticated ? "ok" : "warning", agent.authenticated ? "Credentials are stored locally and only the fingerprint is shown." : "AnxOS can repair local credentials automatically without token copying."));
  appendOnboardingTechnicalDetails(container, "Pairing details", [
    ["Authentication", agent.authenticated ? "Successful" : "Not paired"],
    ["Token fingerprint", agent.pairing?.fingerprint || "Unavailable"],
    ["Local only", agent.pairing?.localOnly ? "Yes" : "Not confirmed"],
  ]);
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  const pair = createTextElement("button", agent.authenticated ? "Repair Pairing" : "Pair Securely", "primary-button");
  pair.type = "button";
  pair.addEventListener("click", async () => {
    const api = getDesktopApiState().api?.agentControl;
    if (!api?.pairLocalAgent) throw new Error("Local Agent pairing is unavailable in this build.");
    await api.pairLocalAgent({ rotate: false, reason: "onboarding" });
    await refreshAgentControl({ includeConfig: true });
    renderOnboardingWizard();
  });
  const rotate = createTextElement("button", "Rotate Credentials", "inline-action");
  rotate.type = "button";
  rotate.addEventListener("click", async () => {
    const api = getDesktopApiState().api?.agentControl;
    if (!api?.pairLocalAgent) throw new Error("Local Agent pairing is unavailable in this build.");
    await api.pairLocalAgent({ rotate: true, reason: "onboarding-rotation" });
    await api.restart?.();
    await refreshAgentControl({ includeConfig: true });
    renderOnboardingWizard();
  });
  actions.append(pair, rotate);
  container.append(actions);
}

function getDependencyFriendlyState(dependency = {}) {
  const state = String(dependency.state || "").toLowerCase();
  if (dependency.updateAvailable === true || state === "update-required" || state === "outdated") return "Update available";
  if (dependency.installed === true || state === "installed" || state === "ready") return "Ready";
  if (state === "installed-unavailable" || state === "verification-failed") return "Installed but unavailable";
  if (state === "detection-failed") return "Detection failed";
  if (state === "missing" || dependency.installed === false) return "Not installed";
  if (state === "unsupported" || dependency.supported === false) return "Not supported";
  if (state.includes("setup") || state.includes("auth")) return "Setup required";
  return "Unable to check";
}

function renderOnboardingDependenciesStep(container) {
  const result = latestDependencyResult;
  const dependencies = Array.isArray(result?.dependencies) ? result.dependencies : [];
  const intro = result
    ? "Detected tools are grouped by the dependency registry used by Marketplace and Agent Control."
    : "No dependency check has completed yet. Run a check to detect tools on the selected system.";
  container.append(createTextElement("p", intro));
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  const check = createTextElement("button", "Scan Dependencies", "primary-button");
  check.type = "button";
  check.addEventListener("click", async () => { await runDependencyAction("check"); renderOnboardingWizard(); });
  const install = createTextElement("button", "Install Missing", "inline-action");
  install.type = "button";
  install.addEventListener("click", async () => { await runDependencyAction("install"); renderOnboardingWizard(); });
  actions.append(check, install);
  container.append(actions);
  const grid = document.createElement("div");
  grid.className = "onboarding-status-grid";
  if (!dependencies.length) {
    grid.append(onboardingStatus("Tools", "Unable to check", "planned", "Run a dependency check to see installed versions and setup requirements."));
  } else {
    dependencies.slice(0, 14).forEach((dependency) => {
      const state = getDependencyFriendlyState(dependency);
      const tone = state === "Ready" ? "ok" : state === "Not installed" || state === "Setup required" ? "warning" : state === "Not supported" ? "planned" : "manual";
      grid.append(onboardingStatus(dependency.displayName || dependency.id || "Dependency", state, tone, dependency.version ? `Version ${dependency.version}` : dependency.reason || "Version unavailable"));
    });
  }
  container.append(grid);
}

function renderOnboardingStorageStep(container) {
  const agent = getLocalAgentOnboardingStatus();
  const config = agent.target?.config || {};
  const storageRoots = Array.isArray(config.storageRoots) ? config.storageRoots : [];
  const allowedFolders = Array.isArray(config.allowedFolders) ? config.allowedFolders : [];
  container.append(createTextElement("p", onboardingUsesLocalAgent() ? "These managed folders are used for instances, backups, logs, and temporary downloads on this PC." : "Storage on this PC is skipped for remote-only setup."));
  const grid = document.createElement("div");
  grid.className = "onboarding-status-grid";
  grid.append(
    onboardingStatus("Instance storage", storageRoots[0] ? "Configured" : "Will be created", storageRoots[0] ? "ok" : "planned", storageRoots[0] || "Managed by Local Agent installer"),
    onboardingStatus("Backup storage", storageRoots[1] ? "Configured" : "Will be created", storageRoots[1] ? "ok" : "planned", storageRoots[1] || "Managed by Local Agent installer"),
    onboardingStatus("Writable paths", allowedFolders.length ? `${allowedFolders.length} roots` : "Default roots", allowedFolders.length ? "ok" : "planned"),
  );
  container.append(grid);
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  const open = createTextElement("button", "Open Agent Control", "inline-action");
  open.type = "button";
  open.addEventListener("click", () => { setOnboardingWizardVisible(false); showPage("agent-control"); });
  const files = createTextElement("button", "Open Files", "inline-action");
  files.type = "button";
  files.addEventListener("click", () => { setOnboardingWizardVisible(false); showPage("files"); });
  actions.append(open, files);
  container.append(actions);
}

function renderOnboardingRemoteSummary(container) {
  container.append(createTextElement("p", onboardingUsesRemoteAgent() ? "Add a remote Windows or Linux Agent when you are ready." : "Remote servers are optional and can be added later."));
  const remoteNodes = (nodesState.nodes || []).filter((node) => node.kind === "agent");
  const grid = document.createElement("div");
  grid.className = "onboarding-status-grid";
  if (!remoteNodes.length) {
    grid.append(onboardingStatus("Remote systems", "Optional", "planned", "Only this computer is connected right now."));
  } else {
    remoteNodes.forEach((node) => {
      const connected = getNodeVisualState(node) === "online";
      grid.append(onboardingStatus(node.displayName || node.hostname || node.id, connected ? "Connected" : "Unable to confirm", connected ? "ok" : "planned", `${node.platform || node.operatingSystem || "Platform unavailable"} · ${node.agentUrl || node.hostname || "Address unavailable"}`));
    });
  }
  container.append(grid);
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  const add = createTextElement("button", "Add a Remote System", "primary-button");
  add.type = "button";
  add.addEventListener("click", () => { setOnboardingWizardVisible(false); showPage("nodes"); setNodeModalVisible(true); });
  const skip = createTextElement("button", "Skip for Now", "inline-action");
  skip.type = "button";
  skip.addEventListener("click", () => goToOnboardingStep("finish"));
  actions.append(add, skip);
  container.append(actions);
}

function renderOnboardingFinishStep(container) {
  const agent = getOnboardingAgentSummary();
  const dependencySummary = summarizeDependencyStatus(latestDependencyResult);
  const remoteCount = (nodesState.nodes || []).filter((node) => node.kind === "agent").length;
  const setupType = getOnboardingSetupType();
  const grid = document.createElement("div");
  grid.className = "onboarding-status-grid";
  grid.append(
    onboardingStatus("Local computer", runtimeInfoState ? "Ready" : "Unable to confirm", runtimeInfoState ? "ok" : "planned"),
    onboardingStatus("Local Agent", onboardingUsesLocalAgent() ? agent.status : "Skipped", onboardingUsesLocalAgent() ? agent.tone : "planned"),
    onboardingStatus("Dependencies", latestDependencyResult ? dependencySummary.label : "Optional setup remaining", latestDependencyResult && dependencySummary.state === "ready" ? "ok" : "manual"),
    onboardingStatus("Connected systems", remoteCount ? `${remoteCount} connected` : "Optional setup remaining", remoteCount ? "ok" : "planned"),
    onboardingStatus("Setup type", setupType === "this-pc" ? "Use This PC" : setupType === "remote" ? "Connect a Remote Server" : "Configure Both", "ok"),
    onboardingStatus("Docker", dockerWorkspaceState?.ready ? "Ready" : "Optional setup remaining", dockerWorkspaceState?.ready ? "ok" : "planned"),
    onboardingStatus("Public access providers", "Optional setup remaining", "planned"),
  );
  container.append(grid);
  if (onboardingUsesRemoteAgent()) renderOnboardingRemoteSummary(container);
  const actions = document.createElement("div");
  actions.className = "onboarding-inline-actions";
  const dashboard = createTextElement("button", "Open Dashboard", "primary-button");
  dashboard.type = "button";
  dashboard.addEventListener("click", async () => {
    await handleOnboardingWizardFinish();
    showPage("dashboard");
  });
  const summary = createTextElement("button", "View Setup Summary", "inline-action");
  summary.type = "button";
  summary.addEventListener("click", () => showToast("Setup summary is shown in this step."));
  actions.append(dashboard, summary);
  container.append(actions);
}

function renderOnboardingWizard() {
  if (!onboardingWizardBody) return;
  const index = getOnboardingStepIndex();
  const step = ONBOARDING_STEPS[index] || ONBOARDING_STEPS[0];
  if (onboardingWizardTitle) onboardingWizardTitle.textContent = step.title;
  if (onboardingWizardDescription) onboardingWizardDescription.textContent = step.description;
  if (onboardingWizardProgress) onboardingWizardProgress.textContent = `Step ${index + 1} of ${ONBOARDING_STEPS.length}`;
  if (onboardingWizardTrack) {
    onboardingWizardTrack.replaceChildren();
    ONBOARDING_STEPS.forEach((candidate, candidateIndex) => {
      const marker = document.createElement("span");
      const optional = candidate.id === "sign-in" || candidate.id === "public-access";
      const blocked = candidate.id === "local-owner" && !getDesktopApiState().hasSecurity;
      const visualState = candidateIndex === index ? "current" : candidateIndex < index ? "completed" : blocked ? "blocked" : optional ? "optional" : "upcoming";
      marker.className = visualState === "current" ? "is-active" : visualState === "completed" ? "is-complete" : visualState === "blocked" ? "is-blocked" : visualState === "optional" ? "is-optional" : "";
      marker.dataset.state = visualState;
      marker.title = `${candidate.title} · ${visualState}`;
      marker.setAttribute("aria-label", `${candidate.title}: ${visualState}`);
      onboardingWizardTrack.append(marker);
    });
  }
  onboardingWizardBody.replaceChildren();
  if (step.id === "sign-in") renderOnboardingSignInStep(onboardingWizardBody);
  else if (step.id === "local-owner") renderOnboardingLocalOwnerStep(onboardingWizardBody);
  else if (step.id === "connect-agent") renderOnboardingConnectAgentStep(onboardingWizardBody);
  else if (step.id === "prepare-node") renderOnboardingPrepareNodeStep(onboardingWizardBody);
  else if (step.id === "first-server") renderOnboardingFirstServerStep(onboardingWizardBody);
  else if (step.id === "public-access") renderOnboardingPublicAccessStep(onboardingWizardBody);
  else renderOnboardingFinishStep(onboardingWizardBody);
  onboardingWizardButtons.forEach((button) => {
    const action = button.dataset.onboardingWizardAction;
    button.hidden = (action === "finish") !== (step.id === "finish") || (action === "continue" && step.id === "finish");
    if (action === "back") button.disabled = index === 0;
  });
}

async function goToOnboardingStep(stepId) {
  await updateOnboardingState({
    "onboarding.started": true,
    "onboarding.completed": false,
    "onboarding.skipped": false,
    "onboarding.currentStep": stepId,
  });
  renderOnboardingWizard();
}

async function handleOnboardingWizardFinish() {
  await updateOnboardingState({
    "onboarding.started": true,
    "onboarding.completed": true,
    "onboarding.skipped": false,
    "onboarding.currentStep": "complete",
  }, { statusMessage: "Setup guide completed." });
  setOnboardingWizardVisible(false);
  showToast("AnxOS setup guide completed.");
}

async function updateOnboardingState(patch = {}, options = {}) {
  const nextPatch = {
    "onboarding.version": DEFAULT_SETTINGS["onboarding.version"],
    ...patch,
  };
  return saveSettingsPatch(nextPatch, options);
}

async function handleOnboardingAction(action) {
  if (action === "start") {
    console.info("[Onboarding] Starting setup from welcome screen.");
    try {
      await updateOnboardingState({
        "onboarding.started": true,
        "onboarding.completed": false,
        "onboarding.skipped": false,
        "onboarding.currentStep": "sign-in",
        "onboarding.setupType": "this-pc",
        "onboarding.welcomeGuidance": true,
        "onboarding.contextualTips": true,
      }, { statusMessage: "Setup guide started." });
    } catch (error) {
      console.warn("[Onboarding] Could not persist setup start; continuing in memory.", normalizeIpcErrorMessage(error, "Setup settings could not be saved."));
      showToast("Setup started, but preferences could not be saved. You can continue and retry later.", "warning");
    }
    setOnboardingWelcomeVisible(false);
    setOnboardingWizardVisible(true);
    console.info("[Onboarding] Setup wizard opened.");
    if (getDesktopApiState().hasAccount) {
      console.info("[Onboarding] Starting account authentication.");
      await startAnxOsAccountLogin();
    }
  } else if (action === "skip") {
    await updateOnboardingState({
      "onboarding.started": false,
      "onboarding.completed": false,
      "onboarding.skipped": true,
      "onboarding.currentStep": "sign-in",
      "onboarding.setupType": "this-pc",
      "onboarding.welcomeGuidance": true,
      "onboarding.contextualTips": true,
    }, { statusMessage: "Setup guide skipped." });
    setOnboardingWelcomeVisible(false);
    showToast("Setup guide skipped. Contextual guidance stays enabled.");
  } else if (action === "restart" || action === "reset") {
    await updateOnboardingState({
      "onboarding.started": false,
      "onboarding.completed": false,
      "onboarding.skipped": false,
      "onboarding.currentStep": "sign-in",
      "onboarding.setupType": "this-pc",
      "onboarding.welcomeGuidance": true,
      "onboarding.contextualTips": true,
    }, { statusMessage: action === "reset" ? "Onboarding state reset." : "Setup guide restarted." });
    setOnboardingWizardVisible(false);
    maybeOpenOnboardingWelcome(getCurrentSettings());
    showToast(action === "reset" ? "Onboarding state reset." : "Setup guide restarted.");
  }
}

function canUseSettingsCapability(capability) {
  if (!capability) return true;
  return settingsPermissionState?.capabilities?.[capability] === true;
}

const AGENT_CONTROL_SECTION_ALIASES = {};

let activeAgentControlSection = (() => {
  try { return window.sessionStorage.getItem("anxos-agent-control-section") || "status"; } catch { return "status"; }
})();

function normalizeAgentControlSection(section = "status") {
  const requested = AGENT_CONTROL_SECTION_ALIASES[section] || section || "status";
  return Array.from(agentControlSections).some((panel) => panel.dataset.agentControlSection === requested) ? requested : "status";
}

function setActiveAgentControlSection(section = activeAgentControlSection || "status") {
  const requested = section || "status";
  const normalized = normalizeAgentControlSection(requested);
  activeAgentControlSection = requested;
  try { window.sessionStorage.setItem("anxos-agent-control-section", requested); } catch {}
  agentControlSections.forEach((panel) => {
    const compatibilityHidden = panel.matches("[data-agent-compatibility-card]")
      && panel.dataset.compatibilityVisible !== "true";
    panel.hidden = panel.dataset.agentControlSection !== normalized || compatibilityHidden;
  });
  agentControlSectionButtons.forEach((button) => {
    const target = button.dataset.agentControlSectionTarget || "status";
    const active = target === requested || (target !== normalized && AGENT_CONTROL_SECTION_ALIASES[target] === normalized && requested === target);
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-current", active ? "page" : "false");
  });
}

const SECURITY_SECTION_ALIASES = {
  revocations: "sessions",
};

let activeSecuritySection = (() => {
  try { return window.sessionStorage.getItem("anxos-security-section") || "status"; } catch { return "status"; }
})();

function normalizeSecuritySection(section = "status") {
  const requested = SECURITY_SECTION_ALIASES[section] || section || "status";
  return Array.from(securitySections).some((panel) => panel.dataset.securitySection === requested) ? requested : "status";
}

function setActiveSecuritySection(section = activeSecuritySection || "status") {
  const requested = section || "status";
  const normalized = normalizeSecuritySection(requested);
  activeSecuritySection = requested;
  try { window.sessionStorage.setItem("anxos-security-section", requested); } catch {}
  securitySections.forEach((panel) => {
    panel.hidden = panel.dataset.securitySection !== normalized;
  });
  securitySectionButtons.forEach((button) => {
    const target = button.dataset.securitySectionTarget || "status";
    const active = target === requested || (target !== normalized && SECURITY_SECTION_ALIASES[target] === normalized && requested === target);
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-current", active ? "page" : "false");
  });
}

function isSettingKeyAuthorized(key) {
  const ownerOnly = settingsPermissionState?.settings?.ownerOnly || [];
  return !ownerOnly.includes(key) || settingsPermissionState?.owner === true;
}

function isSettingsSectionAuthorized(section) {
  if (!section) return false;
  return canUseSettingsCapability(section.dataset.settingsCapability || "");
}

function categoryHasAuthorizedSettingsSection(category) {
  return Array.from(settingsCategorySections).some((section) => (
    section.dataset.settingsCategory === category && isSettingsSectionAuthorized(section)
  ));
}

function normalizeSettingsCategory(category = "general") {
  const requested = category || "general";
  if (categoryHasAuthorizedSettingsSection(requested)) return requested;
  return categoryHasAuthorizedSettingsSection("general") ? "general" : requested;
}

function clearRestrictedSettingsState() {
  marketplaceConfigInput && (marketplaceConfigInput.value = "");
  latestAgentSettingsPayload = null;
  developerUpdateState = null;
  renderDevelopmentBadge(null);
  setDevUpdateModalVisible(false);
  settingsSearchResults?.replaceChildren();
}

function readRequestedSettingsCategoryFromLocation() {
  try {
    const params = new URLSearchParams(window.location.search || "");
    const queryCategory = params.get("settingsCategory") || params.get("settings");
    if (queryCategory) return queryCategory;
    const hash = String(window.location.hash || "").replace(/^#/, "");
    const match = hash.match(/^settings(?:[:=/])([^&?/]+)/i);
    return match ? decodeURIComponent(match[1]) : null;
  } catch {
    return null;
  }
}

function applySettingsPermissions() {
  const ownerNow = settingsPermissionState?.owner === true;
  if (previousSettingsOwnerState === true && ownerNow === false) {
    clearRestrictedSettingsState();
  }
  previousSettingsOwnerState = ownerNow;
  settingsCategorySections.forEach((section) => {
    const authorized = isSettingsSectionAuthorized(section);
    section.dataset.settingsPermissionHidden = authorized ? "false" : "true";
    if (!authorized) section.hidden = true;
  });
  document.querySelectorAll("[data-settings-capability]").forEach((element) => {
    if (element.matches("[data-settings-category]")) return;
    const authorized = canUseSettingsCapability(element.dataset.settingsCapability || "");
    element.hidden = !authorized;
  });
  settingsCategoryButtons.forEach((button) => {
    const category = button.dataset.settingsCategoryTarget || "general";
    button.hidden = !categoryHasAuthorizedSettingsSection(category);
  });
  document.querySelectorAll("[data-settings-category-group]").forEach((group) => {
    const visibleButton = Array.from(group.querySelectorAll("[data-settings-category-target]")).some((button) => !button.hidden);
    group.hidden = !visibleButton;
  });
  settingsInputs.forEach((input) => {
    const authorized = isSettingKeyAuthorized(input.dataset.setting);
    input.toggleAttribute("data-settings-permission-denied", !authorized);
    input.disabled = !authorized || input.dataset.settingsInitiallyDisabled === "true";
  });
  if (!categoryHasAuthorizedSettingsSection(activeSettingsCategory)) {
    activeSettingsCategory = "general";
    try { window.sessionStorage.setItem("anxos-settings-category", activeSettingsCategory); } catch {}
  }
  setActiveSettingsCategory(activeSettingsCategory || "general");
  renderSettingsSearch();
}

async function refreshSettingsPermissions() {
  const desktopApiState = getDesktopApiState();
  if (desktopApiState.api?.settings?.getPermissions) {
    try {
      const payload = await desktopApiState.api.settings.getPermissions();
      settingsPermissionState = {
        ...settingsPermissionState,
        ...(payload || {}),
        capabilities: { ...(settingsPermissionState.capabilities || {}), ...(payload?.capabilities || {}) },
      };
    } catch (error) {
      settingsPermissionState = {
        ...settingsPermissionState,
        owner: false,
        capabilities: {},
      };
      console.warn("[Settings] Permission state unavailable.", normalizeIpcErrorMessage(error, "Settings permissions unavailable."));
    }
  } else {
    const owner = isOwnerWorkspaceAuthorized();
    settingsPermissionState = {
      ...settingsPermissionState,
      owner,
      authenticated: Boolean(securityState?.authenticated || securityState?.accountAuthenticated),
      role: securityState?.user?.role || "Guest",
      capabilities: owner ? {
        canManageMarketplaceSettings: true,
        canManageDeveloperSettings: true,
        canManageInternalUpdates: true,
        canManageAdvancedSecurity: true,
        canManageInfrastructure: true,
        canManageAgentConfiguration: true,
        canManageProviderCredentials: true,
        canViewDiagnostics: true,
        canManageAdvancedNetworking: true,
      } : {},
    };
  }
  applySettingsPermissions();
}

function setActiveSettingsCategory(category = "general", highlightSelector = null) {
  activeSettingsCategory = normalizeSettingsCategory(category || "general");
  try { window.sessionStorage.setItem("anxos-settings-category", activeSettingsCategory); } catch {}
  settingsCategoryButtons.forEach((button) => {
    const active = button.dataset.settingsCategoryTarget === activeSettingsCategory;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-current", active ? "page" : "false");
  });
  settingsCategorySections.forEach((section) => {
    section.hidden = section.dataset.settingsCategory !== activeSettingsCategory || !isSettingsSectionAuthorized(section);
  });
  if (highlightSelector) {
    requestAnimationFrame(() => {
      const target = document.querySelector(highlightSelector);
      const targetSection = target?.matches?.("[data-settings-category]")
        ? target
        : target?.closest?.("[data-settings-category]");
      if (!targetSection || targetSection.dataset.settingsCategory !== activeSettingsCategory || !isSettingsSectionAuthorized(targetSection)) {
        return;
      }
      target?.scrollIntoView?.({ block: "center", behavior: "smooth" });
      target?.classList?.add("settings-highlight");
      target?.focus?.();
      window.setTimeout(() => target?.classList?.remove("settings-highlight"), 1400);
    });
  }
}

function getSettingSearchEntries() {
  return Array.from(settingsCategorySections).filter(isSettingsSectionAuthorized).map((section) => {
    const title = section.querySelector("h3")?.textContent || section.dataset.settingsCategory || "Settings";
    const description = section.querySelector(".settings-section__header p")?.textContent || "";
    const keywords = section.dataset.settingsKeywords || "";
    return {
      category: section.dataset.settingsCategory,
      title,
      description,
      haystack: `${title} ${description} ${keywords} ${section.textContent || ""}`.toLowerCase(),
      selector: `[data-settings-category="${section.dataset.settingsCategory}"]`,
    };
  });
}

function renderSettingsSearch() {
  if (!settingsSearchResults || !settingsSearchInput) return;
  const query = settingsSearchInput.value.trim().toLowerCase();
  settingsSearchResults.replaceChildren();
  settingsSearchResults.hidden = !query;
  if (!query) return;
  const matches = getSettingSearchEntries().filter((entry) => entry.haystack.includes(query)).slice(0, 8);
  if (!matches.length) {
    const empty = document.createElement("p");
    empty.textContent = "No matching settings.";
    settingsSearchResults.append(empty);
    return;
  }
  matches.forEach((entry) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = entry.title;
    button.addEventListener("click", () => {
      setActiveSettingsCategory(entry.category, entry.selector);
      settingsSearchResults.hidden = true;
    });
    settingsSearchResults.append(button);
  });
}

async function loadSettings(options = {}) {
  const desktopApiState = getDesktopApiState();
  await refreshSettingsPermissions();
  let settings = readStoredSettings();
  if (desktopApiState.hasPreferences) {
    try {
      const payload = await desktopApiState.api.settings.getPreferences();
      settings = { ...DEFAULT_SETTINGS, ...(payload?.settings || {}) };
      writeStoredSettings(settings);
    } catch (error) {
      setSettingsStatus(normalizeIpcErrorMessage(error, "Settings could not be loaded. Using local fallback."), "error");
    }
  }
  settingsInputs.forEach((input) => {
    setSettingInputValue(input, settings[input.dataset.setting]);
  });

  applySettings(settings);
  syncAccentSwatches();
  const storedCategory = (() => { try { return window.sessionStorage.getItem("anxos-settings-category"); } catch { return null; } })();
  const routeCategory = readRequestedSettingsCategoryFromLocation();
  setActiveSettingsCategory(routeCategory || storedCategory || activeSettingsCategory || "general");
  if (options.openOnboarding !== false) {
    maybeOpenOnboardingWelcome(settings);
  }
  return settings;
}

async function saveSettings() {
  if (settingsSaveInFlight) return;
  const settings = {
    ...DEFAULT_SETTINGS,
  };

  settingsInputs.forEach((input) => {
    if (!isSettingKeyAuthorized(input.dataset.setting)) return;
    settings[input.dataset.setting] = getSettingInputValue(input);
  });

  writeStoredSettings(settings);
  applySettings(settings);
  syncAccentSwatches();
  refreshPlayitStatus();
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasPreferences) {
    setSettingsStatus("Settings saved locally.");
    return;
  }
  settingsSaveInFlight = true;
  setSettingsStatus("Saving settings...");
  try {
    const payload = await desktopApiState.api.settings.savePreferences(Object.fromEntries(
      Object.entries(settings).filter(([key]) => isSettingKeyAuthorized(key)),
    ));
    writeStoredSettings({ ...DEFAULT_SETTINGS, ...(payload?.settings || settings) });
    setSettingsStatus("Settings saved.");
  } catch (error) {
    setSettingsStatus(normalizeIpcErrorMessage(error, "Settings could not be saved."), "error");
  } finally {
    settingsSaveInFlight = false;
  }
}

async function resetSettings(category = null) {
  const label = category ? `${category} settings` : "all settings";
  if (!(await createSecurityConfirmation({
    title: `Reset ${label}?`,
    message: "Saved preferences for this scope will return to their defaults. Accounts, credentials, server files, backups, and instance data are not removed.",
    confirmLabel: "Reset",
  }))) return;
  const desktopApiState = getDesktopApiState();
  let settings = { ...DEFAULT_SETTINGS };
  if (desktopApiState.hasPreferences) {
    try {
      const payload = await desktopApiState.api.settings.resetPreferences(category);
      settings = { ...DEFAULT_SETTINGS, ...(payload?.settings || {}) };
    } catch (error) {
      setSettingsStatus(normalizeIpcErrorMessage(error, "Settings could not be reset."), "error");
      return;
    }
  }
  window.localStorage.removeItem(SETTINGS_STORAGE_KEY);
  writeStoredSettings(settings);

  settingsInputs.forEach((input) => {
    setSettingInputValue(input, settings[input.dataset.setting]);
  });

  applySettings(settings);
  syncAccentSwatches();
  setSettingsStatus(category ? `${category} settings reset.` : "Settings reset.");
  showToast(category ? `${category} settings reset.` : "Settings reset.");
}

async function loadAgentSettings() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasSettings) {
    setAgentActionButtonsDisabled(true);
    setAgentConnectionDisplay(
      "disconnected",
      desktopApiState.hasBridge
        ? "Agent settings are unavailable in this desktop build."
        : "Desktop preload bridge unavailable.",
      { configSourceText: "Saved Agent settings are unavailable." },
    );
    return;
  }

  agentSettingsRequestInFlight = true;
  setAgentActionButtonsDisabled(true);

  try {
    renderAgentSettings(await desktopApiState.api.settings.getAgentConfig());
    await testAgentConnection({ silent: true });
  } catch {
    setAgentConnectionDisplay("disconnected", "Agent settings could not be loaded.", {
      configSourceText: "Saved Agent settings are unavailable.",
    });
  } finally {
    agentSettingsRequestInFlight = false;
    setAgentActionButtonsDisabled(false);
  }
}

async function loadMarketplaceSettings() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasMarketplaceSettings) {
    if (marketplaceConfigSaveButton) {
      marketplaceConfigSaveButton.disabled = true;
    }
    if (marketplaceConfigMessage) {
      marketplaceConfigMessage.textContent = "Marketplace provider settings are unavailable in this build.";
    }
    return;
  }
  if (securityState?.localOwnerAuthenticated !== true) {
    renderMarketplaceSettings({
      recovery: {
        degraded: true,
        message: "Saved provider credentials are locked until Local Owner authentication completes.",
      },
      curseForge: {
        configured: false,
        diagnostics: {
          degraded: true,
          recoveryMessage: "Unlock AnxOS to use saved Marketplace provider credentials.",
          mode: "local-credentials-locked",
        },
      },
    });
    return;
  }

  try {
    renderMarketplaceSettings(await desktopApiState.api.settings.getMarketplaceConfig());
  } catch {
    if (marketplaceConfigMessage) {
      marketplaceConfigMessage.textContent = "Marketplace provider settings could not be loaded.";
    }
  }
}

async function saveAgentConfiguration() {
  if (agentSettingsRequestInFlight) {
    return;
  }

  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasSettings) {
    showToast("Agent settings are unavailable.");
    return;
  }

  agentSettingsRequestInFlight = true;
  setAgentActionButtonsDisabled(true);

  try {
    const response = await desktopApiState.api.settings.saveAgentConfig(getAgentSettingsFormValues());
    renderAgentSettings(response);
    showToast("Agent settings saved.");
    await testAgentConnection({ silent: true });
    await refreshAgentControl({ includeConfig: false });
  } catch {
    showToast("Agent settings could not be saved.");
  } finally {
    agentSettingsRequestInFlight = false;
    setAgentActionButtonsDisabled(false);
  }
}

async function saveMarketplaceConfiguration() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasMarketplaceSettings) {
    showToast("Marketplace settings are unavailable.");
    return;
  }

  const curseForgeApiKey = marketplaceConfigInput?.value || "";
  if (!curseForgeApiKey.trim()) {
    showToast("Paste a CurseForge API key before saving.");
    marketplaceConfigInput?.focus();
    return;
  }

  if (marketplaceConfigSaveButton) {
    marketplaceConfigSaveButton.disabled = true;
  }

  try {
    const response = await desktopApiState.api.settings.saveMarketplaceConfig({ curseForgeApiKey });
    renderMarketplaceSettings(response);
    showToast("CurseForge API key saved.");
  } catch (error) {
    showToast(error?.message || "Marketplace settings could not be saved.");
  } finally {
    if (marketplaceConfigSaveButton) {
      marketplaceConfigSaveButton.disabled = false;
    }
  }
}

async function testCurseForgeConnection() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasMarketplaceSettings || typeof desktopApiState.api.settings.testCurseForgeConnection !== "function") {
    showToast("CurseForge diagnostics are unavailable.");
    return;
  }

  if (marketplaceConfigTestButton) {
    marketplaceConfigTestButton.disabled = true;
  }

  try {
    const result = await desktopApiState.api.settings.testCurseForgeConnection();
    const diagnostics = result?.diagnostics || {};
    if (result?.ok) {
      showToast(`CurseForge browsing test passed (${diagnostics.mode || "configured"}).`);
    } else {
      showToast(getCurseForgeTestFailureMessage(result));
    }
    renderMarketplaceSettings(await desktopApiState.api.settings.getMarketplaceConfig());
    renderCurseForgeDiagnostics(diagnostics);
  } catch (error) {
    showToast(error?.message || "CurseForge diagnostics failed.");
  } finally {
    if (marketplaceConfigTestButton) {
      marketplaceConfigTestButton.disabled = false;
    }
  }
}

function getCurseForgeTestFailureMessage(result = {}) {
  const diagnostics = result?.diagnostics || {};
  const errorCode = result?.error?.code || diagnostics.errorCode || "unknown";
  if (diagnostics.agentReachable === false) {
    return "CurseForge test failed: selected Agent is unreachable.";
  }
  if (diagnostics.configured === false) {
    return "CurseForge test failed: no API key is configured for the selected Agent.";
  }
  if (diagnostics.apiConnectivity === "failed") {
    return `CurseForge API test failed: ${errorCode}.`;
  }
  if (diagnostics.cdnAuthenticationConnectivity === "failed") {
    return `CurseForge CDN authentication test failed: ${errorCode}.`;
  }
  return `CurseForge test failed: ${errorCode}.`;
}

async function testAgentConnection(options = {}) {
  if (agentConnectionTestInFlight) {
    return;
  }

  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasSettings) {
    if (!options.silent) {
      showToast("Agent connection test is unavailable.");
    }
    return;
  }

  agentConnectionTestInFlight = true;
  setAgentActionButtonsDisabled(true);
  setAgentConnectionDisplay("testing", "Checking the Agent health endpoint...");

  try {
    const result = await desktopApiState.api.settings.testAgentConnection(getAgentSettingsFormValues());
    const fingerprintText = result?.fingerprint ? ` Fingerprint: ${result.fingerprint}.` : "";
    setAgentConnectionDisplay(
      result?.connected ? "connected" : result?.status === "token-mismatch" ? "error" : "disconnected",
      `${result?.message || "Agent unavailable."}${fingerprintText}`,
      { repairAvailable: result?.repairAvailable === true || result?.status === "token-mismatch" },
    );

    if (!options.silent) {
      showToast(result?.connected ? "Agent connected." : result?.repairAvailable ? "Agent token mismatch. Use Repair Connection." : "Agent unavailable.");
    }
    if (getActivePageName() === "agent-control") {
      await refreshAgentControl({ includeConfig: false });
    }
  } catch {
    setAgentConnectionDisplay("disconnected", "Agent unavailable.");

    if (!options.silent) {
      showToast("Agent unavailable.");
    }
  } finally {
    agentConnectionTestInFlight = false;
    setAgentActionButtonsDisabled(agentSettingsRequestInFlight);
  }
}

async function pairAgentFromSettings() {
  const desktopApiState = getDesktopApiState();
  const code = String(agentPairingCodeInput?.value || "").trim();
  if (!desktopApiState.hasSettings || typeof desktopApiState.api.settings.pairAgent !== "function") {
    showToast("Agent pairing is unavailable in this build.");
    return;
  }
  if (!code) {
    showToast("Paste an Agent pairing code first.");
    agentPairingCodeInput?.focus();
    return;
  }
  agentSettingsRequestInFlight = true;
  setAgentActionButtonsDisabled(true);
  try {
    const response = await desktopApiState.api.settings.pairAgent({ code });
    if (agentPairingCodeInput) agentPairingCodeInput.value = "";
    renderAgentSettings(response);
    const fingerprint = response?.pairing?.fingerprint || response?.tokenStatus?.fingerprint || null;
    showToast(`Agent paired${fingerprint ? ` (${fingerprint})` : ""}.`);
    await testAgentConnection({ silent: true });
    await refreshAgentControl({ includeConfig: false });
  } catch (error) {
    const message = normalizeIpcErrorMessage(error, "Agent pairing failed.");
    if (getAgentErrorCode(error) === "PAIRING_CODE_INVALID" || isExpiredPairingError(error, message)) {
      if (agentPairingCodeInput) agentPairingCodeInput.value = "";
    }
    setAgentConnectionDisplay("error", message, { repairAvailable: true });
    showToast(message);
  } finally {
    agentSettingsRequestInFlight = false;
    setAgentActionButtonsDisabled(false);
  }
}

function focusAgentPairingRepair() {
  showPage("agent-control");
  agentPairingCodeInput?.focus();
  setAgentConnectionDisplay("error", "Open Agent setup on that machine, generate a temporary pairing code, paste it here, then select Pair Agent.", { repairAvailable: true });
}

function setAboutFields(info) {
  aboutFields.forEach((field) => {
    const value = info?.[field.dataset.aboutField];
    field.textContent = value || "Unavailable";
  });
}

function getDeveloperBadgeLabel(state = developerUpdateState) {
  if (developerUpdateBusy && state?.status !== "updating") return "Checking Dev…";
  if (state?.status === "available") return "Dev Update Available";
  if (state?.status === "updating") return "Updating Dev…";
  if (state?.status === "restart-required" || state?.restartRequired) return "Restart Required";
  if (state?.status === "error") return "Dev Update Error";
  if (!state?.eligible && state?.status === "checking") return "Checking Dev…";
  return "Developer Mode";
}

function formatDevUpdateTime(value) {
  return value ? formatDateTime(value) : "Not checked yet";
}

function getDeveloperUpdateUnavailableMessage(state = developerUpdateState) {
  if (state?.error === "packaged") return "Developer Update is only available from an unpackaged Electron dev checkout.";
  if (state?.errorCode === "DEV_SOURCE_DIRTY_WORKTREE") return "Local changes detected. Your development checkout contains uncommitted changes. Dev Update will not overwrite them.";
  if (state?.errorCode === "DEV_SOURCE_DIVERGED") return "Development branch has diverged. Automatic source update is unavailable because local commits differ from origin/dev.";
  if (state?.errorCode === "DEV_SOURCE_BRANCH_MISMATCH") return `Dev Update requires the dev branch. Current branch: ${state?.branch || "unknown"}.`;
  if (state?.error === "not-git-worktree") return "Developer Update needs to run from a Git checkout.";
  if (state?.error === "not-dev-branch") return "Developer Update only tracks the dev branch.";
  return state?.error || "Developer Update is unavailable in this checkout.";
}

function renderDevelopmentBadge(state = developerUpdateState) {
  if (!developmentBadge) {
    return;
  }
  const visible = Boolean(canUseSettingsCapability("canManageDeveloperSettings") && state?.eligible && state?.available !== false);
  const label = getDeveloperBadgeLabel(state);
  developmentBadge.hidden = !visible;
  developmentBadge.dataset.devState = state?.status || "up-to-date";
  developmentBadge.title = visible ? "Open Developer Update status" : "";
  developmentBadge.setAttribute("aria-label", visible ? `${label}. Open Developer Update status.` : "Developer Update status");
  if (developmentBadgeLabel) {
    developmentBadgeLabel.textContent = label;
  }
}

function setDevUpdateModalVisible(isVisible) {
  if (!devUpdateModal) return;
  devUpdateModal.hidden = !isVisible;
  if (isVisible && !devUpdateModalCleanup) {
    devUpdateModalCleanup = activateModal(devUpdateModal, { initialFocus: () => devUpdateButtons[0] });
  } else if (!isVisible && devUpdateModalCleanup) {
    devUpdateModalCleanup();
    devUpdateModalCleanup = null;
  }
}

function setDevUpdateField(name, value) {
  devUpdateFields.forEach((field) => {
    if (field.dataset.devUpdateField === name) {
      field.textContent = value || "Unavailable";
    }
  });
}

function renderDeveloperUpdateModal(state = developerUpdateState) {
  const behind = Number(state?.behind || 0);
  const ahead = Number(state?.ahead || 0);
  const blocked = state?.status === "blocked" || Boolean(state?.errorCode);
  if (devUpdateMessage) {
    devUpdateMessage.textContent = state?.status === "available"
      ? `${behind} new development commit${behind === 1 ? "" : "s"} available.`
      : state?.status === "updating"
        ? "Updating source..."
        : state?.status === "fetching"
          ? "Fetching origin/dev..."
          : state?.status === "installing-app-dependencies"
            ? "Installing application dependencies from the committed lockfile..."
            : state?.status === "installing-agent-dependencies"
              ? "Installing Agent dependencies from the committed lockfile..."
              : state?.status === "validating-update"
                ? "Validating updated source..."
                : state?.status === "restarting"
                  ? "Restarting development application..."
        : state?.status === "restart-required" || state?.restartRequired
          ? "Source updated successfully. Restart AnxOS to load the new source."
          : blocked
            ? getDeveloperUpdateUnavailableMessage(state)
          : state?.status === "error"
            ? state?.error || "Developer update check failed."
            : !state?.eligible || state?.available === false
              ? getDeveloperUpdateUnavailableMessage(state)
              : "This dev checkout is up to date.";
  }
  setDevUpdateField("mode", state?.mode === "source-dev" ? "Development Source" : state?.mode === "packaged-dev" ? "Packaged Developer Update" : "Developer Update");
  setDevUpdateField("branch", state?.branch);
  setDevUpdateField("expectedBranch", state?.expectedBranch || "dev");
  setDevUpdateField("localCommit", state?.localCommit);
  setDevUpdateField("remoteCommit", state?.remoteCommit);
  setDevUpdateField("sync", `${behind} behind / ${ahead} ahead`);
  setDevUpdateField("latestCommitMessage", state?.latestCommitMessage);
  setDevUpdateField("lastCheckedAt", formatDevUpdateTime(state?.lastCheckedAt));
  const detailParts = [];
  if (Array.isArray(state?.dependencyScopes) && state.dependencyScopes.length) detailParts.push(`Dependencies: ${state.dependencyScopes.join(", ")}`);
  else if (state?.status === "available" || state?.status === "restart-required") detailParts.push("Dependencies unchanged");
  if (Array.isArray(state?.changedFiles) && state.changedFiles.length) {
    detailParts.push(`${state.changedFiles.length} changed file${state.changedFiles.length === 1 ? "" : "s"}`);
  }
  if (Array.isArray(state?.details) && state.details.length) detailParts.push(state.details.join(" · "));
  setDevUpdateField("details", detailParts.join(" · ") || "Unavailable");
  devUpdateButtons.forEach((button) => {
    const action = button.dataset.devUpdateAction;
    if (action === "update") {
      const restartRequired = state?.status === "restart-required" || state?.restartRequired;
      button.disabled = developerUpdateBusy || blocked || (!restartRequired && behind <= 0);
      button.textContent = restartRequired ? "Restart Now" : developerUpdateBusy ? "Updating..." : "Update Now";
    } else if (action === "check" || action === "changes") {
      button.disabled = developerUpdateBusy || (action === "changes" && !state?.remoteCommit);
    }
  });
}

async function refreshDeveloperUpdateState(options = {}) {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasDeveloperUpdates || !canUseSettingsCapability("canManageDeveloperSettings")) {
    developerUpdateState = null;
    renderDevelopmentBadge(null);
    return null;
  }

  developerUpdateBusy = true;
  if (developerUpdateState?.eligible) {
    renderDevelopmentBadge({ ...developerUpdateState, status: "checking", available: true });
  }
  try {
    const state = options.check === false
      ? await desktopApiState.api.developerUpdates.getState()
      : await desktopApiState.api.developerUpdates.check({ fetch: options.fetch !== false });
    developerUpdateState = state;
    renderDevelopmentBadge(state);
    renderDeveloperUpdateModal(state);
    return state;
  } catch (error) {
    developerUpdateState = { ...(developerUpdateState || {}), eligible: true, available: true, status: "error", error: normalizeIpcErrorMessage(error, "Developer update check failed.") };
    renderDevelopmentBadge(developerUpdateState);
    renderDeveloperUpdateModal(developerUpdateState);
    return developerUpdateState;
  } finally {
    developerUpdateBusy = false;
    renderDevelopmentBadge(developerUpdateState);
    renderDeveloperUpdateModal(developerUpdateState);
  }
}

async function openDeveloperUpdateModal() {
  if (!canUseSettingsCapability("canManageDeveloperSettings")) {
    showToast("Owner access is required for Developer Update.");
    return;
  }
  await refreshDeveloperUpdateState({ fetch: false });
  renderDeveloperUpdateModal(developerUpdateState);
  setDevUpdateModalVisible(true);
}

async function runDeveloperUpdateAction(action) {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasDeveloperUpdates || developerUpdateBusy || !canUseSettingsCapability("canManageDeveloperSettings")) return;
  if (action === "dismiss") {
    setDevUpdateModalVisible(false);
    return;
  }

  developerUpdateBusy = true;
  if (action === "update") {
    developerUpdateState = { ...(developerUpdateState || {}), status: "updating", eligible: true, available: true };
  }
  renderDevelopmentBadge(developerUpdateState);
  renderDeveloperUpdateModal(developerUpdateState);
  try {
    if (action === "check") developerUpdateState = await desktopApiState.api.developerUpdates.check({ fetch: true });
    else if (action === "changes") await desktopApiState.api.developerUpdates.openChanges();
    else if (action === "update") {
      if (developerUpdateState?.status === "restart-required" || developerUpdateState?.restartRequired) {
        await desktopApiState.api.developerUpdates.restart();
        return;
      }
      developerUpdateState = await desktopApiState.api.developerUpdates.update();
    }
    renderDevelopmentBadge(developerUpdateState);
    renderDeveloperUpdateModal(developerUpdateState);
  } catch (error) {
    developerUpdateState = { ...(developerUpdateState || {}), status: "error", error: normalizeIpcErrorMessage(error, "Developer update failed.") };
    renderDevelopmentBadge(developerUpdateState);
    renderDeveloperUpdateModal(developerUpdateState);
    showToast(developerUpdateState.error, "error");
  } finally {
    developerUpdateBusy = false;
    renderDevelopmentBadge(developerUpdateState);
    renderDeveloperUpdateModal(developerUpdateState);
  }
}

async function loadRuntimeInfo() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasApp) {
    setAboutFields(null);
    return;
  }

  try {
    const info = await desktopApiState.api.app.getRuntimeInfo();
    runtimeInfoState = info;
    setAboutFields(info);
    renderRoutingDiagnostics();
    refreshNodeHealth({ notify: false });
  } catch {
    setAboutFields(null);
  }
}

function renderRoutingDiagnostics() {
  const visible = Boolean(runtimeInfoState?.developmentMode && runtimeInfoState?.trustedDevelopmentMode && runtimeInfoState?.isPackaged === false);
  if (routingDiagnostics) routingDiagnostics.hidden = !visible;
  if (!visible) return;
  const node = getSelectedNode();
  const target = getFilesConnectionTarget();
  const values = {
    applicationHost: `${nodesState.applicationHost?.displayName || nodesState.applicationHost?.hostname || "Application Host"} · ${nodesState.applicationHost?.operatingSystem || "Unknown OS"}`,
    selectedNode: `${node?.displayName || "Unavailable"} · ${node?.kind || "unknown"}`,
    agentId: node?.kind === "agent" ? node.agentIdentity?.deviceId || "Unavailable" : "None",
    nodeId: node?.id || "Unavailable",
    executionTarget: node?.executionTarget?.type || node?.kind || "Unavailable",
    filesystemProvider: target?.label || "None selected",
    providerType: target?.providerType || "None",
    routingTarget: target?.key || node?.executionTarget?.type || "Unavailable",
  };
  routingDiagnosticFields.forEach((field) => { field.textContent = values[field.dataset.routingDiagnostic] || "Unavailable"; });
}

function formatUpdateBytes(value) {
  const bytes = Number(value || 0);

  if (!Number.isFinite(bytes) || bytes <= 0) {
    return "0 B";
  }

  const units = ["B", "KB", "MB", "GB"];
  let size = bytes;
  let unitIndex = 0;

  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex += 1;
  }

  return `${size >= 10 || unitIndex === 0 ? Math.round(size) : size.toFixed(1)} ${units[unitIndex]}`;
}

function setUpdateStatusMessage(message) {
  if (updateStatusMessage) {
    updateStatusMessage.textContent = message;
  }
  if (updateAboutStatus) {
    updateAboutStatus.textContent = message;
  }
}

function setUpdateModalVisible(isVisible) {
  if (!updateModal) {
    return;
  }

  updateModal.hidden = !isVisible;
  if (isVisible && !updateModalCleanup) {
    updateModalCleanup = activateModal(updateModal, { initialFocus: () => updatePrimaryButton });
  } else if (!isVisible && updateModalCleanup) {
    updateModalCleanup();
    updateModalCleanup = null;
  }
}

function renderUpdateProgress(progress = null) {
  if (!updateProgress || !updateProgressFill || !updateProgressText) {
    return;
  }

  if (!progress) {
    updateProgress.hidden = true;
    updateProgressFill.style.width = "0%";
    updateProgressText.textContent = "Preparing download...";
    return;
  }

  updateProgress.hidden = false;
  const percent = Number.isFinite(progress.percent) ? Math.max(0, Math.min(progress.percent, 100)) : null;
  updateProgressFill.style.width = `${percent || 8}%`;
  const received = formatUpdateBytes(progress.receivedBytes);
  const total = progress.totalBytes ? formatUpdateBytes(progress.totalBytes) : "unknown size";
  updateProgressText.textContent = percent === null ? `${received} downloaded of ${total}.` : `${percent}% downloaded (${received} of ${total}).`;
}

function sanitizeMarkdownText(value) {
  return String(value || "").replace(/[<>&]/g, (char) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;" }[char]));
}

function renderMarkdownLite(markdown = "") {
  const lines = String(markdown || "").split(/\r?\n/);
  const output = [];
  let inList = false;
  let inCode = false;
  const closeList = () => {
    if (inList) {
      output.push("</ul>");
      inList = false;
    }
  };
  lines.forEach((line) => {
    const text = line.trim();
    if (text.startsWith("```")) {
      closeList();
      output.push(inCode ? "</code></pre>" : "<pre><code>");
      inCode = !inCode;
      return;
    }
    if (inCode) {
      output.push(`${sanitizeMarkdownText(line)}\n`);
      return;
    }
    if (!text) {
      closeList();
      return;
    }
    if (/^#{1,3}\s+/.test(text)) {
      closeList();
      const level = Math.min(text.match(/^#+/)?.[0].length || 3, 3);
      output.push(`<h${level + 2}>${sanitizeMarkdownText(text.replace(/^#{1,3}\s+/, ""))}</h${level + 2}>`);
      return;
    }
    if (/^[-*]\s+/.test(text)) {
      if (!inList) {
        output.push("<ul>");
        inList = true;
      }
      output.push(`<li>${sanitizeMarkdownText(text.replace(/^[-*]\s+/, ""))}</li>`);
      return;
    }
    closeList();
    output.push(`<p>${sanitizeMarkdownText(text).replace(/`([^`]+)`/g, "<code>$1</code>").replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2" target="_blank" rel="noreferrer">$1</a>')}</p>`);
  });
  closeList();
  if (inCode) output.push("</code></pre>");
  return output.join("");
}

function formatUpdateDate(value) {
  if (!value) return "Unavailable";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

function getUpdateModeFromState(state = updateUiState) {
  if (state?.status === "downloaded") return "downloaded";
  if (state?.status === "downloading" || state?.downloadInFlight) return "downloading";
  if (state?.status === "error") return "error";
  if (state?.status === "up-to-date") return "up-to-date";
  if (state?.status === "unavailable") return "unavailable";
  return "available";
}

function isUpdateDownloadBlocked(state = updateUiState) {
  return /not publicly downloadable|HTTP (401|403|404)|release asset/i.test(String(state?.error || ""));
}

function renderUpdateSurfaces(state = updateUiState) {
  const update = state?.latest || latestUpdateInfo || {};
  const hasUpdate = Boolean(update?.hasUpdate && !update?.skipped);
  const isReady = state?.status === "downloaded" && Boolean(state?.downloadedPath || downloadedUpdatePath);
  const latestVersion = update.latestVersion || "Unavailable";
  latestUpdateInfo = update?.hasUpdate ? update : latestUpdateInfo;
  downloadedUpdatePath = state?.downloadedPath || downloadedUpdatePath;
  updateDownloadInFlight = Boolean(state?.downloadInFlight || state?.status === "downloading");
  updateCheckInFlight = Boolean(state?.checkInFlight);

  if (updateLatestAbout) updateLatestAbout.textContent = latestVersion;
  if (updateLastCheck) updateLastCheck.textContent = state?.lastCheckedAt ? formatDateTime(state.lastCheckedAt) : "Not checked yet";
  if (updateSidebarBadge) {
    updateSidebarBadge.hidden = !hasUpdate;
    updateSidebarBadge.textContent = isReady ? "Ready" : "Update";
  }
  if (updateReadyBanner) {
    updateReadyBanner.hidden = !isReady;
  }
  updateInstallButtons.forEach((button) => {
    const canInstallUpdate = canUseSettingsCapability("canManageInternalUpdates");
    button.hidden = !isReady || !canInstallUpdate;
    button.disabled = !isReady || !canInstallUpdate;
  });

  if (state?.status === "up-to-date") setUpdateStatusMessage("You're up to date.");
  else if (state?.status === "available") setUpdateStatusMessage(`Update ${latestVersion} is available.`);
  else if (state?.status === "downloading") setUpdateStatusMessage("Downloading update...");
  else if (state?.status === "downloaded") setUpdateStatusMessage("Update ready to install.");
  else if (state?.status === "error") setUpdateStatusMessage("Update failed.");
}

function renderUpdateModal(mode = getUpdateModeFromState()) {
  const update = latestUpdateInfo || {};
  const latestVersion = update.latestVersion || "newer build";
  const currentVersion = update.currentVersion || "current build";

  if (updateTitle) {
    updateTitle.textContent = mode === "downloaded"
      ? "Ready to Install"
      : mode === "downloading"
        ? "Downloading Update"
        : mode === "up-to-date"
          ? "You're Up to Date"
          : mode === "unavailable"
            ? "Update Check Unavailable"
            : mode === "error"
              ? "Update Check Failed"
              : "New Version Available";
  }

  if (updateMessage) {
    if (mode === "downloading") {
      updateMessage.textContent = "Downloading the update. You can keep using AnxOS while this finishes.";
    } else if (mode === "downloaded") {
      updateMessage.textContent = "The update is ready. Restart now to finish installing.";
    } else if (mode === "up-to-date") {
      updateMessage.textContent = "This AnxOS Control Center build is the latest available version.";
    } else if (mode === "unavailable") {
      updateMessage.textContent = update.message || "AnxOS could not find a published update release.";
    } else if (mode === "error") {
      updateMessage.textContent = isUpdateDownloadBlocked()
        ? "AnxOS found the update, but the update file is not publicly downloadable by the app. Open the download in your browser to install it manually."
        : updateUiState?.error || "The update could not be downloaded.";
    } else {
      updateMessage.textContent = "A newer AnxOS Control Center build is available.";
    }
  }

  if (updateCurrentVersion) {
    updateCurrentVersion.textContent = currentVersion;
  }

  if (updateLatestVersion) {
    updateLatestVersion.textContent = latestVersion;
  }
  if (updateReleaseDate) {
    updateReleaseDate.textContent = formatUpdateDate(update.releaseDate || update.publishedAt);
  }
  if (updateReleaseNotes) {
    updateReleaseNotes.hidden = !update.releaseNotes;
    updateReleaseNotes.innerHTML = update.releaseNotes ? renderMarkdownLite(update.releaseNotes) : "";
    updateReleaseNotes.querySelectorAll("a[href]").forEach((link) => {
      link.addEventListener("click", (event) => {
        event.preventDefault();
        window.open(link.href, "_blank", "noopener,noreferrer");
      });
    });
  }

  if (updatePrimaryButton) {
    updatePrimaryButton.disabled = mode === "downloading";
    updatePrimaryButton.textContent = mode === "downloaded"
      ? "Restart Now"
      : mode === "downloading"
        ? "Downloading..."
        : mode === "error"
          ? isUpdateDownloadBlocked()
            ? "Retry Download"
            : "Retry"
          : mode === "up-to-date" || mode === "unavailable"
            ? "Close"
            : "Download & Install";
  }

  if (updateOpenDownloadButton) {
    updateOpenDownloadButton.hidden = !(mode === "error" && isUpdateDownloadBlocked() && update?.asset?.downloadUrl);
  }

  document.querySelectorAll('[data-update-action="skip"]').forEach((button) => {
    button.hidden = mode === "up-to-date" || mode === "unavailable" || mode === "error";
  });

  if (mode !== "downloading") {
    renderUpdateProgress(null);
  }

  setUpdateModalVisible(true);
}

function handleUpdateStatus(payload = {}) {
  updateUiState = payload.state || updateUiState;
  if (payload.type === "available") {
    updateCheckInFlight = false;
    if (updateUiState) updateUiState.checkInFlight = false;
    latestUpdateInfo = payload.update || latestUpdateInfo;
    downloadedUpdatePath = null;
    renderUpdateSurfaces(updateUiState);
    if (payload.notify) renderUpdateModal("available");
    return;
  }

  if (payload.type === "download-started") {
    updateDownloadInFlight = true;
    latestUpdateInfo = payload.update || latestUpdateInfo;
    activeUpdateOperationId = activeUpdateOperationId || startOperation({
      type: "Updates",
      title: "Download application update",
      target: latestUpdateInfo?.latestVersion || "Latest release",
      step: "Download started.",
      percent: 0,
    });
    setUpdateStatusMessage("Downloading update...");
    renderUpdateSurfaces(updateUiState);
    renderUpdateModal("downloading");
    renderUpdateProgress({ receivedBytes: 0, totalBytes: latestUpdateInfo?.asset?.size || 0, percent: 0 });
    return;
  }

  if (payload.type === "download-progress") {
    if (updateUiState) updateUiState.progress = payload.progress || updateUiState.progress;
    updateOperation(activeUpdateOperationId, {
      percent: payload.progress?.percent,
      step: Number.isFinite(payload.progress?.receivedBytes) && Number.isFinite(payload.progress?.totalBytes)
        ? `${formatBytes(payload.progress.receivedBytes)} of ${formatBytes(payload.progress.totalBytes)}`
        : "Downloading update.",
    });
    renderUpdateSurfaces(updateUiState);
    renderUpdateProgress(payload.progress || null);
    return;
  }

  if (payload.type === "downloaded") {
    updateDownloadInFlight = false;
    if (updateUiState) {
      updateUiState.status = "downloaded";
      updateUiState.downloadInFlight = false;
      updateUiState.downloadedPath = payload.path || updateUiState.downloadedPath || null;
    }
    downloadedUpdatePath = payload.path || null;
    finishOperation(activeUpdateOperationId, true, "Update downloaded.");
    activeUpdateOperationId = null;
    setUpdateStatusMessage("Update downloaded. Open it when you are ready.");
    renderUpdateSurfaces(updateUiState);
    renderUpdateModal("downloaded");
    return;
  }

  if (payload.type === "download-error") {
    updateDownloadInFlight = false;
    finishOperation(activeUpdateOperationId, false, payload.error || "Update download failed.");
    activeUpdateOperationId = null;
    setUpdateStatusMessage("Update download failed.");
    renderUpdateSurfaces(updateUiState);
    renderUpdateModal("error");
    return;
  }
  if (["checking", "not-available", "unavailable", "error", "skipped"].includes(payload.type)) {
    if (payload.type !== "checking") {
      updateCheckInFlight = false;
      if (updateUiState) updateUiState.checkInFlight = false;
    }
    renderUpdateSurfaces(updateUiState);
    if (payload.type === "error" && payload.notify) {
      renderUpdateModal("error");
    }
  }
}

async function checkForUpdates(options = {}) {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasUpdates || updateCheckInFlight) {
    if (!options.silent && !desktopApiState.hasUpdates) {
      showToast("Updates are unavailable in this build.");
    }
    return null;
  }

  updateCheckInFlight = true;
  const operationId = options.silent ? null : startOperation({
    type: "Updates",
    title: "Check for application updates",
    step: "Contacting update service.",
  });
  let operationError = "";
  setUpdateStatusMessage("Checking for updates...");

  try {
    const result = await desktopApiState.api.updates.check({ silent: Boolean(options.silent) });
    latestUpdateInfo = result?.hasUpdate ? result : latestUpdateInfo;
    if (result?.state) {
      updateUiState = result.state;
      renderUpdateSurfaces(updateUiState);
    }

    if (result?.releaseUnavailable) {
      setUpdateStatusMessage(result.message || "No update release is published yet.");

      if (!options.silent) {
        showToast(result.message || "No update release is published yet.", "warning");
      }
    } else if (result?.error) {
      operationError = result.error;
      updateUiState = {
        ...(updateUiState || {}),
        status: "error",
        error: result.error,
        latest: latestUpdateInfo,
      };
      setUpdateStatusMessage("Update check failed.");

      if (!options.silent) {
        renderUpdateSurfaces(updateUiState);
        renderUpdateModal("error");
      }
    } else if (result?.hasUpdate) {
      setUpdateStatusMessage(`Update ${result.latestVersion || ""} is available.`);
      if (!result.skipped) renderUpdateModal("available");
    } else if (!options.silent) {
      latestUpdateInfo = result || latestUpdateInfo;
      updateUiState = {
        ...(updateUiState || {}),
        status: "up-to-date",
        latest: result || latestUpdateInfo,
        lastCheckedAt: new Date().toISOString(),
      };
      setUpdateStatusMessage("You are running the latest available version.");
      renderUpdateSurfaces(updateUiState);
      renderUpdateModal("up-to-date");
    } else {
      setUpdateStatusMessage("Updates check automatically on startup.");
    }

    return result;
  } catch (error) {
    console.error("[Updates] Renderer check failed.", error);
    operationError = error?.message || "Update check failed.";
    setUpdateStatusMessage("Update check failed.");

    if (!options.silent) {
      showToast("Update check failed.");
    }

    return null;
  } finally {
    if (operationId) {
      finishOperation(operationId, !operationError, operationError || "Update check finished.");
    }
    updateCheckInFlight = false;
  }
}

async function downloadUpdate() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasUpdates || updateDownloadInFlight) {
    return;
  }

  if (downloadedUpdatePath) {
    await desktopApiState.api.updates.install?.();
    return;
  }

  updateDownloadInFlight = true;
  activeUpdateOperationId = startOperation({
    type: "Updates",
    title: "Download application update",
    target: latestUpdateInfo?.latestVersion || "Latest release",
    step: "Starting download.",
  });
  renderUpdateModal("downloading");

  try {
    const result = await desktopApiState.api.updates.download();

    if (result?.downloaded) {
      downloadedUpdatePath = result.path || null;
      updateUiState = result.state || updateUiState;
      finishOperation(activeUpdateOperationId, true, "Update downloaded.");
      activeUpdateOperationId = null;
      renderUpdateSurfaces(updateUiState);
      renderUpdateModal("downloaded");
    } else if (!result?.downloading) {
      updateUiState = {
        ...(result?.state || updateUiState || {}),
        status: "error",
        error: result?.error || result?.message || "Update download failed.",
        latest: result?.state?.latest || latestUpdateInfo,
      };
      setUpdateStatusMessage(updateUiState.error);
      finishOperation(activeUpdateOperationId, false, updateUiState.error);
      activeUpdateOperationId = null;
      renderUpdateSurfaces(updateUiState);
      renderUpdateModal("error");
    }
  } catch (error) {
    console.error("[Updates] Renderer download failed.", error);
    updateUiState = {
      ...(updateUiState || {}),
      status: "error",
      error: error?.message || "Update download failed.",
      latest: latestUpdateInfo,
    };
    setUpdateStatusMessage(updateUiState.error);
    finishOperation(activeUpdateOperationId, false, updateUiState.error);
    activeUpdateOperationId = null;
    renderUpdateSurfaces(updateUiState);
    renderUpdateModal("error");
  } finally {
    updateDownloadInFlight = false;
  }
}

async function installUpdate() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasUpdates) return;
  if (!canUseSettingsCapability("canManageInternalUpdates")) {
    showToast("Owner access is required to install application updates.");
    return;
  }
  try {
    await (desktopApiState.api.updates.install ? desktopApiState.api.updates.install() : desktopApiState.api.updates.openDownloaded());
  } catch {
    showToast("Update installer could not be opened.");
  }
}

async function skipUpdateVersion() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasUpdates || !latestUpdateInfo?.latestVersion) return;
  updateUiState = await desktopApiState.api.updates.skip?.(latestUpdateInfo.latestVersion);
  setUpdateModalVisible(false);
  renderUpdateSurfaces(updateUiState);
  showToast(`Skipped ${latestUpdateInfo.latestVersion}.`);
}

async function openUpdateRelease() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasUpdates) {
    return;
  }

  try {
    await desktopApiState.api.updates.openRelease();
  } catch {
    showToast("Release page could not be opened.");
  }
}

async function openUpdateDownload() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasUpdates) return;

  try {
    if (typeof desktopApiState.api.updates.openDownload === "function") {
      await desktopApiState.api.updates.openDownload();
    } else {
      await desktopApiState.api.updates.openRelease();
    }
  } catch {
    showToast("Update download page could not be opened.");
  }
}

function setupUpdates() {
  const desktopApiState = getDesktopApiState();

  if (!desktopApiState.hasUpdates) {
    setUpdateStatusMessage("Updates are unavailable in this build.");
    return;
  }

  desktopApiState.api.updates.onStatus(handleUpdateStatus);
  desktopApiState.api.updates.getState?.().then((state) => {
    updateUiState = state;
    latestUpdateInfo = state?.latest || latestUpdateInfo;
    renderUpdateSurfaces(state);
    if (state?.status === "available" && state?.latest?.hasUpdate && !state?.latest?.skipped) {
      renderUpdateModal("available");
    } else if (state?.status === "downloaded") {
      renderUpdateModal("downloaded");
    }
  }).catch(() => {});
}

function setupDeveloperUpdates() {
  const desktopApiState = getDesktopApiState();
  if (!desktopApiState.hasDeveloperUpdates) {
    renderDevelopmentBadge(null);
    return;
  }
  refreshDeveloperUpdateState({ fetch: true }).catch(() => {});
}

