agentRemoteList?.addEventListener("click", async (event) => {
  const selectButton = event.target.closest("[data-remote-agent-select]");
  if (selectButton) {
    const nodeId = selectButton.dataset.remoteAgentSelect || "";
    if (nodeId) {
      await selectNode(nodeId);
    }
    return;
  }
  const button = event.target.closest("[data-remote-agent-diagnostics]");
  if (!button) return;
  const nodeId = button.dataset.remoteAgentDiagnostics || "";
  const lastCapturedAt = remoteDiagnosticsLastCapturedAt.get(nodeId) || 0;
  if (!nodeId || remoteDiagnosticsInFlight.has(nodeId)) {
    return;
  }
  if (Date.now() - lastCapturedAt < 30000) {
    showToast("Remote diagnostics were just captured.", "info");
    return;
  }
  button.disabled = true;
  remoteDiagnosticsInFlight.add(nodeId);
  try {
    const result = await getDesktopApiState().api.agentControl.remoteDiagnostics(nodeId);
    remoteDiagnosticsLastCapturedAt.set(nodeId, Date.now());
    showToast(result?.cached ? "Recent remote diagnostics already available." : "Remote diagnostics captured.", "success");
  }
  catch (error) { showToast(normalizeIpcErrorMessage(error, "Remote diagnostics failed."), "error"); }
  finally {
    remoteDiagnosticsInFlight.delete(nodeId);
    button.disabled = false;
  }
});
agentDiagnosticsList?.addEventListener("click", (event) => {
  const action = event.target.closest("[data-agent-repair]")?.dataset.agentRepair;
  if (action === "start") runAgentControlAction("start");
  if (action === "install-service") runAgentControlAction("installService");
  if (action === "repair-local-agent") runAgentControlAction("stopOldLocalAgentAndRepair");
  if (action === "repair-pairing") runAgentControlAction("repairAgent");
  if (action === "repair-permissions") runAgentControlAction("repairAgent");
  if (action === "updateAgent") runAgentControlAction("updateAgent");
  if (action === "rescan-dependencies") { showPage("marketplace"); refreshMarketplaceDownloads(); }
  if (action === "select-port") agentConfigFields.forEach((field) => { if (field.dataset.agentConfig === "port") field.focus(); });
});
document.querySelectorAll("[data-diagnostics-action]").forEach((button) => button.addEventListener("click", async () => {
  button.disabled = true;
  const action = button.dataset.diagnosticsAction;
  try { await runDiagnosticsAction(action); }
  catch {}
  finally { button.disabled = false; }
}));
document.querySelector('[data-page="playit"]')?.addEventListener("click", async (event) => {
  const serviceCard = event.target.closest("[data-public-access-service-card]");
  if (serviceCard && !event.target.closest("[data-public-access-action]")) {
    selectedPublicAccessServiceId = serviceCard.dataset.publicAccessServiceCard || selectedPublicAccessServiceId;
    renderPublicAccessProviderDetails(latestPublicAccessSnapshot);
    return;
  }
  const button = event.target.closest("[data-public-access-action]");
  if (!button) return;
  button.disabled = true;
  try {
    await runPublicAccessAction(button.dataset.publicAccessAction);
  } catch (error) {
    showToast(normalizeIpcErrorMessage(error, "Public Access action failed."), "error");
  } finally {
    button.disabled = false;
  }
});
document.querySelector('[data-page="playit"]')?.addEventListener("keydown", (event) => {
  const serviceCard = event.target.closest("[data-public-access-service-card]");
  if (!serviceCard || !["Enter", " "].includes(event.key)) return;
  event.preventDefault();
  selectedPublicAccessServiceId = serviceCard.dataset.publicAccessServiceCard || selectedPublicAccessServiceId;
  renderPublicAccessProviderDetails(latestPublicAccessSnapshot);
});
backupActionButtons.forEach((button) => {
  button.addEventListener("click", async () => {
    const action = button.dataset.backupAction;
    const operationId = action === "refresh" ? null : startOperation({
      type: "Backups",
      title: {
        create: "Create backup",
        restore: "Restore backup",
        delete: "Delete backup",
        download: "Download backup",
        import: "Import backup",
      }[action] || "Run backup action",
      target: selectedInstanceId || "Selected instance",
      step: "Backup request started.",
    });
    try {
      if (action === "refresh") {
        await refreshBackups();
      } else if (action === "create") {
        await createBackupForInstance();
      } else if (action === "restore") {
        await restoreSelectedBackup();
      } else if (action === "delete") {
        await deleteSelectedBackup();
      } else if (action === "download") {
        await downloadSelectedBackup();
      } else if (action === "import") {
        await importBackupForInstance();
      }
      if (operationId) finishOperation(operationId, true, "Backup action completed.");
    } catch (error) {
      const message = normalizeIpcErrorMessage(error, "Backup action failed.");
      if (operationId) finishOperation(operationId, false, message);
      showToast(message, "error");
    }
  });
});
